var MIDTERM_202609 = [{"id":"law-m1","subject":"law","name":"法规 · 提分密训卷一","stats":{"单选":40,"多选":40,"判断":30,"案例":10},"questions":[{"id":"law-m1-0","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"企业计提法定公积金超过注册资本的（ ）之后，可不再提取。","options":["50%","30%","51%","25%"],"answer":"A","explain":"公司法定公积金累计额为公司注册资本的50%以上的，可以不再提取。"},{"id":"law-m1-1","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"根据《证券期货投资者适当性管理办法》，下列不属于专业投资者的是（ ）。","options":["经行业协会备案的私募基金管理人","经行业协会登记的期货公司子公司","证券公司的员工","经批准的财务公司"],"answer":"C","explain":"证券公司员工不属于专业投资者。专业投资者包括金融机构、经备案或登记的子公司、私募基金管理人等。"},{"id":"law-m1-2","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列选项中，属于《证券法》明文列示的证券公司操纵市场行为的是（ ）。","options":["将自营账户借给他人使用操作","在自己实际控制的账户之间进行证券交易，影响证券交易价格或者证券交易量","内幕信息的知情人员利用内幕信息买卖证券或者根据内幕信息建议他人买卖证券","假借他人名义或者个人名义开展自营业务"],"answer":"B","explain":"在自己实际控制的账户之间进行证券交易属于操纵市场行为。"},{"id":"law-m1-3","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列对我国《基金法》规定的基金份额持有人享有的权利描述，错误的是（ ）。","options":["按照规定要求召开基金份额持有人大会","查阅或者复制未公开披露的基金信息资料","参与分配清算后的剩余基金财产","分享基金财产收益"],"answer":"B","explain":"基金份额持有人有权查阅公开披露的基金信息资料，而非“未公开”的。"},{"id":"law-m1-4","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"关于跨越信息隔离墙管理的说法，正确的是（ ）。","options":["公开侧业务部门应当事先向跨境人员所属部门和合规部门提出申请，并经其审批同意","跨境人员在跨境活动结束且获取的内幕信息已公开或者不再具有重大影响后方可回填","跨境人员在跨境后不应泄露跨境期间知悉的内幕信息","证券公司无须对跨境人员的行为进行监督管理"],"answer":"B","explain":"跨境人员在跨境活动结束且内幕信息已公开或不再具有重大影响后方可回填。"},{"id":"law-m1-5","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列关于刚性兑付的相关规定，说法错误的是（ ）。","options":["资产管理产品的发行人或者管理人违反真实公允确定净值原则，对产品进行保本保收益，视为刚性兑付","资产管理产品的发行人或者管理人采取滚动发行等方式，实现产品保本保收益的，视为刚性兑付","资产管理产品不能如期兑付或者兑付困难时，发行或者管理该产品的金融机构自行筹集资金偿付或者委托其他机构代为偿付，不应视为刚性兑付","经认定存在刚性兑付行为的，应该区分存款类金融机构和非存款类持牌金融机构进行惩处"],"answer":"C","explain":"金融机构自行筹集资金偿付或委托其他机构代为偿付，视为刚性兑付。"},{"id":"law-m1-6","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"法律主体是法律关系的参与者，主要包括（ ）。","options":["权利、行为和义务","主体、客体和内容","物、人格和精神成果","自然人、组织和国家"],"answer":"D","explain":"法律主体主要包括自然人、组织和国家三类。"},{"id":"law-m1-7","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列不属于证券经纪业务禁止行为的是（ ）。","options":["向投资者介绍证券交易基本知识","与投资者约定分担投资损失","对客户证券买卖的收益作出承诺","违规委托证券经纪人以外的个人或者机构进行投资者招揽、服务活动"],"answer":"A","explain":"向投资者介绍证券交易基本知识是允许的，属于投资者教育。"},{"id":"law-m1-8","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列不属于监事会的职权的是（ ）。","options":["检查公司财务","提议召开临时股东会会议","向董事会会议提出提案","监督高级管理人员执行职务的行为"],"answer":"C","explain":"监事会向股东会会议提出提案，而非向董事会会议提出提案。"},{"id":"law-m1-9","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"财务顾问将申报文件报中国证监会审核期间，委托人和财务顾问终止委托协议的，财务顾问和委托人应当自终止之日起（ ）个工作日内向中国证监会报告。","options":["3","7","5","10"],"answer":"C","explain":"应当自终止之日起5个工作日内向中国证监会报告。"},{"id":"law-m1-10","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"按照《证券公司合规管理实施指引》的要求，某证券公司设立合规负责人王某，王某发现该证券公司2018年发生违法违规行为并且存在合规风险隐患，王某的下列做法错误的是（ ）。","options":["王某依照公司章程规定及时向董事会、经营管理主要负责人报告，提出处理意见，并督促整改","对于违规行为，王某督促该证券公司及时向证监会相关派出机构报告","对于该证券公司违反行业规范和自律规则的情况，王某只向证监会相关派出机构进行了报告","王某督促该证券公司进行专项检查"],"answer":"C","explain":"违反行业规范和自律规则的，还应当向有关自律组织报告，而非只向证监会报告。"},{"id":"law-m1-11","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"违法失信信息，在诚信档案中的效力期限为（ ），但因证券期货违法行为被行政处罚、市场禁入、刑事处罚和判决承担较大侵权、违约民事赔偿责任的信息，其效力期限为（ ）。","options":["3年；5年","3年；6年","2年；3年","2年；5年"],"answer":"A","explain":"违法失信信息效力期限为3年，特定严重信息效力期限为5年。"},{"id":"law-m1-12","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"法是调整人们的行为或社会关系的规范，具有规范性。下列关于法的规范性的体现，错误的是（ ）。","options":["规定了人们可以为或不为一定行为或者人们可以要求他人为或不为一定行为，体现了人们依法享有的权利","法所规定的权利和义务，仅指个人的权利和义务","规定了人们应当为一定行为或不得为一定行为，体现了人们依法应履行的义务","法所规定的权利和义务，不仅指个人的权利和义务，还包括国家机关及其公职人员在执行公务过程中的职权及相应职责"],"answer":"B","explain":"法所规定的权利和义务不仅指个人的，还包括国家机关及其公职人员的职权和职责。"},{"id":"law-m1-13","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"实现利润未达到预测金额（ ），中国证监会可以对上市公司、相关机构及其责任人员采取监管谈话、出具警示函、责令定期报告等监管措施。","options":["30%","40%","50%","60%"],"answer":"C","explain":"实现利润未达到预测金额50%的，可采取监管措施。"},{"id":"law-m1-14","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"以下关于证券公司证券投资顾问业务内部控制的说法，正确的是（ ）。","options":["禁止以任何方式承诺或保证投资收益","与客户签订证券投资顾问协议，按照公平、合理、自愿的原则，与客户协商并以书面或口头的方式约定费用收取安排","证券投资顾问服务费应当以公司账户或者个人账户收取","业务档案保存期限自协议开始之日起不得少于5年"],"answer":"A","explain":"证券公司禁止以任何方式承诺或保证投资收益。"},{"id":"law-m1-15","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券的发行、交易活动的当事人具有平等的法律地位，其行为准则不包括下列选项中的（ ）。","options":["自愿","有偿","无偿","诚实信用"],"answer":"C","explain":"证券发行、交易活动应遵循自愿、有偿、诚实信用的原则。"},{"id":"law-m1-16","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"关于证券公司开展经纪业务的相关规定，以下说法正确的是（ ）。","options":["证券公司向客户收取证券交易费用，应当符合国家有关规定，不需将收费项目、收费标准公示","证券公司可以委托证券公司以外的人员作为证券经纪人，代理其进行客户招揽、客户服务等活动","客户证券账户内的证券不足的，可以接受其卖出委托","客户资金账户内的资金不足的，可以接受其买入委托"],"answer":"B","explain":"证券公司可以委托证券公司以外的人员作为证券经纪人进行客户招揽和服务。"},{"id":"law-m1-17","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列关于股份有限公司设立的说法，正确的是（ ）。","options":["股份有限公司的设立，必须采取发起设立的方式","股份有限公司采取发起方式设立的，在发起人认购的股份缴足前，可以向他人募集股份","设立股份有限公司，应当有1人以上200人以下为发起人，其中应当有半数以上的发起人在中国境内有住所","设立股份有限公司，由董事会制定公司章程"],"answer":"C","explain":"设立股份有限公司，应当有1人以上200人以下为发起人，其中半数以上在中国境内有住所。"},{"id":"law-m1-18","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"在科创板创新交易机制中，下列关于科创板股票涨跌幅限制的说法，正确的是（ ）。","options":["科创板股票的涨跌幅限制为20%，新股上市后的前5个交易日不设涨跌幅限制","科创板股票的涨跌幅限制为10%，新股上市首日不设涨跌幅限制","科创板股票的涨跌幅限制为20%，新股上市首日不设涨跌幅限制","科创板股票的涨跌幅限制为10%，新股上市后的前5个交易日不设涨跌幅限制"],"answer":"A","explain":"科创板股票涨跌幅限制为20%，新股上市前5个交易日不设涨跌幅限制。"},{"id":"law-m1-19","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司合并、分立的，涉及客户权益的重大资产转让应当经具有证券相关业务资格的（ ）。","options":["资产评估机构评估","律师事务所核实","信用评级机构评级","会计师事务所验资"],"answer":"A","explain":"重大资产转让应当经具有证券相关业务资格的资产评估机构评估。"},{"id":"law-m1-20","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"按照《证券公司治理准则》的要求，关于证券公司与股东之间关系的特别规定，以下选项错误的是（ ）。","options":["证券公司的控股股东、实际控制人不得利用其控制地位或滥用权利损害公司客户的合法权益","证券公司的控股股东可以直接任免证券公司的董事、监事和高级管理人员","证券公司的股东、实际控制人不得违反公司章程的规定干预证券公司的经营管理活动","证券公司与其他关联方应当在业务等方面严格分开，各自独立经营、独立核算、独立承担责任和风险"],"answer":"B","explain":"控股股东不得直接任免董事、监事和高级管理人员，应通过股东会、董事会程序。"},{"id":"law-m1-21","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司、托管人、销售机构和投资顾问等服务机构违反法律、行政法规及中国证监会其他规定的，中国证监会及相关派出机构可以采取的措施不包括（ ）。","options":["责令改正","监管谈话","出具警示函","拘留"],"answer":"D","explain":"拘留不属于中国证监会的监管措施，由公安机关等行使。"},{"id":"law-m1-22","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列有关证券登记结算机构的说法中，错误的是（ ）。","options":["证券登记结算机构不得挪用客户的证券","投资者委托证券公司进行证券交易，应当通过证券公司申请在证券登记结算机构开立证券账户","在证券交易所或者国务院批准的其他全国性证券交易场所交易的证券，应当全部存管在证券交易所","证券登记结算机构应当妥善保存登记、存管和结算的原始凭证及有关文件资料，其保存期限不得少于20年"],"answer":"C","explain":"证券应当全部存管在证券登记结算机构，而非证券交易所。"},{"id":"law-m1-23","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"效力期限，自对违法失信行为的处理决定（ ）起算。","options":["生效之日","生效次日","执行完毕之日","执行完毕次日"],"answer":"C","explain":"效力期限自对违法失信行为的处理决定执行完毕之日起算。"},{"id":"law-m1-24","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"一家公司发行股票、债券进行筹资，下列（ ）行为构成欺诈发行证券罪。","options":["行为人在招股说明书、认股书、公司、企业债券募集办法中隐瞒重要事实或编造重大虚假内容，但尚未发行证券","行为人因过失制作了虚假招股说明书、认股书、公司、企业债券募集办法，且已经发行证券","行为人制作了虚假的招股说明书、认股书、公司、企业债券募集办法发行证券，并达到数量巨大、后果严重或者有其他严重情节","行为人制作并向社会发行了虚假招股说明书、认股书、公司、企业债券募集办法"],"answer":"C","explain":"欺诈发行证券罪要求既制作虚假文件又发行证券，且达到数额巨大、后果严重或有其他严重情节。"},{"id":"law-m1-25","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券金融公司充抵保证金的每种证券余额不得超过该证券总市值的（ ）。","options":["15%","20%","25%","10%"],"answer":"A","explain":"充抵保证金的每种证券余额不得超过该证券总市值的15%。"},{"id":"law-m1-26","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"公司提供担保的主要方式不包括（ ）。","options":["保证","抵押","质押","留置"],"answer":"D","explain":"公司提供担保的主要方式为保证、抵押、质押，不包括留置。"},{"id":"law-m1-27","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列关于证券公司反洗钱工作要求的说法中，错误的是（ ）。","options":["证券公司应当明确董事会、监事会、高级管理层和相关部门的反洗钱职责","证券公司及其分支机构负责人应当对反洗钱内部控制制度的有效实施负责","总部应当对分支机构执行反洗钱内部控制制度进行监督管理","反洗钱信息系统应当以业务部门为单位，覆盖所有业务和客户，及时、准确、完整采集和记录洗钱风险管理所需信息，对洗钱风险进行识别、评估、监测和报告"],"answer":"D","explain":"反洗钱信息系统应当以客户为单位，而非以业务部门为单位。"},{"id":"law-m1-28","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券在证券交易所上市交易，应当采用（ ）。","options":["公开的集中交易方式或者国务院证券监督管理机构批准的其他方式","做市商交易方式","集中竞价交易方式","公开的集中交易方式"],"answer":"A","explain":"证券在证券交易所上市交易，应当采用公开的集中交易方式或者国务院证券监督管理机构批准的其他方式。"},{"id":"law-m1-29","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券行业文化建设包括三大层次，不包括（ ）。","options":["行为层","组织层","观念层","理想层"],"answer":"D","explain":"证券行业文化建设三大层次为行为层、组织层、观念层。"},{"id":"law-m1-30","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"根据《证券公司治理准则》，下列关于证券公司与客户关系的基本原则的说法，错误的是（ ）。","options":["证券公司向客户提供的产品或者服务，对有关产品和服务的内容应履行保密","证券公司不得侵犯客户的财产权、选择权、公平交易权、知情权及其他合法权益","证券公司不得挪用客户交易结算资金、委托管理的资产及托管在公司的证券","证券公司应当设专职部门或者岗位负责与客户进行沟通，处理客户的投诉"],"answer":"A","explain":"证券公司对有关产品和服务的内容及风险应予以充分披露，而非保密。"},{"id":"law-m1-31","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列说法中正确的是（ ）。","options":["被动知悉内幕消息，可以向客户或投资者提供分析、预测或建议","预测证券市场、证券品种的走势或者就投资证券的可行性进行建议时需有充分的理由和依据，不得主观臆断","证券投资分析报告、投资分析文章等形式的咨询服务产品可以适当提及投资者在具体证券品种上进行具体价位买卖等方面的内容","证券投资咨询机构及其执业人员有权拒绝媒体对其所提供的稿件进行断章取义、做有损原意的删节和修改，并自提供之日起将其稿件以书面形式保存2年"],"answer":"B","explain":"预测证券市场走势需有充分理由和依据，不得主观臆断。"},{"id":"law-m1-32","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"股份有限公司的股东以其（ ）为限对公司的债务承担责任。","options":["全部财产","认缴的出资额","认购的股份","认缴的股份"],"answer":"C","explain":"股份有限公司的股东以其认购的股份为限对公司承担责任。"},{"id":"law-m1-33","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"按照《上市公司并购重组财务顾问业务管理办法》规定，财务顾问主办人应该最近（ ）个月未因执业行为违法违规受到处罚。","options":["6","12","24","36"],"answer":"D","explain":"财务顾问主办人应该最近36个月未因执业行为违法违规受到处罚。"},{"id":"law-m1-34","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"（ ）是证券期货经营机构服务投资者、控制经营风险和保护投资者合法权益的重要操作流程，核心目的是“将适当的产品或服务销售或提供给适当的投资者”。","options":["法人集中清算制度","信息隔离墙制度","利益冲突管理机制","投资者适当性制度"],"answer":"D","explain":"投资者适当性制度的核心目的是“将适当的产品或服务销售或提供给适当的投资者”。"},{"id":"law-m1-35","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"在信息披露义务人信息披露违法的责任认定中，认定为不予行政处罚的情形不包括（ ）。","options":["当事人对认定的信息披露违法事项提出具体异议记载于董事会、监事会、公司办公会议记录等，并在上述会议中投反对票的","当事人在信息披露违法事实所涉及期间，由于不可抗力、失去人身自由等无法正常履行职责的","对公司信息披露违法行为不负有主要责任的人员在公司信息披露违法行为发生后及时向公司和证券交易所、证券监管机构报告的","受他人胁迫参与信息披露违法行为"],"answer":"D","explain":"受他人胁迫参与属于从轻或减轻处罚情形，而非不予处罚情形。"},{"id":"law-m1-36","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"上市公司在1年内向他人提供担保的金额超过公司资产总额30%的，应当由股东会作出决议，并经（ ）通过。","options":["出席会议的股东所持表决权的半数以上","所有股东所持表决权的半数以上","出席会议的股东所持表决权的2/3以上","所有股东所持表决权的2/3以上"],"answer":"C","explain":"需经出席会议的股东所持表决权的2/3以上通过。"},{"id":"law-m1-37","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列关于联合保存的说法，错误的是（ ）。","options":["证券发行规模达到一定数量的，可以采用联合保荐","参与联合保荐的保荐机构不得超过2家","证券发行的主承销商可以由该保荐机构担任","其他具有保荐业务资格的证券公司不得与该保荐机构共同担任证券发行的主承销商"],"answer":"D","explain":"其他具有保荐业务资格的证券公司可以与该保荐机构共同担任主承销商。"},{"id":"law-m1-38","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"公司对公开发行股票所募集资金，必须按照招股说明书或者其他公开发行募集文件所列资金用途使用；改变资金用途，必须经（ ）作出决议。","options":["股东会","董事会","国务院","证券交易所"],"answer":"A","explain":"改变资金用途必须经股东会作出决议。"},{"id":"law-m1-39","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列关于证券公司廉洁从业的说法，错误的是（ ）。","options":["证券期货经营机构及其工作人员不得输送不正当利益","证券期货经营机构及其工作人员应当遵守社会公德、商业道德、职业道德和行为规范","证券期货经营机构不得直接向他人提供内幕信息、未公开信息、商业秘密和客户信息","证券期货经营机构工作人员可以向正在洽谈的潜在客户提供旅游服务"],"answer":"D","explain":"不得以提供旅游服务等方式向潜在客户输送不正当利益。"},{"id":"law-m1-40","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司在中间介绍业务中，不得为从事期货交易的客户提供下列（ ）服务。","options":["间接为期货交易提供担保","代客户保管交易密码","为期货交易提供融资","提供期货行情信息"],"answer":"ABC","explain":"不得提供融资、担保、代保管密码；提供期货行情信息是允许的。"},{"id":"law-m1-41","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"企业在（ ）状况下，不得再次公开发行公司债券。","options":["对已公开发行的公司债券或其他债务有违约或者延迟支付本息的事实，仍处于继续状态","违反《证券法》规定，改变公开发行公司债券所募资金的用途","具有持续经营能力","最近3年财务会计报告被出具无保留意见审计报告"],"answer":"AB","explain":"存在违约或改变资金用途的，不得再次公开发行公司债券。"},{"id":"law-m1-42","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"在处理与股东及股东关联方之间的关系时，证券公司还应注意，不得发生以下（ ）行为。","options":["持有股东的股权，但法律、行政法规或者中国证监会另有规定的除外","通过购买股东持有的证券等方式向股东输送不当利益","股东违规占用公司资产","法律、行政法规或者中国证监会禁止的其他行为"],"answer":"ABCD","explain":"上述均为禁止行为。"},{"id":"law-m1-43","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"客户信用证券账户内的证券，出现（ ）等情形时，证券公司在计算客户维持担保比例时，可以根据与客户的约定按照公允价格或其他定价方式计算其市值。","options":["被调出可充抵保证金证券范围","被暂停交易","被实施风险警示","因权益处理等产生尚未到账的在途证券"],"answer":"ABCD","explain":"上述情形均可按公允价格或其他方式计算市值。"},{"id":"law-m1-44","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列有关有限责任公司股权转让的说法，正确的有（ ）。","options":["有限责任公司的股东之间可以相互转让其全部或者部分股权","股东向股东以外的人转让股权，应当将股权转让的数量、价格、支付方式和期限等事项书面通知其他股东，其他股东在同等条件下有优先购买权","股东自接到书面通知之日起满30日未答复的，视为放弃优先购买权","2个以上股东行使优先购买权的，协商确定各自的购买比例"],"answer":"ABCD","explain":"均为股权转让的正确规定。"},{"id":"law-m1-45","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"当可疑交易符合下列（ ）情形时，证券公司应当在向中国反洗钱监测分析中心提交可疑报告的同时，以电子形式或者书面形式向所在地中国人民银行或者其分支机构报告，并配合反洗钱调查。","options":["明显涉嫌洗钱等犯罪活动的","明显涉嫌恐怖融资等犯罪活动的","严重危害国家安全的","严重影响社会稳定的"],"answer":"ABCD","explain":"上述情形均需同时报告。"},{"id":"law-m1-46","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列关于从事证券、期货投资咨询活动的说法，正确的是（ ）。","options":["通过电台、电视台等公众传播媒体提供证券、期货投资咨询服务","举办有关证券、期货投资咨询的讲座、报告会、分析会","接受本公司的委托，为投资者提供证券、期货投资咨询服务","在报刊上发表证券、期货投资咨询的文章、评论、报告"],"answer":"ABD","explain":"证券投资咨询不包括接受本公司委托，应为接受投资人或者客户委托。"},{"id":"law-m1-47","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"保荐人出具有虚假记载、误导性陈述或者重大遗漏的保荐书，或者不履行其他法定职责，有可能受到监管机构（ ）的监督、处罚措施。","options":["责令改正、给予警告","情节严重的，暂停或者撤销相关业务许可","对直接负责的主管人员和其他直接负责人员给予记大过处分","没收业务收入，并处罚款"],"answer":"ABD","explain":"记大过处分属于行政处分，不属于证监会的监管措施。"},{"id":"law-m1-48","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券经纪人在执业过程中可以（ ）。","options":["向客户介绍证券交易的基本知识","违反规定委托他人代理其从事客户招揽和客户服务等活动","向客户明示其与证券公司的委托代理关系，在委托合同约定的代理权限内从事客户招揽等活动","提供或传播虚假信息"],"answer":"AC","explain":"经纪人可以介绍证券交易基本知识，并应在代理权限内活动。"},{"id":"law-m1-49","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列各项中，属于我国证券市场法律法规体系主要层级的是（ ）。","options":["规范性文件","证券公司规章制度","普遍遵守的职业道德","行业自律规则"],"answer":"AD","explain":"主要层级包括法律、行政法规、部门规章、规范性文件、行业自律规则。"},{"id":"law-m1-50","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司在全国中小企业股份转让系统开展业务涉及的主要规定包括（ ）。","options":["《非上市公众公司监督管理办法》","《全国中小企业股份转让系统分层管理办法》","《全国中小企业股份转让系统业务规则（试行）》","《证券公司柜台交易业务规范》"],"answer":"ABC","explain":"D属于柜台市场业务规定。"},{"id":"law-m1-51","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司发生网络安全事件，对投资者造成影响的，应当及时通过（ ）等有效渠道通知相关方可以采取的替代方式或者应急措施。","options":["官方网站","客户交易终端","电话","邮件"],"answer":"ABCD","explain":"上述渠道均可用于通知。"},{"id":"law-m1-52","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券期货经营机构及其工作人员违反《证券期货经营机构及其工作人员廉洁从业规定》，有（ ）情形的，中国证监会应当从重处理。","options":["连续或者多次违反该规定","违反该规定后及时报告","涉及金额较大","曾为公职人员"],"answer":"ACD","explain":"及时报告属于从轻处理情形。"},{"id":"law-m1-53","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券金融公司的资金可以用于（ ）。","options":["购买银行存款","购买国债","购置自用不动产","维持公司正常运转"],"answer":"ABCD","explain":"上述均为资金用途。"},{"id":"law-m1-54","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司经营证券经纪业务、证券资产管理业务、融资融券业务和证券承销与保荐业务中两种以上业务的，其董事会应当设立（ ）。","options":["战略发展委员会","薪酬与提名委员会","审计委员会","风险控制委员会"],"answer":"BCD","explain":"应当设立薪酬与提名委员会、审计委员会和风险控制委员会。"},{"id":"law-m1-55","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"经营机构邀请外部专家参与证券投资咨询服务以外咨询服务，应当符合（ ）要求。","options":["外部专家应当具有良好的社会声誉，在最近三年没有被证券监管部门处罚的记录","经营机构如果通过第三方邀请外部专家，应当与第三方签订专门的外部专家邀请协议","经营机构邀请第三方为客户提供证券投资咨询服务以外的咨询服务，相关的费用不能单独列支","经营机构不得通过外包或与第三方签署业务收入分成协议等类似形式安排没有证券投资咨询业务资质的机构或个人为客户提供咨询服务"],"answer":"BD","explain":"外部专家最近两年未被处罚；费用应单独列支。"},{"id":"law-m1-56","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司加强自营业务内部控制的措施主要有（ ）。","options":["应加强自营账户的集中管理和访问权限控制","建立健全自营决策机构和决策程序","确保自营资金来源的合法性","建立独立的实时监控系统"],"answer":"ABCD","explain":"上述均为自营业务内部控制措施。"},{"id":"law-m1-57","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"根据《区域性股权市场自律管理与服务规范（试行）》，关于证券公司参与区域性股权市场，下列说法正确的有（ ）。","options":["证券公司开展区域性股权市场业务，应当在每个月的前10个工作日内将上个月度业务开展情况报送至中国证监会","证券公司入股区域性股权市场运营机构，不得利用股东身份谋取不正当利益","证券公司分支机构可以经证券公司批准并在授权范围内开展区域性股权市场相关业务","证券公司及其从业人员应当勤勉尽责，严格遵守执业规范和职业道德，按规定和约定履行义务"],"answer":"BCD","explain":"报送对象为中国证券业协会，而非证监会。"},{"id":"law-m1-58","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列关于证券公司应急预案的说法正确的是（ ）。","options":["证券公司应当制定并持续完善应急预案，包括但不限于应急管理建设目标、备份信息系统建设和恢复机制、备份数据恢复机制等内容","证券公司应急预案应当充分考虑重要信息系统故障、相关信息技术服务机构无法继续提供服务、证券公司信息技术高管或重要技术团队发生重大变动以及自然灾害等可能影响重要信息系统平稳运行的事件","证券公司应当根据系统变更、业务变化等情况，持续更新应急预案","应急演练应当形成报告，保存期限不得少于3年"],"answer":"ABC","explain":"应急演练报告保存期限不得少于5年。"},{"id":"law-m1-59","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"资产管理产品的投资者分为不特定社会公众和合格投资者两大类。以下属于合格投资者的是（ ）。","options":["个人的家庭金融资产合计不低于50万元","公司、企业等机构的净资产不低于500万元","具有2年以上投资经历且家庭金融净资产不低于300万元的个人","最近1年末净资产不低于1000万元的法人单位"],"answer":"CD","explain":"合格投资者要求家庭金融净资产不低于300万元（个人）或最近1年末净资产不低于1000万元（法人）。"},{"id":"law-m1-60","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"关于操纵证券、期货市场罪，下列说法正确的是（ ）。","options":["单位不能成为本罪的犯罪主体","本罪主观方面只能是获取不正当利益","情节严重的，处5年以下有期徒刑，并处或者单处罚金","情节特别严重的，处5年以上10年以下有期徒刑，并处罚金"],"answer":"CD","explain":"单位可构成本罪；主观方面为故意。"},{"id":"law-m1-61","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司净资本或者其他风险控制指标不符合规定标准的，中国证监会派出机构应当责令公司限期改正。整改期内、中国证监会及其派出机构应当区别情形，可以对证券公司采取的措施有（ ）。","options":["停止批准新业务","停止批准增设、收购营业性分支机构","限制分配红利","限制转让财产或在财产上设定其他权利"],"answer":"ABCD","explain":"上述措施均可采取。"},{"id":"law-m1-62","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"根据《证券法》，下列关于承销或者销售擅自公开发行或者变相公开发行的证券的主要法律责任，说法正确的是（ ）。","options":["责令停止承销或者销售，没收违法所得，并处以违法所得1倍以上10倍以下的罚款","责令停止承销或者销售，没收违法所得，并处以违法所得1倍以上5倍以下的罚款","对直接负责的主管人员和其他直接责任人员给予警告，并处以50万元以上500万元以下的罚款","对直接负责的主管人员和其他直接责任人员给予警告，并处以10万元以上100万元以下的罚款"],"answer":"AC","explain":"罚款为违法所得1倍以上10倍以下，直接责任人员罚款50万-500万。"},{"id":"law-m1-63","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司、证券投资咨询机构从事投资顾问业务时，可以（ ）。","options":["辅助客户作出投资决策","为客户提供投资建议","从该业务中获取经济利益","代客户作出投资决策"],"answer":"ABC","explain":"投资顾问不得代客户作出投资决策。"},{"id":"law-m1-64","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司参股一家地方性股权交易中心（持股25%，无控制权）。该交易中心若发生重大违规，可能导致证券公司被监管问询、暂停相关业务资格。在决定是否将其纳入并表管理时，除持股比例外，还应重点评估（ ）。","options":["该交易中心违规可能引发的证券公司声誉受损程度","证券公司是否可能因其违规而承担连带法律责任","该交易中心自身的盈利能力","该交易中心风险事件引发证券公司流动性紧张的可能性"],"answer":"ABD","explain":"盈利能力不是并表管理的核心评估因素。"},{"id":"law-m1-65","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列事项中，做法正确的是（ ）。","options":["证券公司股东的非货币财产出资总额占其注册资本的45%","证券公司股东会审议批准公司的利润分配方案","由董事会秘书负责股东会和董事会会议的筹备","证券公司审计委员会负责人由独立董事担任"],"answer":"BCD","explain":"非货币财产出资总额不得超过注册资本的30%。"},{"id":"law-m1-66","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"公司在合规负责人任期届满前免除其职务的正当理由只能有（ ）。","options":["合规负责人本人申请","中国证监会责令更换","有证据证明其无法正常履职","董事会认为其未能勤勉尽责"],"answer":"ABC","explain":"“董事会认为”不是法定正当理由。"},{"id":"law-m1-67","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"对于融资融券业务客户的申请，证券公司的客户选择标准，说法不正确的有（ ）。","options":["从事证券交易的时间3个月以上","最近20个交易日日均证券类资产不低于30万元","可以选择本公司的股东或关联人","客户信誉良好，无重大违约记录"],"answer":"ABC","explain":"交易时间需满半年，资产不低于50万元，不得选择股东或关联人。"},{"id":"law-m1-68","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"甲公司与乙公司计划合并成立丙公司，双方于2016年12月1日签订合并协议。在合并过程中，下列做法正确的有（ ）。","options":["双方编制资产负债表及财产清单","甲公司将合并事宜于2016年12月9日通知其债权人","乙公司于2017年1月13日在报纸上公告合并事宜","甲公司债权人丁公司在2016年12月12日收到甲公司的通知，在2017年1月10日向甲公司要求清偿债务"],"answer":"ABD","explain":"公告应在决议之日起30日内，C选项已超过期限。"},{"id":"law-m1-69","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列说法属于变相公开发行股票情形的有（ ）。","options":["非公开发行股票及其股权转让采用推介会的方式向社会公众发行","公司股东自行以公开方式向社会公众转让股票","公司股东委托他人以公开方式向社会公众转让股票","向特定对象转让股票，未经中国证监会核准，转让后公司股东139人"],"answer":"ABC","explain":"向特定对象转让后股东超过200人才构成变相公开发行，D为139人。"},{"id":"law-m1-70","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"关于证券公司必须符合的风险控制指标标准，下列说法错误的是（ ）。","options":["风险覆盖率不得高于100%","资本杠杆率不得高于8%","流动性覆盖率不得高于100%","净稳定资金率不得高于100%"],"answer":"ABCD","explain":"上述指标应为“不得低于”，而非“不得高于”。"},{"id":"law-m1-71","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"我国《证券法》规定，上市公司的收购方式包括（ ）。","options":["要约收购","协议收购","竞价收购","其他合法方式"],"answer":"ABD","explain":"上市公司收购方式包括要约收购、协议收购及其他合法方式。"},{"id":"law-m1-72","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司向客户融资，可以使用（ ）。","options":["自有资金","自有证券","依法筹集的资金","依法取得处分权的证券"],"answer":"AC","explain":"融资使用自有资金或依法筹集的资金；融券使用自有证券或依法取得处分权的证券。"},{"id":"law-m1-73","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列关于普通合伙人行为的说法，正确的有（ ）。","options":["普通合伙人应当根据合伙协议的约定来执行合伙事务","合伙人对《合伙企业法》规定或者合伙协议约定必须经全体合伙人一致同意始得执行的事务擅自处理，给合伙企业或者其他合伙人造成损失的，依法承担赔偿责任","普通合伙人执行合伙事务，利用职务上的便利，将应当归属合伙企业的利益据为己有的，应当将该利益退还合伙企业","不具有事务执行权的普通合伙人也可以执行合伙事务"],"answer":"ABC","explain":"不具有事务执行权的合伙人不得执行合伙事务。"},{"id":"law-m1-74","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司以资产管理计划资产从事关联交易的，应当做到（ ）。","options":["事先取得投资者的同意","向中国证监会相关派出机构报告","向证券投资基金业协会报告","事后及时告知投资者和托管人"],"answer":"ABD","explain":"无需向基金业协会报告。"},{"id":"law-m1-75","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"按照《证券公司内部控制指引》的要求，证券公司内部控制的组织结构要求设立严密有效的三道业务防线，分别是（ ）。","options":["建立相关部门、相关岗位之间相互制衡、监督的防线","建立重要一线岗位双人、双职、双责为基础的防线","建立独立的监督检查部门对各项业务、各部门、各分支机构、各岗位全面实施监控、检查和反馈的防线","建立健全经纪业务的实时监控系统"],"answer":"ABC","explain":"D属于经纪业务内部控制，不属于三道防线。"},{"id":"law-m1-76","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"对负有信息披露义务的公司、企业向股东和社会公众提供虚假的或者隐瞒重要事实的财务会计报告，或者对依法应当披露的其他重要信息不按照规定披露，涉嫌下列情形之一的，应予立案追诉（ ）。","options":["造成股东、债权人或者其他人直接经济损失数额累计在50万元以上的","致使不符合发行条件的公司、企业骗取发行核准并且上市交易的","其他严重损害股东、债权人或者其他人利益，或者有其他严重情节的情形","多次对依法应当披露的重要信息不按照规定披露的"],"answer":"BCD","explain":"直接经济损失累计应为100万元以上。"},{"id":"law-m1-77","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"衍生品交易，是指期货交易以外的，以（ ）及其组合为交易标的的交易活动。","options":["互换合约","标准化期权合约","远期合约","非标准化期权合约"],"answer":"ACD","explain":"衍生品交易不包括标准化期权合约（属期货交易）。"},{"id":"law-m1-78","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列属于《股票期权交易试点管理办法》规定的公司开展股票期权业务的主要交易规则的有（ ）。","options":["证券登记结算机构负责投资者衍生品合约账户的统一管理","股票期权买方应当支付权利金，股票期权卖方收取权利金，并应当根据证券交易所、证券登记结算机构的规定交纳保证金","股票期权买方有权决定在合约规定期间是否行权","股票期权交易实行当日无负债结算制度"],"answer":"ABCD","explain":"上述均为股票期权交易规则。"},{"id":"law-m1-79","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列属于信用风险的业务类型的是（ ）。","options":["股票质押式回购交易","互换、场外期权、远期、信用衍生品等场外衍生品业务","债券回购交易","非标准化债权资产投资"],"answer":"ABCD","explain":"上述业务均涉及信用风险。"},{"id":"law-m1-80","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"发行人申请公开发行股票、可转换为股票的公司债券，依法采取承销方式的，或者公开发行法律、行政法规规定实行保荐制度的其他证券的，应当聘请证券公司担任保荐人。（ ）","options":["正确","错误"],"answer":"A","explain":"该表述正确。"},{"id":"law-m1-81","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司风险处置措施包括停业整顿、托管、接管、行政重组、撤销、行政清理及破产清算和重整。（ ）","options":["正确","错误"],"answer":"A","explain":"该表述正确。"},{"id":"law-m1-82","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"就中国证监会在反馈意见中提出的问题，财务顾问主办人应当与项目团队成员商议后直接尽快回复。（ ）","options":["正确","错误"],"answer":"B","explain":"应当按内部程序向部门负责人、内部核查机构负责人报告后审慎回复。"},{"id":"law-m1-83","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"公司不采纳合规负责人的合规审查意见的，应当将有关事项提交股东会审议决定。（ ）","options":["正确","错误"],"answer":"B","explain":"应当提交董事会审议决定。"},{"id":"law-m1-84","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"私募资产管理业务投资经理离任的，证券期货经营机构应当立即对其进行离任审查，并自离任之日起2个月内将审查报告报送中国证监会相关派出机构。（ ）","options":["正确","错误"],"answer":"B","explain":"应在30个工作日内报送。"},{"id":"law-m1-85","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"国家控股的企业之间不因为同受国家控股而具有关联关系。（ ）","options":["正确","错误"],"answer":"A","explain":"该表述正确。"},{"id":"law-m1-86","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司向客户收取的佣金无下限限制，可以实行0佣金。（ ）","options":["正确","错误"],"answer":"B","explain":"佣金不得低于代收的证券交易监管费和证券交易所手续费等。"},{"id":"law-m1-87","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司董事会设薪酬与提名委员会、审计委员会的，委员会负责人由董事长担任。（ ）","options":["正确","错误"],"answer":"B","explain":"委员会负责人由独立董事担任。"},{"id":"law-m1-88","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"在招股说明书、认股书、公司、企业债券募集办法等发行文件中隐瞒重要事实或者编造重大虚假内容，发行股票或者公司、企业债券、存托凭证或者国务院依法认定的其他证券，非法募集资金金额在500万元以上的，应予立案追诉。（ ）","options":["正确","错误"],"answer":"B","explain":"非法募集资金金额应在1000万元以上。"},{"id":"law-m1-89","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司聘任董事、监事和高级管理人员前，应当审慎考察并确认其符合相应的任职条件，自作出聘任决定之日起5个工作日内向中国证监会相关派出机构报送相关备案材料。（ ）","options":["正确","错误"],"answer":"A","explain":"该表述正确。"},{"id":"law-m1-90","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券投资咨询人员经证券监督管理机构审批同意后，可以在两家或者两家以上的证券投资咨询机构执业。（ ）","options":["正确","错误"],"answer":"B","explain":"只能在一家证券经营机构执业。"},{"id":"law-m1-91","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"开放式基金无需保持足够的现金或者政府债券。（ ）","options":["正确","错误"],"answer":"B","explain":"开放式基金应当保持足够的现金或政府债券以应对赎回。"},{"id":"law-m1-92","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"某证券公司认为其附属公募基金公司受证监会单独监管，因此无需将其股票持仓数据纳入集团市场风险监测系统。（ ）","options":["正确","错误"],"answer":"B","explain":"并表管理要求覆盖所有附属机构的风险。"},{"id":"law-m1-93","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司设立的自营业务投资决策机构是自营业务的最高决策机构，负责确定公司自营业务规模、可承受的风险限额、资产配置策略等。（ ）","options":["正确","错误"],"answer":"B","explain":"董事会是自营业务的最高决策机构。"},{"id":"law-m1-94","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"内幕交易、泄露内幕信息罪的犯罪主体是一般主体。（ ）","options":["正确","错误"],"answer":"B","explain":"犯罪主体是特殊主体，包括内幕信息知情人员和非法获取人员。"},{"id":"law-m1-95","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司在自评估时发现了涉嫌洗钱和恐怖融资的活动，但因风险较低，所以证券公司可以采取适当的简化措施。（ ）","options":["正确","错误"],"answer":"B","explain":"发现涉嫌洗钱或恐怖融资活动时，不得采取简化措施。"},{"id":"law-m1-96","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"公司可依照不同的分类标准作不同的分类，依照股份是否在证券交易所挂牌交易，可分为有限责任公司和股份有限公司。（ ）","options":["正确","错误"],"answer":"B","explain":"依股东人数和股份流动性可分为有限责任公司和股份有限公司。"},{"id":"law-m1-97","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"主板上市公司发行新股、可转换公司债券的，持续督导期间为股票、可转换公司债券上市当年剩余时间及其后2个完整会计年度。（ ）","options":["正确","错误"],"answer":"B","explain":"持续督导期间为上市当年剩余时间及其后1个完整会计年度。"},{"id":"law-m1-98","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司进行破产清算的，行政清理时已登记的不符合国家收购规定的债权，管理人可以直接予以登记。（ ）","options":["正确","错误"],"answer":"A","explain":"该表述正确。"},{"id":"law-m1-99","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"从事证券投资咨询业务的人员可以不用加入有从业资格的证券投资咨询机构，独立执业。（ ）","options":["正确","错误"],"answer":"B","explain":"证券投资咨询人员应为证券投资咨询机构正式员工。"},{"id":"law-m1-100","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"盘后固定价格交易指在竞价交易结束后，投资者通过集合竞价委托，按照收盘价买卖股票的交易方式。（ ）","options":["正确","错误"],"answer":"B","explain":"盘后固定价格交易按照时间优先顺序对收盘定价申报进行撮合，而非集合竞价委托。"},{"id":"law-m1-101","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"有限合伙人转变为普通合伙人的，对其作为有限合伙人期间有限合伙企业发生的债务以其认缴的出资额为限承担责任。（ ）","options":["正确","错误"],"answer":"B","explain":"应承担无限连带责任。"},{"id":"law-m1-102","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"监事会每年至少进行1次全面的内部控制检查评价工作，并形成相应的专门报告。（ ）","options":["正确","错误"],"answer":"B","explain":"董事会负责进行全面的内部控制检查评价。"},{"id":"law-m1-103","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"期货公司不得以自有资金参与股票期权交易试点。（ ）","options":["正确","错误"],"answer":"A","explain":"该表述正确。"},{"id":"law-m1-104","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"公司以超过股票票面金额的发行价格发行股份所得的溢价款、发行无面额股所得股款未计入注册资本的金额，以及国务院财政部门规定列入资本公积金的其他项目，应当列为公司法定公积金。（ ）","options":["正确","错误"],"answer":"B","explain":"应列为公司资本公积金，而非法定公积金。"},{"id":"law-m1-105","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司对子公司的风险管理以授权管理为主，穿透管理仅作为补充手段。（ ）","options":["正确","错误"],"answer":"B","explain":"应以穿透管理与授权管理相结合的方式。"},{"id":"law-m1-106","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券经纪人应当为客户办理证券认购、交易或者资金存取、划转等事宜。（ ）","options":["正确","错误"],"answer":"B","explain":"经纪人不得办理上述事宜。"},{"id":"law-m1-107","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司从事私募资产管理业务，应当依法经中国基金业协会批准。（ ）","options":["正确","错误"],"answer":"B","explain":"应经中国证监会批准。"},{"id":"law-m1-108","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"董事、监事、高级管理人员应当遵守法律、行政法规和公司章程，对公司负有忠实义务和勤勉义务。董事、监事、高级管理人员执行职务时违反法律、行政法规或者公司章程的规定，给公司造成损失的，应当承担赔偿责任。（ ）","options":["正确","错误"],"answer":"A","explain":"该表述正确。"},{"id":"law-m1-109","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"被执法单位采取证券市场禁入措施的人员，执法单位将通过中国证券业协会网站，或者指定媒体向社会公布，并记入证券市场诚信档案。（ ）","options":["正确","错误"],"answer":"B","explain":"通过中国证监会或派出机构网站公布。"},{"id":"law-m1-110","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】周某时任丙证券公司投资银行部副总监，是丁公司IPO和持续督导保荐代表人，为法定内幕信息知情人。丁公司上市前，周某介绍李某等人以“王某”名义入股丁公司。丁公司上市后进行重大资产重组的信息属于内幕信息，周某在此期间获悉并指导李某通过大宗交易减持“王某”证券账户中丁公司股票，同时以电话委托方式帮助李某卖出“王某”证券账户所持有的丁公司股票。请回答1-2题。\n\n【问题】（1）除了周某以外，下列人员中，属于丁公司证券交易内幕信息知情人的有（ ）。","options":["丁公司的董事赵某","持有丁公司10%股份的张某","丁公司的实际控制人钱某","承销丁公司股票的证券公司工作人员"],"answer":"ABCD","explain":"上述人员均属于内幕信息知情人。"},{"id":"law-m1-111","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】周某时任丙证券公司投资银行部副总监，是丁公司IPO和持续督导保荐代表人，为法定内幕信息知情人。丁公司上市前，周某介绍李某等人以“王某”名义入股丁公司。丁公司上市后进行重大资产重组的信息属于内幕信息，周某在此期间获悉并指导李某通过大宗交易减持“王某”证券账户中丁公司股票，同时以电话委托方式帮助李某卖出“王某”证券账户所持有的丁公司股票。请回答1-2题。\n\n【问题】（2）某省中级人民法院认定，周某的行为已构成内幕交易罪，下列关于周某需承担的法律责任的表述中，说法正确的是（ ）。","options":["责令依法处理非法持有的证券","没收全部财产","处以违法所得1倍以上5倍以下的罚款","处以违法所得1倍以上10倍以下的罚款"],"answer":"AD","explain":"应没收违法所得（非全部财产），罚款1倍以上10倍以下。"},{"id":"law-m1-112","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】中国人民银行某中心支行对辖区内乙证券公司营业部开展了反洗钱执法检查，在检查中发现了该营业部存在未按规定履行客户身份识别义务的情况。请根据上述背景信息回答以下问题。\n\n【问题】（1）乙证券公司营业部在开展客户尽职调查时，应当（ ）。","options":["存在代理关系的，核实代理人身份","登记客户身份基本信息","留存客户的有效身份证件","对于涉及较低洗钱风险的，应根据情况简化客户尽职调查"],"answer":"ABCD","explain":"上述均为客户尽职调查要求。"},{"id":"law-m1-113","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】中国人民银行某中心支行对辖区内乙证券公司营业部开展了反洗钱执法检查，在检查中发现了该营业部存在未按规定履行客户身份识别义务的情况。请根据上述背景信息回答以下问题。\n\n【问题】（2）客户先前提交的身份证件或者身份证明文件已过有效期，没有在合理期限内更新且没有提出合理理由的，乙证券公司应采取（ ）的措施。","options":["限制为其办理新业务","限制撤销指定交易","冻结账户","限制其资金转出"],"answer":"ABD","explain":"可限制办理新业务、限制撤销指定交易、限制资金转出，但不能冻结账户。"},{"id":"law-m1-114","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】中国人民银行某中心支行对辖区内乙证券公司营业部开展了反洗钱执法检查，在检查中发现了该营业部存在未按规定履行客户身份识别义务的情况。请根据上述背景信息回答以下问题。\n\n【问题】（3）对于新建业务关系的客户，乙证券公司应在建立业务关系后的（ ）个工作日内，按照收集信息、筛选分析信息、初评和复评的流程，划分其风险等级。","options":["3","5","7","10"],"answer":"D","explain":"应在建立业务关系后10个工作日内完成风险等级划分。"},{"id":"law-m1-115","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】甲公司拟申请在科创板首次公开发行股票并上市，聘请乙证券公司担任保荐机构。乙证券公司指派员工张某、王某担任甲公司首次公开发行股票并上市项目的保荐代表人。中国证监会在审核的过程中发现，乙证券公司及其保荐代表人在保荐过程中未能勤勉尽责，出具的保荐书存在虚假记载的情形。请回答1-3题。\n\n【问题】（1）乙证券公司作为保荐机构，应当具备的条件包括（ ）。","options":["注册资本、净资本符合规定","具有完善的公司治理和内部控制制度","保荐代表人不少于2人","最近2年内未因重大违法违规行为受到处罚"],"answer":"ABD","explain":"保荐代表人应不少于4人，故C错误。"},{"id":"law-m1-116","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】甲公司拟申请在科创板首次公开发行股票并上市，聘请乙证券公司担任保荐机构。乙证券公司指派员工张某、王某担任甲公司首次公开发行股票并上市项目的保荐代表人。中国证监会在审核的过程中发现，乙证券公司及其保荐代表人在保荐过程中未能勤勉尽责，出具的保荐书存在虚假记载的情形。请回答1-3题。\n\n【问题】（2）乙证券公司及其保荐代表人在保荐过程中未能勤勉尽责，出具的保荐书存在虚假记载的情形，对此，中国证监会能够采取的监管措施包括（ ）。","options":["责令改正","给予警告","没收业务收入","并处罚款"],"answer":"ABCD","explain":"上述措施均可采取。"},{"id":"law-m1-117","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】甲公司拟申请在科创板首次公开发行股票并上市，聘请乙证券公司担任保荐机构。乙证券公司指派员工张某、王某担任甲公司首次公开发行股票并上市项目的保荐代表人。中国证监会在审核的过程中发现，乙证券公司及其保荐代表人在保荐过程中未能勤勉尽责，出具的保荐书存在虚假记载的情形。请回答1-3题。\n\n【问题】（3）若甲公司最终成功在科创板首次公开发行股票并上市，则甲公司的持续督导期间应为（ ）。","options":["股票上市当年剩余时间及其后1个完整会计年度","股票上市当年剩余时间及其后2个完整会计年度","股票上市当年剩余时间及其后3个完整会计年度","股票上市当年剩余时间及其后4个完整会计年度"],"answer":"C","explain":"科创板持续督导期间为上市当年剩余时间及其后3个完整会计年度。"},{"id":"law-m1-118","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】2012年下半年，乙公司因资金紧张、经营困难，公司法定代表人张某与公司高管研究决定发行私募债券融资，并安排财务负责人胡某具体负责。为顺利发行债券，张某安排胡某对会计师事务所隐瞒乙公司及张某负债数千万元的重要事实，并提供虚假财务账表、凭证，通过虚构公司销售收入和应收款项、骗取审计询证等方式，致使会计师事务所的审计报告发生重大误差，且在募集说明书中引用审计报告。2013年5月，乙公司在某证券交易所骗取5000万元中小企业私募债券发行备案，并在当年内分两期完成发行。请回答1-2题。\n\n【问题】（1）张某及胡某的上述行为构成（ ）。","options":["欺诈发行证券罪","非法吸收公众存款罪","擅自公开或变相公开发行证券","集资诈骗罪"],"answer":"A","explain":"上述行为符合欺诈发行证券罪的构成要件。"},{"id":"law-m1-119","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】2012年下半年，乙公司因资金紧张、经营困难，公司法定代表人张某与公司高管研究决定发行私募债券融资，并安排财务负责人胡某具体负责。为顺利发行债券，张某安排胡某对会计师事务所隐瞒乙公司及张某负债数千万元的重要事实，并提供虚假财务账表、凭证，通过虚构公司销售收入和应收款项、骗取审计询证等方式，致使会计师事务所的审计报告发生重大误差，且在募集说明书中引用审计报告。2013年5月，乙公司在某证券交易所骗取5000万元中小企业私募债券发行备案，并在当年内分两期完成发行。请回答1-2题。\n\n【问题】（2）乙公司涉嫌（ ）情形的，应予立案追诉。","options":["非法募集资金金额在1000万元以上的","造成投资者直接经济损失数额累计在50万元以上的","伪造、变造有效证明文件或者相关凭证、单据的","向负有金融监督管理职责的单位或者人员行贿的"],"answer":"ACD","explain":"直接经济损失应为100万元以上。"}]},{"id":"law-m2","subject":"law","name":"法规 · 提分密训卷二","stats":{"单选":40,"多选":40,"判断":30,"案例":10},"questions":[{"id":"law-m2-0","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列关于有限责任公司股东出资责任的说法，正确的是（ ）。","options":["公司设立时，股东未按照公司章程规定实际缴纳出资，或者实际出资的非货币财产的实际价额显著低于所认缴的出资额的，设立时的其他股东与该股东在出资不足的范围内无需承担连带责任","公司注册资本为在公司登记机关登记的全体股东实缴的出资额","股东未按期足额缴纳出资的，向公司足额缴纳出资额后，无需承担其他责任","股东以非货币财产出资的，该非货币财产应当评估作价，核实财产，不得高估或低估作价"],"answer":"D","explain":"股东以非货币财产出资的，应当评估作价，不得高估或低估。"},{"id":"law-m2-1","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列关于全国股转公司对申请文件进行审核的说法，错误的是（ ）。","options":["最近一个完整会计年度净利润为正","申请挂牌公司符合公开转让条件、挂牌条件以及信息披露要求","出具同意公开转让并挂牌的审核意见","将审核意见、注册申请文件及相关审核资料报中国证监会注册"],"answer":"A","explain":"全国股转公司对企业挂牌不设财务指标。"},{"id":"law-m2-2","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列属于证券监督管理机构制定的部门规章的是（ ）。","options":["《证券公司和证券投资基金管理公司合规管理办法》","《期货交易管理条例》","《中华人民共和国公司法》","《中华人民共和国证券投资基金法》"],"answer":"A","explain":"《证券公司和证券投资基金管理公司合规管理办法》属于部门规章。"},{"id":"law-m2-3","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"同时符合下列条件的法人或者其他组织是第二类专业投资者：最近1年年末净资产不低于（ ）万元；最近1年年末金融资产不低于（ ）万元；具有2年以上证券、基金、期货、黄金、外汇等投资经历。","options":["1000；1000","2000；1000","2000；2000","1000；2000"],"answer":"B","explain":"第二类专业投资者要求净资产不低于2000万元，金融资产不低于1000万元。"},{"id":"law-m2-4","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"关于擅自改变公开发行证券募集资金用途的认定，下列选项错误的有（ ）。","options":["公开发行公司债券筹集的资金，必须按照公司债券募集办法所列资金用途使用","公司改变招股说明书所列资金用途的，必须经过股东会作出决议","公开发行公司债券筹集的资金，可以用于弥补亏损和非生产性支出","擅自改变用途未作纠正的，或者未经股东会认可的，不得公开发行新股"],"answer":"C","explain":"公开发行公司债券筹集的资金，不得用于弥补亏损和非生产性支出。"},{"id":"law-m2-5","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"未经批准擅自设立基金管理公司或者未经核准从事公开募集基金管理业务的，由国务院证券监督管理机构（ ）或者责令改正，没收违法所得，并处违法所得1倍以上5倍以下罚款。","options":["市场禁入","予以取缔","进行训诫","通报批评"],"answer":"B","explain":"国务院证券监督管理机构予以取缔或者责令改正。"},{"id":"law-m2-6","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司应当建立观察名单和限制名单制度。以下关于观察名单和限制名单进出时点的说法，错误的是（ ）。","options":["观察名单的进入时点，以与客户签署保密协议、对项目立项、进场开展工作和实际获知项目内幕信息中较晚者为准","限制名单的进出时点之一是担任首次公开发行股票项目的上市辅导人、保荐机构或主承销商的信息公开之日","担任上市公司股权类、债权类再融资项目或并购重组项目保荐机构、主承销商或财务顾问的，限制名单的进出时点是项目公司首次对外公告该项目之日","证券公司根据实际需要，可以将列入限制名单的时点前移"],"answer":"A","explain":"观察名单的进入时点以较早者为准，而非较晚者。"},{"id":"law-m2-7","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列关于背信运用受托财产罪的刑事追诉标准的说法，正确的是（ ）。","options":["本罪即使行为人擅自运用多个客户资金，如果涉案金额达不到标准，也不满足刑事追诉的标准","本罪即使涉案金额达不到标准，但多次擅自运用客户资金或者其他委托财产的，也满足刑事追诉的标准","本罪即使行为人多次擅自运用客户资金，如果涉案金额达不到标准，也不满足刑事追诉的标准","本罪的刑事追诉标准和具体涉案金额数无关"],"answer":"B","explain":"虽未达到数额标准，但多次擅自运用客户资金的，应予立案追诉。"},{"id":"law-m2-8","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列关于上市的条件的说法中，错误的是（ ）。","options":["中国证监会根据国务院授权的部门的决定安排政府债券上市交易","证券交易所根据国务院授权部门的决定安排政府债券上市交易","申请证券上市交易应当向证券交易所提出申请","申请证券上市的公司应与证券交易所签订上市协议"],"answer":"A","explain":"证券交易所根据国务院授权部门的决定安排政府债券上市交易，而非中国证监会。"},{"id":"law-m2-9","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"按照《证券公司治理准则》的要求，关于证券公司和控股股东、实际控制人及其关联方之间开展业务竞争和关联交易的说法正确的是（ ）。","options":["证券公司的关联方可以与其所控制的证券公司开展同类业务","证券公司控制其他证券公司的，可以开展与该证券公司相同的同类业务，以竞争的形式促进双方发展","证券公司的股东、实际控制人与证券公司的关联交易可以在牺牲证券公司利益的基础上进行","证券公司章程应当对重大关联交易及其披露和表决程序作出规定"],"answer":"D","explain":"证券公司章程应当对重大关联交易及其披露和表决程序作出规定。"},{"id":"law-m2-10","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"具备（ ）业务资格的证券公司可以从事金融衍生产品交易。","options":["证券经纪","证券自营","证券投资咨询","证券承销与保荐"],"answer":"B","explain":"具备证券自营业务资格的证券公司可以从事金融衍生产品交易。"},{"id":"law-m2-11","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列关于有限合伙企业的说法，正确的是（ ）。","options":["有限合伙企业由有限合伙人执行合伙事务","有限合伙人转变为普通合伙人，应当经半数合伙人一致同意","有限合伙企业仅剩有限合伙人的，应当解散","有限合伙企业仅剩普通合伙人的，应当解散"],"answer":"C","explain":"有限合伙企业仅剩有限合伙人的，应当解散；仅剩普通合伙人的，转为普通合伙企业。"},{"id":"law-m2-12","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"以下关于客户身份资料和交易记录保存的基本要求，说法错误的是（ ）。","options":["在业务关系存续期间，客户身份资料发生变更的，证券公司应当及时更新客户身份资料","证券公司应当保存的交易记录包括关于每笔交易的数据信息、业务凭证、账簿以及有关规定要求的反映交易真实情况的合同、业务凭证、单据、业务函件和其他资料","客户身份资料，自业务关系结束后或者一次性金融服务结束后至少保存20年","交易记录，自交易结束后至少保存10年"],"answer":"C","explain":"客户身份资料自业务关系结束后至少保存10年，而非20年。"},{"id":"law-m2-13","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"关于证券发行后，保荐代表人的更换规定不正确的是（ ）。","options":["证券发行后，除规定原因外保荐机构不得更换保荐代表人","因保荐代表人离职或者被撤销保荐代表人资格的，应当更换保荐代表人","保荐机构更换保荐代表人的，应当通知发行人，并在3个工作日内向中国证监会、证券交易所报告，说明原因","原保荐代表人在具体负责保荐工作期间未勤勉尽职的，其责任不因保荐代表人的更换而免除或终止"],"answer":"C","explain":"应在5个工作日内报告，而非3个工作日。"},{"id":"law-m2-14","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列（ ）不属于资产管理计划的投资者主要应履行的义务。","options":["接受合格投资者认定程序，如实填写风险识别能力和风险承担能力问卷","认真阅读并签署风险揭示书","保守商业秘密，不得泄露资产管理计划的投资计划、投资意向等","监督管理人、托管人履行投资管理及托管义务的情况"],"answer":"D","explain":"监督管理人、托管人履行义务是投资者的权利，而非义务。"},{"id":"law-m2-15","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列关于股份有限公司股票转让的表述中，说法不正确的是（ ）。","options":["公司一般情况下不得收购本公司股份","股东持有的股份可以向其他股东转让，也可以向股东以外的人转让","股份转让有限制的，其转让按照公司章程的规定进行","公司公开发行股份前已发行的股份，自公司股票在证券交易所上市交易之日起2年内不得转让"],"answer":"D","explain":"公开发行前已发行的股份，自上市交易之日起1年内不得转让。"},{"id":"law-m2-16","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"甲证券公司根据自身经营目标和运营状况，结合自身的环境条件，建立有效的内部控制制度、机制。以下甲证券公司内部控制当前遵循的原则，错误的是（ ）。","options":["甲证券公司的内部控制覆盖所有业务、部门和人员","为了提高效率，甲证券公司承担内部控制监督检查职能的部门同时辅助前台业务运作","该证券公司以合理的成本实现内部控制目标","前台业务运作与后台管理支持适当分离"],"answer":"B","explain":"承担内部控制监督检查职能的部门应当独立于其他部门。"},{"id":"law-m2-17","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券交易所为证券集中交易提供场所和设施，组织和监督证券交易，实行自律管理，关于证券交易所的交易规则，说法正确的是（ ）。","options":["进入实行会员制的证券交易所参与集中交易的，必须是证券交易所的会员","投资者应当与证券公司签订证券交易委托协议，并在证券公司实名开立账户，以口头、电话以及其他方式，委托该证券公司代其买卖证券","证券公司为投资者开立账户，应当按照规定对投资者提供的身份信息进行核对，证券公司可以将投资者的账户提供给他人使用","未经证券交易所许可，单位可以发布证券交易即时行情，个人不得发布证券交易即时行情"],"answer":"A","explain":"进入会员制交易所参与集中交易的，必须是该交易所的会员。"},{"id":"law-m2-18","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"在证券经纪业务中，证券公司不赚取买卖差价，只收取一定比例的（ ）作为报酬。","options":["印花税","佣金","结算登记费","过户费"],"answer":"B","explain":"证券公司通过收取佣金作为报酬。"},{"id":"law-m2-19","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司的净资本等风险控制指标达到预警标准或者不符合规定标准的，应当分别在该情形发生之日起（ ）个、（ ）个工作日内，向中国证监会及其派出机构报告。","options":["3;1","5;1","5;3","7;5"],"answer":"A","explain":"达到预警标准在3个工作日内，不符合规定标准在1个工作日内报告。"},{"id":"law-m2-20","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"以下关于设立证券公司，应当具备下列条件，说法错误的是（ ）。","options":["主要股东及公司的实际控制人具有良好的财务状况和诚信记录，最近2年无重大违法违规记录","有合格的经营场所、业务设施和信息技术系统","有完善的风险管理与内部控制制度","有符合法律、行政法规规定的公司章程"],"answer":"A","explain":"主要股东及实际控制人最近3年无重大违法违规记录。"},{"id":"law-m2-21","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司是内地证券基金经营机构，在使用港股投资顾问服务的过程中，不符合业务规范的是（ ）。","options":["证券公司委托提供港股投资顾问服务的香港机构直接执行投资指令","证券公司与提供港股投资顾问服务的香港机构签订协议","证券公司在招募说明书中如实披露使用港股投资顾问服务的情况","证券公司对使用港股通投资顾问服务的情况实行留痕管理，并以电子方式存储"],"answer":"A","explain":"不得委托香港机构直接执行投资指令，应自主作出投资决策。"},{"id":"law-m2-22","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列有关有限责任公司的说法，错误的是（ ）。","options":["自然人股东死亡后，其合法继承人可以继承股东资格；但是，公司章程另有规定的除外","股权转让时，公司应当及时注销原股东的出资说明书，向新股东签发出资说明书，并相应修改公司章程。对公司章程的该项修改不需再向股东会表决","人民法院依照法律规定强制执行程序转让股东股权时，其他股东同等条件下有优先购买权","有限责任公司股东对外转让股权时，2个以上股东行使优先购买权的，若公司章程没有规定，股东之间需要平均分配所转让的股权"],"answer":"D","explain":"协商确定购买比例，协商不成的按出资比例行使。"},{"id":"law-m2-23","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"关于保证金可用余额的规定，以下选项错误的有（ ）。","options":["交易所可以根据市场情况调整可充抵保证金证券的名单和折算率","保证金可用余额是指客户用于充抵保证金的现金加证券市值减去客户未了结融资融券交易已占用保证金的余额","国债作为融资融券保证金的折算率不超过95%","上证180指数成分股股票作为融资融券保证金的折算率不超过70%"],"answer":"B","explain":"保证金可用余额还包括融资融券交易产生的浮盈经折算后形成的保证金总额。"},{"id":"law-m2-24","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司应当建立合理的内部控制监督、检查与评价机制，确保内部控制的有效性。证券公司应当设立监督检查部门或岗位，监督检查部门应加强对内部控制执行情况的现场检查、非现场检查和常规稽核、非常规稽核，并将检查结果报（ ）。","options":["证券公司注册地中国证监会派出机构","证券公司注册地中国证券业协会","证券公司所在地中国证监会派出机构","证券公司所在地中国证券业协会"],"answer":"A","explain":"检查结果报证券公司注册地中国证监会派出机构。"},{"id":"law-m2-25","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"关于证券公司及其分支机构的业务经营，下列说法中，错误的是（ ）。","options":["证券公司经营的业务应当经国务院证券监督管理机构批准","证券公司境内分支机构不得经营未经批准的业务","两个以上证券公司相互之间存在控制关系的，可以经营相同的证券业务","两个以上证券公司受同一单位控制的，不得经营相同的证券业务"],"answer":"C","explain":"相互之间存在控制关系或受同一单位控制的，不得经营相同的证券业务。"},{"id":"law-m2-26","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"根据《证券公司另类投资子公司管理规范》下列关于另类投资业务规则的说法，错误的是（ ）。","options":["另类投资子公司资金不足以向银行申请贷款","另类子公司应当建立投资管理制度，设立专门的投资决策机构，明确决策权限和决策","另类子公司不得下设机构，不得从事融资类收益互换业务，不得投资于高杠杆的结构化资产管理产品","另类子公司持有境内证券交易场所上市交易和转让的证券的，应当将另类子公司与母公司自营持有同一只证券的市值合并计算"],"answer":"A","explain":"另类子公司不得融资，不得对外提供担保和贷款。"},{"id":"law-m2-27","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"基金托管人在基金信息披露方面的主要职责是（ ）。","options":["办理与基金托管业务活动有关的信息披露事项","办理与基金财产管理业务活动有关的信息披露事项","编制中期和年度基金报告","进行基金会计核算并编制基金财务会计报告"],"answer":"A","explain":"基金托管人负责办理与基金托管业务活动有关的信息披露事项。"},{"id":"law-m2-28","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"对证券公司投资银行类项目负有主要管理或执行责任人员的收入递延支付年限，原则上不得少于（ ）年。","options":["5","4","3","2"],"answer":"C","explain":"收入递延支付年限原则上不得少于3年。"},{"id":"law-m2-29","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列关于擅自发行股票、公司、企业债券罪的犯罪构成的说法，错误的是（ ）。","options":["本罪的主体是一般主体，既可以是自然人，也可以是单位","客观方面，未经国家有关部门批准，擅自发行股票或者公司、企业债券，且数额巨大，后果严重或者有其他严重情节","本罪的客体是国家对发行股票或者公司、企业债券的管理秩序","本罪的主观方面是故意或过失"],"answer":"D","explain":"本罪的主观方面是故意。"},{"id":"law-m2-30","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"交易者在结算过程中违约的，其委托的结算参与人按照合同约定动用该交易者的保证金以及结算参与人的（ ）和自有资金完成结算。","options":["法定公积金","风险准备金","结算担保金","资本公积金"],"answer":"B","explain":"动用结算参与人的风险准备金和自有资金完成结算。"},{"id":"law-m2-31","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"经营机构向普通投资者销售产品或者提供服务前，应当告知的下列信息中错误的是（ ）。","options":["可能直接导致本金亏损的事项","可能直接导致超过原始本金损失的事项","因经营机构的业务或者财产状况变化，可能导致本金或者原始本金亏损的事项","利益保证承诺"],"answer":"D","explain":"利益保证承诺是禁止行为，不属于应告知信息。"},{"id":"law-m2-32","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"某证券公司在2017年8月1日开始行政重组。关于下列行为，符合《证券公司风险处置条例》规定的是（ ）。","options":["2017年12月31日完成重组","2018年8月11日完成重组，且未申请延期","2018年7月31日获批准延期，延期到2019年8月1日","上述选项均不符合规定"],"answer":"A","explain":"行政重组期限一般不超过12个月，A符合规定。"},{"id":"law-m2-33","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列关于董事与董事会会议决议事项的说法中，错误的是（ ）。","options":["所涉及的企业有关联关系的，董事不得对该项决议行使表决权","所涉及的企业有关联关系的，董事不得代理其他董事行使表决权","出席董事会的无关联关系董事人数不足3人的，应将该事项提交股东会审议","董事会会议应有2/3的董事出席方可举行"],"answer":"D","explain":"董事会会议应有半数以上无关联关系董事出席即可举行。"},{"id":"law-m2-34","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司应当（ ）计算客户交存的担保物价值与其所欠债务的比例。","options":["逐日","每周","逐月","每季度"],"answer":"A","explain":"证券公司应当逐日计算客户交存的担保物价值与其所欠债务的比例。"},{"id":"law-m2-35","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列关于公司对外投资规定的表述，错误的是（ ）。","options":["公司向其他企业投资，依照公司章程的规定，由董事长决定","公司可以向其他企业投资","公司章程对投资总额及单项投资的数额有限额规定的，不得超过规定的限额","公司对外投资，需承担相应的责任"],"answer":"A","explain":"公司向其他企业投资，依照公司章程的规定，由董事会或者股东会决议。"},{"id":"law-m2-36","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"根据《关于规范金融机构资产管理业务的指导意见》，下列关于资产管理产品分级要求的说法，正确的是（ ）。","options":["固定收益类产品分级比例不超过3：1","分级私募产品应根据所投资产的风险程度设定分级比例，中间级份额计入劣后级","期货和衍生品类产品的分级比例不得超过1:1","公募产品不得进行份额分级，私募产品可进行份额分级"],"answer":"A","explain":"固定收益类产品分级比例不超过3：1。"},{"id":"law-m2-37","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"非公开募集基金应当向合格投资者募集，合格投资者累计不得超过（ ）人。","options":["100","200","50","1000"],"answer":"B","explain":"合格投资者累计不得超过200人。"},{"id":"law-m2-38","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司必须持续符合风险控制指标标准的要求，下列能够符合要求的是（ ）。","options":["丙证券公司的流动性覆盖率为80%","丁证券公司的净稳定资金率为40%","甲证券公司的风险覆盖率为120%","乙证券公司的资本杠杆率为6%"],"answer":"C","explain":"风险覆盖率不得低于100%，120%符合要求。"},{"id":"law-m2-39","subject":"law","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"A公司是B公司的全资子公司。2013年，A公司向供应商采购了一批生产物资，至今尚未还款，根据下列情形，说法正确的是（ ）。","options":["付款责任主要由A公司承担，由B公司承担连带责任","付款责任应由B公司承担","付款责任应由A公司承担","付款责任主要由A公司承担，由B公司承担补充责任"],"answer":"C","explain":"子公司具有法人资格，依法独立承担民事责任。"},{"id":"law-m2-40","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"合规负责人应当对证券公司（ ）进行合规审查，并出具书面审核意见。","options":["证券公司内部规章制度","重大决策","新产品方案","日常经营"],"answer":"ABC","explain":"合规审查不包括日常经营。"},{"id":"law-m2-41","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"经营机构发布证券研究报告，应该遵守（ ）。","options":["独立原则","客观原则","效率原则","审慎原则"],"answer":"ABD","explain":"应遵循独立、客观、公平、审慎原则。"},{"id":"law-m2-42","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"股东可以用货币出资，也可以用（ ）等可以用货币估价并可以依法转让的非货币财产作价出资。","options":["劳务","知识产权","股权、债权","土地使用权"],"answer":"BCD","explain":"劳务不得作为出资。"},{"id":"law-m2-43","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"首席风险官及风险管理部门的履职保障的说法中，正确的是（ ）。","options":["证券公司应当保障首席风险官能够充分行使履行职责所必需的知情权","专门部门履行风险管理职责，应当在首席风险官的领导下推动全面风险管理工作","证券公司应当对风险信息汇总管理并实施同一业务层面的风险监测、分析和预警","证券公司风险管理部门具备3年以上的证券、金融、会计、信息技术等有关领域工作经历的人员占公司总部员工比例应不低于15%"],"answer":"ABC","explain":"比例应不低于2%。"},{"id":"law-m2-44","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"甲是A有限责任公司的股东之一。股东会通过决议连续5年不向股东分配利润，而A公司该5年连续盈利，并符合分配利润条件。甲对该项决议投了反对票，以下说法正确的有（ ）。","options":["甲可以请求公司其他股东按照合理的价格收购其股权","甲可以请求公司按照合理的价格收购其股权","甲与公司不能达成股权收购协议的，可以在法定期限内向人民法院提起诉讼","公司收购甲的股权后，应注销甲的出资证明书"],"answer":"BCD","explain":"甲应向公司请求收购股权，而非其他股东。"},{"id":"law-m2-45","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"以下属于行业文化建设要求的是（ ）。","options":["坚持依法合规，筑牢发展基础","坚持稳中推进，促进经济发展","坚持诚实守信，恪守职业操守","坚持专业精神，提升服务能力"],"answer":"ACD","explain":"行业文化建设不包括“稳中推进，促进经济发展”。"},{"id":"law-m2-46","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券研究报告是指证券公司、证券投资咨询机构对证券及证券相关产品的价值、市场走势或者相关影响因素进行分析，形成证券估值、投资评级等投资分析意见而制作的证券研究报告，主要包括的文件有（ ）。","options":["对具体证券的价值分析报告","对证券相关产品的价值分析报告","投资策略报告","行业研究报告"],"answer":"ABCD","explain":"上述均为证券研究报告的类型。"},{"id":"law-m2-47","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司应当妥善保存信息系统（ ）过程中产生的文档，并根据业务开展情况以及信息系统的重要程度建立与监测工作相适应的日志留痕机制。","options":["开发","测试","上线","变更"],"answer":"ABCD","explain":"上述过程均需保存文档。"},{"id":"law-m2-48","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"关于合伙企业的清算，下列说法正确的是（ ）。","options":["合伙企业注销后，原普通合伙人对合伙企业存续期间的债务应承担无限连带责任","合伙企业注销后，原普通合伙人对合伙企业存续期间的债务应承担有限责任","合伙企业依法宣告破产的，普通合伙人对合伙企业债务仍应承担无限连带责任","合伙企业依法宣告破产的，普通合伙人对合伙企业债务仍应承担有限责任"],"answer":"AC","explain":"普通合伙人承担无限连带责任。"},{"id":"law-m2-49","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司在柜台市场发行、销售与转让产品可采取的方式包括但不限于（ ）。","options":["协议","拍卖竞价","标购竞价","集中竞价"],"answer":"ABC","explain":"不得采用集中竞价方式。"},{"id":"law-m2-50","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"关于证券公司的恐怖活动资产冻结工作，下列说法正确的是（ ）。","options":["证券公司采取冻结措施后，无论如何都应当及时告知客户，并说明采取冻结措施的依据和理由","证券公司发现恐怖活动组织及恐怖活动人员拥有或者控制的资产，应立即采取冻结措施","非依法律规定，证券公司不得擅自解除冻结措施","境外有关部门以涉及恐怖活动为由，要求证券公司冻结相关资产、提供客户身份信息及交易信息的，证券公司应当告知对方通过外交途径或者司法协助途径提出请求，不得擅自采取冻结措施"],"answer":"BCD","explain":"除另有要求外，应及时告知客户，并非“无论如何”。"},{"id":"law-m2-51","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"公司的经营原则有（ ）。","options":["遵守法律、行政法规","遵守社会公德、商业道德","诚实守信","承担社会责任"],"answer":"ABCD","explain":"均为公司经营原则。"},{"id":"law-m2-52","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列信息披露违法行为中，应当认定为从重处罚情形的有（ ）。","options":["在信息披露违法案件中变造、隐瞒、毁灭证据，或者提供伪证，妨碍调查","在信息披露上有不良诚信记录并记入证券期货诚信档案","相信专业机构或者专业人员出具的意见和报告","受到股东、实际控制人控制或者其他外部干预"],"answer":"AB","explain":"C、D属于不予处罚或从轻处罚情形。"},{"id":"law-m2-53","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"A证券公司全额包销B公司公开发行的公司债券，销售起始日期为2015年3月1日，则其销售截止日期可选择（ ）。","options":["2015年5月27日","2015年5月28日","2015年5月29日","2015年5月30日"],"answer":"ABC","explain":"承销期限最长90日，截止日期为5月29日，5月30日超期。"},{"id":"law-m2-54","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司从事证券经纪业务，应当客观说明公司业务资格、服务职责、范围等情况，（ ）。","options":["不得提供虚假、误导性信息","不得与投资者约定分享投资收益或者分担投资损失","不得诱导无投资意愿的投资者参与证券交易活动","不得损害投资者合法权益"],"answer":"ABCD","explain":"上述均为禁止行为。"},{"id":"law-m2-55","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列事项中，（ ）属于有限责任公司章程中应当记载的事项。","options":["公司名称和住所","公司经营范围","公司设立时发行的股份数、面额股的每股金额","股东的姓名或者名称"],"answer":"ABD","explain":"C属于股份有限公司章程记载事项。"},{"id":"law-m2-56","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司代销金融产品时，下列行为不被允许的是（ ）。","options":["采取夸大宣传、虚假宣传等方式误导客户购买金融产品","采取抽奖、回扣、赠送实物等方式诱导客户购买金融产品","使用证券公司客户交易结算资金专用存款账户进行合规操作","与客户分享投资收益、分担投资损失"],"answer":"ABD","explain":"C属于合规操作。"},{"id":"law-m2-57","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"国务院证券监督管理机构可以要求（ ），在指定的期限内提供与证券公司经营管理和财务状况有关的资料、信息。","options":["证券公司的董事、监事、工作人员","证券公司的股东、实际控制人","证券公司的股东、实际控制人的配偶","为证券公司提供服务的证券服务机构"],"answer":"ABD","explain":"不包括股东、实际控制人的配偶。"},{"id":"law-m2-58","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"信息披露义务人未按照规定披露信息，或者公告的证券发行文件、定期报告、临时报告及其他信息披露资料存在虚假记载、误导性陈述或者重大遗漏致使投资者遭受损失的，相关责任人应该承担的责任包括（ ）。","options":["信息披露义务人报送的报告或者披露的信息有虚假记载、误导性陈述或者重大遗漏的，责令改正，给予警告，并处以50万元以上500万元以下的罚款","对直接负责的主管人员和其他直接责任人给予警告，并处20万元以上200万元以下罚款","发行人的控股股东、实际控制人组织、指使从事违法行为的，或者隐瞒相关事项导致损失的，处100万元以上1000万元以下的罚款","信息披露义务人报送的报告或者披露的信息有虚假记载、误导性陈述或者重大遗漏的，责令改正，给予警告，并处以100万元以上1000万元以下的罚款"],"answer":"CD","explain":"罚款为100万-1000万，直接责任人罚款50万-500万。"},{"id":"law-m2-59","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"有关保荐代表人制作或者出具的文件不齐备或者不符合要求的，下列说法正确的是（ ）。","options":["中国证监会可以视情节轻重，采取责令改正、监管谈话、出具警示函等监管措施","中国证监会可以视情节轻重，采取监管或者市场禁入措施","情节严重的，中国证监会可以采取暂停保荐机构的保荐业务、依法认定保荐代表人为不适当人选3个月到12个月的监管措施","情节严重的，中国证监会可以采取暂停保荐机构的保荐业务、依法认定保荐代表人为不适当人选3个月到36个月的监管措施"],"answer":"AC","explain":"不适当人选的期限为3-12个月。"},{"id":"law-m2-60","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列事物中，属于法律关系客体的是（ ）。","options":["物","人身、人格","精神成果","行为"],"answer":"ABCD","explain":"上述均为法律关系客体。"},{"id":"law-m2-61","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"资产支持证券可依法（ ）。","options":["继承","交易","转让","出质"],"answer":"ABCD","explain":"资产支持证券可依法继承、交易、转让或出质。"},{"id":"law-m2-62","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列对法的概念的描述，正确的是（ ）。","options":["法是由国家制定或认可并由国家强制力保证实施的","法是反映特定物质生活条件所决定的统治阶级意志","法是以确认、保护和发展对统治阶级有利的社会关系和社会秩序为目的的规范系统","法以保障和约束为内容"],"answer":"ABC","explain":"法以权利和义务为内容。"},{"id":"law-m2-63","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券投资顾问执业行为准则包括（ ）。","options":["证券投资顾问不得为公司及其关联方的利益损害客户利益","证券投资顾问应当根据了解的客户情况，在评估客户风险承受能力和服务需求的基础上，向客户提供适当的投资建议服务，并提示潜在的投资风险","提供投资建议应具有合理依据","不得参与媒体证券节目"],"answer":"ABC","explain":"证券投资顾问可以规范参与媒体证券节目。"},{"id":"law-m2-64","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"出现下列（ ）情况的，应当在国务院证券监督管理机构指定的报刊上公告，并按照规定将经营证券业务许可证交国务院证券监督管理机构注销。","options":["证券公司停止全部证券业务","证券公司解散","证券公司破产","证券公司撤销境内分支机构"],"answer":"ABC","explain":"撤销分支机构无需注销许可证。"},{"id":"law-m2-65","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"根据《刑法》的规定，犯集资诈骗罪的处罚措施有（ ）。","options":["数额较大的，处3年以上7年以下有期徒刑并处罚金","数额巨大或者有其他严重情节的，处7年以上有期徒刑或者无期徒刑，并处罚金或者没收财产","单位犯该罪的，对单位判处罚金","数额特别巨大并且给国家和人民利益造成重大损失的，处无期徒刑或者死刑，并没收财产"],"answer":"ABC","explain":"集资诈骗罪已取消死刑。"},{"id":"law-m2-66","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"以下关于融资融券业务的决策授权体系的说法，错误的有（ ）。","options":["由部门负责人确定融资融券业务的总规模","业务决策机构确定对具体客户的授信额度","业务执行部门确定单一客户的授信额度","分支机构可自行决定客户的开户、保证金收取"],"answer":"ABCD","explain":"董事会确定总规模，业务执行部门确定对具体客户的授信额度，分支机构不得自行决定。"},{"id":"law-m2-67","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"股份有限公司不得收购本公司股份。但是，有下列（ ）情形的，可以收购。","options":["减少公司注册资本","与持有本公司股份的其他公司合并","将股份奖励给本公司职工","股东因对股东会作出的公司合并决议持异议，要求公司收购其股份"],"answer":"ABCD","explain":"上述情形均可回购。"},{"id":"law-m2-68","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列关于背信运用受托财产罪的说法，正确的是（ ）。","options":["背信运用受托财产罪的犯罪主体是特殊主体，即金融机构","背信运用受托财产罪客观上表现为金融机构违背受托义务，擅自运用客户资金或者其他委托、信托的财产的行为，情节严重的","构成本罪的主观方面为过失","本罪既处罚单位，也处罚直接负责的主管人员和其他直接责任人员"],"answer":"ABD","explain":"主观方面为故意。"},{"id":"law-m2-69","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"标准化债权类资产应当同时满足的条件包括（ ）。","options":["等分化，可交易","信息披露充分","公允定价，流动性机制完善","在银行间市场、证券交易所市场等国务院同意设立的交易场所交易"],"answer":"ABCD","explain":"上述均为标准化债权类资产的条件。"},{"id":"law-m2-70","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司风险处置措施中的“破产清算和重组”的说法，正确的是（ ）。","options":["国务院证券监督管理机构或者其委托的行政清理组依照《企业破产法》有关规定，可以向人民检察院申请对被撤销、关闭证券公司进行破产清算","人民法院裁定受理证券公司重整或者破产清算申请的，国务院证券监督管理机构可以向人民法院推荐管理人人选","对不需要动用证券投资者保护基金的证券公司，国务院证券监督管理机构应当在批准破产清算前撤销其证券业务许可","对需要动用证券投资者保护基金的证券公司，国务院证券监督管理机构对该证券公司或者其债权人的破产清算申请不予批准"],"answer":"BCD","explain":"应向人民法院申请，而非人民检察院。"},{"id":"law-m2-71","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列属于利用未公开信息交易罪犯罪主体的是（ ）。","options":["证券公司的从业人员","保险公司的从业人员","期货经纪公司的从业人员","基金管理公司的从业人员"],"answer":"ABCD","explain":"上述均为该罪主体。"},{"id":"law-m2-72","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"下列属于证券投资咨询机构利用“荐股软件”从事证券投资咨询业务应当符合的监督要求是（ ）。","options":["在公司营业场所、公司网站、中国证券业协会网站公示信息","不得对产品功能和服务业绩进行虚假、不实、夸大、误导性的营销宣传","公平对待客户，不得通过诱导客户升级付费等方式，将相同产品以不同价格销售给不同客户","遵循客户适当性原则，制定了解客户的制度和流程，对“荐股软件”产品进行分类升级，并向客户解释产品的特点及风险，将合适的产品销售给适当的客户"],"answer":"ABCD","explain":"上述均为监督要求。"},{"id":"law-m2-73","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"从事私募基金业务活动，应当遵循（ ）的原则。","options":["自愿","平等","诚信","公平"],"answer":"ACD","explain":"私募基金应遵循自愿、公平、诚信原则。"},{"id":"law-m2-74","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司可以从事的业务包括（ ）。","options":["股票期权经纪业务","自营业务","做市业务","与股票期权备兑开仓以及行权相关的证券现货经纪业务"],"answer":"ABC","explain":"D为期货公司的业务。"},{"id":"law-m2-75","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"未经法定机关核准，擅自公开或者变相公开发行证券的，应给予的处罚有（ ）。","options":["责令停止发行","退还所募资金并加算银行同期存款利息","处以5万元以上50万元以下的罚款","对直接负责的主管人员和其他直接责任人员给予警告"],"answer":"ABD","explain":"罚款为非法所募资金金额5%以上50%以下。"},{"id":"law-m2-76","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"以下关于封闭式基金的表述，正确的是（ ）。","options":["封闭式基金的规模是固定的","由基金管理人或者其委托的基金服务机构办理","持有人只能在证券交易场所交易","在基金合同期限内，基金份额持有人不得申购或赎回基金份额"],"answer":"ACD","explain":"封闭式基金在证券交易所交易，不由基金管理人办理申购赎回。"},{"id":"law-m2-77","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"执业声誉信息包括（ ）。","options":["基本信息","表彰奖励信息","违法失信信息","其他执业声誉信息"],"answer":"ABCD","explain":"上述均为执业声誉信息。"},{"id":"law-m2-78","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"财务顾问代表委托人向中国证监会提交申请文件后，应当配合中国证监会的审核，并承担（ ）工作。","options":["指定财务顾问主办人与中国证监会进行专业沟通，并按照中国证监会提出的反馈意见作出回复","按照中国证监会的要求对涉及本次并购重组活动的特定事项进行尽职调查或者核查","组织委托人及其他专业机构对中国证监会的意见进行答复","申报本次担任并购重组财务顾问的收费情况"],"answer":"ABCD","explain":"上述均为财务顾问应承担的工作。"},{"id":"law-m2-79","subject":"law","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷二","q":"当期货市场出现异常情况时，期货交易所可以采取的紧急措施包括（ ）。","options":["调整保证金","调整涨跌停板幅度","调整会员、交易者的交易限额或持仓限额标准","暂时停止交易"],"answer":"ABCD","explain":"上述均为期货交易所可采取的紧急措施。"},{"id":"law-m2-80","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"超过效力期限的违法失信信息，不再进行诚信信息公开，并不再接受诚信信息申请查询。（ ）","options":["正确","错误"],"answer":"A","explain":"该表述正确。"},{"id":"law-m2-81","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"劳务派遣至证券公司的人员属于证券公司的工作人员。（ ）","options":["正确","错误"],"answer":"A","explain":"该表述正确。"},{"id":"law-m2-82","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"中国证监会依法对金融债券的发行进行监督管理。未经中国证监会核准，任何金融机构不得擅自发行金融债券。（ ）","options":["正确","错误"],"answer":"B","explain":"中国人民银行依法对金融债券发行进行监督管理。"},{"id":"law-m2-83","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"从事套期保值等风险管理活动的，可以申请豁免持仓限额。（ ）","options":["正确","错误"],"answer":"A","explain":"该表述正确。"},{"id":"law-m2-84","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"根据《证券公司风险控制指标管理办法》，证券公司应当建立动态的风险控制指标监控和资本补足机制，确保净资本等各项风险控制指标在每个季末都符合规定标准。（ ）","options":["正确","错误"],"answer":"B","explain":"应在任一时点都符合规定标准。"},{"id":"law-m2-85","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"具备证券自营业务资质的证券公司可以设立子公司，从事《证券公司证券自营投资品种清单》所列品种以外的金融产品等投资。该证券公司可以为子公司提供融资或担保。（ ）","options":["正确","错误"],"answer":"B","explain":"证券公司不得为子公司提供融资或担保。"},{"id":"law-m2-86","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司董事会合规管理职责包括审议批准年度合规报告、决定聘任、解聘、考核合规负责人及组织制定公司规章制度。（ ）","options":["正确","错误"],"answer":"B","explain":"组织制定公司规章制度是经营管理主要负责人的职责。"},{"id":"law-m2-87","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司从每年的业务收入中提取交易风险准备金，用于弥补证券经营的损失，其提取的具体比例由国务院证券监督管理机构会同中国人民银行规定。（ ）","options":["正确","错误"],"answer":"B","explain":"会同国务院财政部门规定。"},{"id":"law-m2-88","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"另类子公司持有境内证券交易场所上市交易和转让的证券的，应当将另类子公司与母公司自营持有同一只证券的市值合并计算。（ ）","options":["正确","错误"],"answer":"A","explain":"该表述正确。"},{"id":"law-m2-89","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"李某作为股票自营部门负责人在股票投资业务中给公司带来亏损不属于证券公司的合规管理风险。（ ）","options":["正确","错误"],"answer":"A","explain":"投资亏损不属于合规风险。"},{"id":"law-m2-90","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券基金经营机构董事长、高级管理人员、分支机构负责人离任的，证券基金经营机构应当对其进行审计，并自其离任之日起3个月内将离任审计报告向中国证监会相关派出机构报告。（ ）","options":["正确","错误"],"answer":"B","explain":"应在2个月内报告。"},{"id":"law-m2-91","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"财务顾问应当建立并购重组工作档案和工作底稿制度，为每一个项目建立独立的工作档案。财务顾问的工作档案和工作底稿应当真实、准确、完整，保存期不少于20年。（ ）","options":["正确","错误"],"answer":"B","explain":"保存期不少于10年。"},{"id":"law-m2-92","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"客户先前提交的身份证件或者身份证明文件已过有效期，客户没有在合理期限内更新且没有提出合理理由的，证券公司应当立即冻结其账户。（ ）","options":["正确","错误"],"answer":"B","explain":"应采取限制办理新业务、限制资金转出等措施，而非冻结。"},{"id":"law-m2-93","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司委托其他证券公司或者基金管理公司进行证券投资管理，且投资规模合计不超过其净资本80%的，无须取得证券自营业务资格。（ ）","options":["正确","错误"],"answer":"A","explain":"该表述正确。"},{"id":"law-m2-94","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"公开募集基金财产应当用于投资上市交易的股票、债券或国务院证券监督管理机构规定的其他证券及其衍生品种。（ ）","options":["正确","错误"],"answer":"A","explain":"该表述正确。"},{"id":"law-m2-95","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司应当遵循最多功能以及最大权限等原则分配信息系统管理、操作和访问权限，并履行审批流程。（ ）","options":["正确","错误"],"answer":"B","explain":"应遵循最少功能及最小权限原则。"},{"id":"law-m2-96","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"拟任证券经营机构分支机构负责人的人员，应当具备3年以上与其拟任职务相关的证券、基金、金融、法律、会计、信息技术等工作经历。（ ）","options":["正确","错误"],"answer":"A","explain":"该表述正确。"},{"id":"law-m2-97","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司的自营、受托投资管理、财务顾问和投资银行等业务部门的专业人员在离开原岗位后的3个月内不得从事面向社会公众开展的证券投资咨询业务。（ ）","options":["正确","错误"],"answer":"B","explain":"应在6个月内不得从事。"},{"id":"law-m2-98","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"担任发行人股票首次公开发行的保荐机构、主承销商，自确定并公告发行价格之日起30日内，不得发布与该发行人有关的证券研究报告。（ ）","options":["正确","错误"],"answer":"B","explain":"应在40日内不得发布。"},{"id":"law-m2-99","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"未向社会公开宣传，在亲友或者单位内部针对特定对象吸收资金的，不属于非法吸收或者变相吸收公众存款。（ ）","options":["正确","错误"],"answer":"A","explain":"该表述正确。"},{"id":"law-m2-100","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券分析师最多同时在两家机构任职。（ ）","options":["正确","错误"],"answer":"B","explain":"证券分析师只能在一家证券经营机构执业。"},{"id":"law-m2-101","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司应当至少每年经主要负责人、首席风险官签署确认后，向公司全体董事报告一次公司净资本等风险控制指标的具体情况和达标情况。（ ）","options":["正确","错误"],"answer":"B","explain":"应至少每半年报告一次。"},{"id":"law-m2-102","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司自营权益类证券及其衍生品的合计额不得超过净资本的500%。（ ）","options":["正确","错误"],"answer":"B","explain":"不得超过净资本的100%。"},{"id":"law-m2-103","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司董事会负责建立信息技术人力和资金保障方案。（ ）","options":["正确","错误"],"answer":"A","explain":"该表述正确。"},{"id":"law-m2-104","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"证券公司合并、分立的，国务院证券监督管理机构应当对合并、分立的申请进行审查，并在自受理之日起30日内作出核准或者不予核准的书面决定。（ ）","options":["正确","错误"],"answer":"B","explain":"应在3个月内作出决定。"},{"id":"law-m2-105","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"从事证券投资顾问业务的营销、客服等直接为客户提供服务，但不涉及向客户提供投资建议的业务人员无须进行从业人员登记。（ ）","options":["正确","错误"],"answer":"B","explain":"应登记为从事一般证券业务。"},{"id":"law-m2-106","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"审计委员会中独立董事的人数不得少于1/2，并且至少有1名独立董事从事会计工作3年以上。（ ）","options":["正确","错误"],"answer":"B","explain":"从事会计工作5年以上。"},{"id":"law-m2-107","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"认沽期权，指买方有权在将来特定时间以特定价格买入约定数量合约标的的期权合约。（ ）","options":["正确","错误"],"answer":"B","explain":"认沽期权是卖出，认购期权是买入。"},{"id":"law-m2-108","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"经营机构无权自主决定是否同意投资者转化为专业投资者。（ ）","options":["正确","错误"],"answer":"B","explain":"经营机构有权自主决定。"},{"id":"law-m2-109","subject":"law","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷二","q":"某个人投资者要参加上交所科创板股票交易，其申请权限开通前20个交易日证券账户及资金账户内的资产日均不低于人民币50万元。（ ）","options":["正确","错误"],"answer":"A","explain":"该表述正确。"},{"id":"law-m2-110","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷二","q":"【资料】甲证券公司严格执行《证券期货经营机构及其工作人员廉洁从业规定》，把廉洁从业管理作为净化企业、提升员工执业道德的重要手段，推进公司的文化建设。请回答1-2题。\n\n【问题】（1）甲证券公司将廉洁从业制度纳入内部控制制度中，下列关于该公司廉洁从业责任承担的说法，正确的是（ ）。","options":["甲证券公司承担廉洁从业风险防控主体责任","甲证券公司的合规总监并不负责落实廉洁从业管理目标","甲证券公司的董事会对廉洁从业管理的有效性承担责任","甲证券公司的各级负责人在职责范围内对落实廉洁从业承担相应管理职责"],"answer":"ACD","explain":"合规总监属于高级管理人员，负责落实廉洁从业管理目标。"},{"id":"law-m2-111","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷二","q":"【资料】甲证券公司严格执行《证券期货经营机构及其工作人员廉洁从业规定》，把廉洁从业管理作为净化企业、提升员工执业道德的重要手段，推进公司的文化建设。请回答1-2题。\n\n【问题】（2）根据《证券期货经营机构及其工作人员廉洁从业规定》，甲证券公司的下列做法，错误的是（ ）。","options":["将工作人员廉洁从业情况纳入人力资源管理体系，对工作人员廉洁从业情况予以考察评估，离职情形除外","对所从事的业务种类、环节及相关工作进行科学、系统的廉洁风险评估，识别廉洁从业风险点，强化岗位制衡与内部监督机制并确保运作有效","制定覆盖全体工作人员的廉洁从业规范","建立健全廉洁从业内部控制制度，制定具体、有效的事前风险防范体系、事中管控措施和事后追责机制"],"answer":"A","explain":"离职情形也应纳入考察评估。"},{"id":"law-m2-112","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷二","q":"【资料】朱某系甲证券公司副总经理，2020年5月，朱某与甲证券公司原总经理牛某共谋，通过集中资金优势、持股优势，连续买卖等手段影响乙公司的股票交易，牟取非法利益。请回答1-3题。\n\n【问题】（1）朱某和牛某的上述行为，构成了（ ）。","options":["操纵证券、期货市场罪","背信运用受托财产罪","内幕交易、泄露内幕信息罪","诱骗投资者买卖证券、期货合约罪"],"answer":"A","explain":"集中资金优势连续买卖影响股票交易，构成操纵证券、期货市场罪。"},{"id":"law-m2-113","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷二","q":"【资料】朱某系甲证券公司副总经理，2020年5月，朱某与甲证券公司原总经理牛某共谋，通过集中资金优势、持股优势，连续买卖等手段影响乙公司的股票交易，牟取非法利益。请回答1-3题。\n\n【问题】（2）朱某和牛某的下列行为中，应予立案追诉的情形有（ ）。","options":["朱某最高持有乙公司股票占总流通股38%","在朱某控制的账户内，乙公司股票成交量多次占同期该股票连续20个交易日成交总量的30%以上","牛某对乙公司股票公开作出评价，同时进行反向证券交易，证券交易成交额在500万元以上","朱某和牛某的获利数额为3000万元"],"answer":"ABD","explain":"反向交易成交额应在1000万元以上。"},{"id":"law-m2-114","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷二","q":"【资料】朱某系甲证券公司副总经理，2020年5月，朱某与甲证券公司原总经理牛某共谋，通过集中资金优势、持股优势，连续买卖等手段影响乙公司的股票交易，牟取非法利益。请回答1-3题。\n\n【问题】（3）朱某和牛某的犯罪情节特别严重，故判处（ ）有期徒刑，并处罚金。","options":["3年以上5年以下","5年以上10年以下","3年以上7年以下","7年以上10年以下"],"answer":"B","explain":"情节特别严重的，处5年以上10年以下有期徒刑。"},{"id":"law-m2-115","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷二","q":"【资料】丙证券公司未将合规职责与风控职责严格区分，合规部内设风险经理岗，承担财富管理业务部、场外业务部、托管业务部风险管理职责；部分分支机构合规管理人员不具备相关工作经验；部分合规人员薪酬低于公司同级别平均水平；对下属子公司现场合规检查不足，近三年仅开展过1次；对合规有效性评估中发现问题的规范力度不足，前期评估发现问题未完成落实规范。请回答1-3题。\n\n【问题】（1）证监会要求丙证券公司（ ）应当按照《证券公司和证券投资基金管理公司合规管理办法》的要求，督促下属各单位为合规管理人员履职提供有效保障。","options":["董事会","监事会","经营管理主要负责人","下属各单位负责人"],"answer":"C","explain":"经营管理主要负责人应当督促下属各单位为合规管理人员履职提供有效保障。"},{"id":"law-m2-116","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷二","q":"【资料】丙证券公司未将合规职责与风控职责严格区分，合规部内设风险经理岗，承担财富管理业务部、场外业务部、托管业务部风险管理职责；部分分支机构合规管理人员不具备相关工作经验；部分合规人员薪酬低于公司同级别平均水平；对下属子公司现场合规检查不足，近三年仅开展过1次；对合规有效性评估中发现问题的规范力度不足，前期评估发现问题未完成落实规范。请回答1-3题。\n\n【问题】（2）丙证券公司的分支机构应当配备具备（ ）年以上证券、金融、法律、会计、信息技术等有关领域工作经历，具备与履行合规管理职责相适应的专业知识和技能的合规管理人员。","options":["1","2","3","4"],"answer":"C","explain":"应具备3年以上相关工作经历。"},{"id":"law-m2-117","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷二","q":"【资料】丙证券公司未将合规职责与风控职责严格区分，合规部内设风险经理岗，承担财富管理业务部、场外业务部、托管业务部风险管理职责；部分分支机构合规管理人员不具备相关工作经验；部分合规人员薪酬低于公司同级别平均水平；对下属子公司现场合规检查不足，近三年仅开展过1次；对合规有效性评估中发现问题的规范力度不足，前期评估发现问题未完成落实规范。请回答1-3题。\n\n【问题】（3）丙证券公司应当配备专职合规管理人员的部门及机构包括（ ）。","options":["自营部门","投资银行部门","工作人员人数在10人及以上的分支机构","证券公司异地总部"],"answer":"ABD","explain":"工作人员人数在15人及以上的分支机构才需配备专职合规管理人员。"},{"id":"law-m2-118","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷二","q":"【资料】张某担任甲证券公司私募资产管理业务投资经理。2022年6月1日，张某从甲证券公司离任，拟入职乙证券公司担任私募资产管理业务投资经理，从事投资业务。请回答1-2题。\n\n【问题】（1）张某作为私募资产管理业务的投资经理，应当具备（ ）。","options":["依法取得的基金从业资格","2年以上投资管理、投资研究、投资咨询等相关业务经验","良好的诚信记录和职业操守","法律法规规定的其他条件"],"answer":"ACD","explain":"投资经理应具备3年以上相关业务经验。"},{"id":"law-m2-119","subject":"law","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷二","q":"【资料】张某担任甲证券公司私募资产管理业务投资经理。2022年6月1日，张某从甲证券公司离任，拟入职乙证券公司担任私募资产管理业务投资经理，从事投资业务。请回答1-2题。\n\n【问题】（2）甲、乙证券公司应当针对私募资产管理业务的主要业务人员和相关管理人员建立收入递延支付机制，递延支付年限原则上不少于（ ）年。","options":["1","2","3","4"],"answer":"C","explain":"递延支付年限原则上不少于3年。"}]},{"id":"basics-mt","subject":"basics","name":"金融 · 章节母题","stats":{"单选":88,"多选":101,"判断":51,"案例":0},"questions":[{"id":"basics-mt-0","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"金融市场是要素市场的一种，是以（ ）为交易对象而形成的供求关系和交易机制的总和。","options":["金融资产","金融负债","股票","债券"],"answer":"A","explain":"金融市场是创造和交易金融资产的市场，以金融资产为交易对象。"},{"id":"basics-mt-1","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"现代金融市场以有形市场为主。（ ）","options":["正确","错误"],"answer":"B","explain":"现代金融市场往往是无形的市场，并非有形市场为主。"},{"id":"basics-mt-2","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"常见的直接融资的方式有（ ）。","options":["银行信用融资","商业信用融资","股票市场融资","风险投资融资"],"answer":"BCD","explain":"直接融资方式包括股票市场融资、债券市场融资、风险投资融资、商业信用融资等。银行信用融资属于间接融资。"},{"id":"basics-mt-3","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"股份制企业以让渡一定的企业经营控制权、收益分配权和剩余索取权而获得企业经营资金的一种方式是（ ）。","options":["股票市场融资","债券市场融资","风险投资融资","民间借贷"],"answer":"A","explain":"股票市场融资是股份制企业以让渡控制权、收益分配权和剩余索取权获得资金的方式。"},{"id":"basics-mt-4","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"金融市场的重要性主要体现在（ ）。","options":["促进储蓄-投资转化","优化资源配置","风险管理","宏观调控"],"answer":"ABD","explain":"金融市场重要性包括促进储蓄投资转化、优化资源配置、反映经济状态、宏观调控。风险管理不是其直接重要性。"},{"id":"basics-mt-5","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"金融市场通过竞争性的价格决定（利率），将货币资金配置到生产效率最高的经济主体或部门，这反映了金融市场优化资源配置的作用。（ ）","options":["正确","错误"],"answer":"A","explain":"该描述正确，反映了金融市场优化资源配置的作用。"},{"id":"basics-mt-6","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"下列关于金融市场分类错误的是（ ）。","options":["按照发行流通性质划分可以分为一级市场和二级市场","按照组织方式可以分为交易所市场和场外交易市场","按照交易工具可分为债权市场和权益市场","按照金融工具上所约定的期限长短划分可以分为现货市场和衍生品市场"],"answer":"D","explain":"按交割方式分现货市场和衍生品市场，不是按期限长短。"},{"id":"basics-mt-7","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"下列选项中，不属于货币市场的是（ ）。","options":["商业票据市场","短期国库券市场","银行间同业拆借市场","股票市场"],"answer":"D","explain":"股票市场属于资本市场，不属于货币市场。"},{"id":"basics-mt-8","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"世界上最早的证券交易所是（ ）。","options":["纽约证券交易所","费城证券交易所","阿姆斯特丹证券交易所","伦敦证券交易所"],"answer":"C","explain":"1602年荷兰东印度公司创建了阿姆斯特丹证券交易所，是世界上最早的证券交易所。"},{"id":"basics-mt-9","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"1944年布雷顿森林体系会议后，（ ）成为世界金融中心。","options":["伦敦","纽约","东京","华盛顿"],"answer":"B","explain":"布雷顿森林体系确立以美元为中心，纽约成为世界金融中心。"},{"id":"basics-mt-10","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"国际金融监管体系包括（ ）。","options":["巴塞尔银行监管委员会","国际保险监督官协会","中国证券监督管理委员会","国际证监会组织"],"answer":"ABD","explain":"国际金融监管体系包括巴塞尔银行监管委员会、国际证监会组织、国际保险监督官协会等。"},{"id":"basics-mt-11","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"中国证监会于（ ）年成为IOSCO的正式成员。","options":["1994","1995","1996","1997"],"answer":"B","explain":"中国证监会于1995年成为IOSCO正式成员。"},{"id":"basics-mt-12","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"英国是全球最大的金融服务出口国。（ ）","options":["正确","错误"],"answer":"A","explain":"英国是全球最大的金融服务出口国。"},{"id":"basics-mt-13","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"金融业区域内短期资金成本的基准指标包括（ ）。","options":["SHIBOR","HIBOR","EURIBOR","TIBOR"],"answer":"ABCD","explain":"SHIBOR、HIBOR、EURIBOR、TIBOR均为区域短期资金成本基准指标。"},{"id":"basics-mt-14","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"自2006年之后，纳斯达克的分层制度将市场分为（ ）三个板块。","options":["纳斯达克全球精选市场","纳斯达克货币市场","纳斯达克资本市场","纳斯达克全球市场"],"answer":"ACD","explain":"纳斯达克分为全球精选市场、全球市场和资本市场三个板块。"},{"id":"basics-mt-15","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"纽约证券交易所交易制度模式的特征包括（ ）。","options":["指定做市商制度","场内经纪商制度","场外经纪商制度","补充流动性提供商制度"],"answer":"ABD","explain":"纽交所交易制度特征包括指定做市商、场内经纪商和补充流动性提供商制度。"},{"id":"basics-mt-16","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"香港是全球最活跃及流动性最高的证券市场之一。（ ）","options":["正确","错误"],"answer":"A","explain":"香港是全球最活跃及流动性最高的证券市场之一。"},{"id":"basics-mt-17","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"中国香港的金融监管机构包括（ ）。","options":["中国香港金融管理局","中国香港政府","证券及期货事务监察委员会","保险业监理处"],"answer":"ACD","explain":"香港金融监管机构包括金融管理局、证券及期货事务监察委员会、保险业监理处。"},{"id":"basics-mt-18","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"下列对我国金融市场的发展现状的描述中，正确的是（ ）。","options":["“大一统”的单一银行体系","交易场所多层次","交易品种多样化","交易机制多元化"],"answer":"BCD","explain":"目前中国金融市场具有交易场所多层次、交易品种多样化、交易机制多元化的特征。“大一统”是改革前的特征。"},{"id":"basics-mt-19","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"利率对金融市场的影响是局部的、非系统的。（ ）","options":["正确","错误"],"answer":"B","explain":"利率对金融市场的影响是系统性、全局性的。"},{"id":"basics-mt-20","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"按业务特征及货币创造、交换媒介和支付手段的能力划分，金融中介机构可以划分为商业性金融机构和政策性金融机构。（ ）","options":["正确","错误"],"answer":"B","explain":"按业务特征划分应为银行金融中介机构和非银行金融中介机构。"},{"id":"basics-mt-21","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"商业银行负债业务中借款负债的渠道主要包括（ ）。","options":["向中央银行借款","同业借款","股票融资","回购协议"],"answer":"ABD","explain":"借款负债渠道包括向中央银行借款、同业借款、回购协议等。股票融资不是借款负债。"},{"id":"basics-mt-22","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"一般来说，中央银行的主要职能概括为（ ）。","options":["“发行的银行”","“银行的银行”","“监管的银行”","“政府的银行”"],"answer":"ABD","explain":"中央银行主要职能为发行的银行、银行的银行、政府的银行。"},{"id":"basics-mt-23","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"货币政策的最终目标包括（ ）。","options":["促进国际化","稳定物价","促进经济增长","促进证券市场发展"],"answer":"BC","explain":"货币政策最终目标包括稳定物价、经济增长、充分就业、国际收支平衡、金融稳定。"},{"id":"basics-mt-24","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"按照交易产品品种的不同，可以将资本市场分为（ ）。","options":["股票市场","债券市场","衍生品市场","基金市场"],"answer":"ABCD","explain":"资本市场按品种分为股票、债券、衍生品、基金市场。"},{"id":"basics-mt-25","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"资本市场的多层次性体现在（ ）。","options":["投资者结构的多层次性","中介机构和监管体系的多层次性","交易定价的多样性","交割清算方式的多样性"],"answer":"ABCD","explain":"多层次资本市场体现在投资者结构、中介监管体系、交易定价、交割清算方式的多样性。"},{"id":"basics-mt-26","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"为具有高成长性的中小企业和高科技企业提供融资服务，又称为二板市场的是（ ）。","options":["证券交易所市场","银行间市场","创业板市场","中小企业板市场"],"answer":"C","explain":"创业板市场又称二板市场，为高成长性中小企业和高科技企业融资服务。"},{"id":"basics-mt-27","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"目前，全国中小企业股份转让系统挂牌公司的转让类型包括（ ）。","options":["审批","协议","注册","做市"],"answer":"BD","explain":"新三板转让方式包括协议、做市、竞价等。"},{"id":"basics-mt-28","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"多层次资本市场的意义包括（ ）。","options":["有利于调动民间资本的积极性，转储蓄为投资","有利于创新宏观调控机制，提高间接融资比重，防范和化解经济风险","有利于促进科技创新，促进新兴产业发展和经济转型","有利于促进产业整合，缓解产能过剩"],"answer":"ACD","explain":"多层次资本市场的意义不包括提高间接融资比重，而是提高直接融资比重。"},{"id":"basics-mt-29","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"我国首个实行注册制的场内市场是（ ）。","options":["科创板市场","创业板市场","主板市场","全国中小企业股份转让系统"],"answer":"A","explain":"科创板是我国首个实行注册制的场内市场。"},{"id":"basics-mt-30","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"新“国九条”发布以来，形成了“1+N”政策体系，其中“1”是对应的配套制度规则，“N”是新“国九条”主要相关内容。（ ）","options":["正确","错误"],"answer":"B","explain":"“1”是新“国九条”本身，“N”是配套制度规则。"},{"id":"basics-mt-31","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"证券市场融资活动是指（ ）之间以有价证券为媒介，实现资金融通的金融活动。","options":["公司（企业）和个人投资者","资金盈余单位和赤字单位","证券发行单位和证券投资单位","证券公司和普通投资者"],"answer":"B","explain":"证券市场融资活动是资金盈余单位和赤字单位之间以有价证券为媒介的资金融通。"},{"id":"basics-mt-32","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"通过证券市场进行的融资属于（ ）。","options":["股权融资","债权融资","间接融资","直接融资"],"answer":"D","explain":"证券市场融资属于直接融资。"},{"id":"basics-mt-33","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"可以作为证券发行人的机构主要包括（ ）。","options":["商业银行","企业","慈善机构","政府机构"],"answer":"ABD","explain":"证券发行人包括政府及其机构、企业、金融机构。慈善机构不能作为证券发行人。"},{"id":"basics-mt-34","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"政府作为债券发行的重要主体之一，所筹集的资金可以用来（ ）。","options":["协调财政资金短期周转，弥补财政赤字","兴建政府投资的大型基础性的建设项目","实施某项特殊政策","弥补战争费用的开支"],"answer":"ABCD","explain":"政府发行债券资金可用于短期周转、弥补赤字、兴建项目、实施特殊政策、弥补战争费用。"},{"id":"basics-mt-35","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"证券投资者是证券市场的资金供给者，众多的证券投资者保证了证券（ ）的连续性。","options":["发行和交易","发行","流通","交易"],"answer":"A","explain":"证券投资者保证了证券发行和交易的连续性。"},{"id":"basics-mt-36","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"（ ）是证券市场最广泛的投资者。","options":["个人投资者","金融机构类投资者","政府机构类投资者","基金类投资者"],"answer":"A","explain":"个人投资者是证券市场最广泛的投资者。"},{"id":"basics-mt-37","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"中央银行参与证券投资的目的主要是为了（ ）。","options":["套期保值","实现盈利","影响汇率","宏观调控"],"answer":"D","explain":"中央银行参与证券投资主要是为了宏观调控。"},{"id":"basics-mt-38","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"在我国，基金性质的机构投资者包括（ ）。","options":["证券投资基金","社保基金","社会公益基金","企业年金"],"answer":"ABCD","explain":"基金性质的机构投资者包括证券投资基金、社保基金、社会公益基金、企业年金等。"},{"id":"basics-mt-39","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"个人投资者投资行为的特点不包括（ ）。","options":["随意性","专业性","分散性","短期性"],"answer":"B","explain":"个人投资者特点包括随意性、分散性、短期性，不包括专业性。"},{"id":"basics-mt-40","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"金融机构通常采用客户调查问卷、产品风险评估、充分披露等方法，根据客户分级和（ ）匹配原则，避免错误销售。","options":["产品规模","资产分级","产品收益","客户风险"],"answer":"B","explain":"根据客户分级和资产分级匹配原则。"},{"id":"basics-mt-41","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"既是证券市场上的主要中介机构，又是证券市场上重要的机构投资者的是（ ）。","options":["会计师事务所","证券公司","资产评估事务所","投资咨询公司"],"answer":"B","explain":"证券公司既是中介机构，也是重要的机构投资者。"},{"id":"basics-mt-42","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"我国股权分置改革试点工作开始于（ ）。","options":["2004","2000","2007","2005"],"answer":"D","explain":"2005年4月股权分置改革启动。"},{"id":"basics-mt-43","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"（ ）是指证券公司、证券投资咨询机构接受客户委托，按照约定，向客户提供涉及证券及证券相关产品的投资建议服务，辅助客户作出投资决策，并直接或者间接获取经济利益的经营活动。","options":["证券经纪业务","证券投资顾问业务","证券投资咨询业务","证券资产管理业务"],"answer":"B","explain":"证券投资顾问业务是提供投资建议服务并获取经济利益的经营活动。"},{"id":"basics-mt-44","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"证券承销是指证券公司代理证券发行人发行证券的行为，证券承销业务可以采取的方式有（ ）。","options":["代销","全额包销","余额包销","自销"],"answer":"ABC","explain":"证券承销方式包括代销、全额包销、余额包销。自销不是承销方式。"},{"id":"basics-mt-45","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"1998年亚洲金融危机后，国内证券公司开始加快国际化步伐，国内证券公司“走出去”的过程中也存在一些问题，这些问题包括（ ）。","options":["部分机构下设机构较多，层级较多，内部架构不清晰，管控不到位","部分机构将业务拓展至非金融业务领域","部分机构返程境内设立子公司从事与母公司同质或相似的业务","证券基金经营机构对境外机构管控不足，存在风险隐患"],"answer":"ABCD","explain":"均为证券公司“走出去”存在的问题。"},{"id":"basics-mt-46","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"《证券公司和证券投资基金管理公司境外设立、收购、参股经营机构管理办法》，主要内容包括以下（ ）。","options":["维持适当门槛，支持机构“走出去”","规范业务范围，完善组织架构","督促母公司加强管控，完善境外机构管理","加强持续监管，完善跨境监管合作"],"answer":"ABCD","explain":"该办法主要内容包括上述四个方面。"},{"id":"basics-mt-47","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"会计师事务所为证券的发行、上市、挂牌、交易等证券业务活动制作、出具（ ），应当按照规定向中国证监会和国务院有关主管部门备案。","options":["财务报表审计报告","内部控制鉴证报告","盈利预测审核报告","验资报告"],"answer":"ABCD","explain":"会计师事务所从事证券服务业务，出具上述报告均需备案。"},{"id":"basics-mt-48","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"下列服务属于证券投资咨询服务的是（ ）。","options":["接受投资人或者客户委托，提供证券投资咨询服务","举办有关证券投资咨询的讲座、报告会、分析会等","在报刊上发表证券投资咨询的文章、评论、报告，以及通过电台、电视台等公众传播媒体提供证券投资咨询服务","通过电话、传真、电脑网络等电信设备系统，提供证券投资咨询服务"],"answer":"ABCD","explain":"上述均为证券投资咨询的形式。"},{"id":"basics-mt-49","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"整个证券市场的核心是（ ）。","options":["证券发行人","证券交易所","中国证监会","国务院"],"answer":"B","explain":"证券交易所是整个证券市场的核心。"},{"id":"basics-mt-50","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"会员制证券交易所是一个由会员自愿组成，不以盈利为目的的（ ）。","options":["金融机构","证券服务机构","社会法人团体","企业法人"],"answer":"C","explain":"会员制证券交易所是不以营利为目的的社会法人团体。"},{"id":"basics-mt-51","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"中国证券业协会是根据（ ）的有关规定设立的证券业自律性组织。","options":["《证券法》","《社会团体登记管理条例》","《公司法》","《公司登记管理条例》"],"answer":"AB","explain":"中国证券业协会依据《证券法》和《社会团体登记管理条例》设立。"},{"id":"basics-mt-52","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"代表中国证券业加入相关国际组织、推动相关资质互认的是（ ）。","options":["中国证监会","证券交易所","中国证券业协会","外交部"],"answer":"C","explain":"中国证券业协会代表中国证券业加入相关国际组织。"},{"id":"basics-mt-53","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"下列关于证券交易参与各方的说法，正确的是（ ）。","options":["证券投资主体只包括自然人","证券公司只有有限责任公司一种形式","证券交易所是不以营利为目的的公司制法人","中国证券登记结算有限责任公司是不以营利为目的的法人"],"answer":"D","explain":"中国结算是为证券交易提供集中登记、存管与结算服务，不以营利为目的的法人。"},{"id":"basics-mt-54","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"目前，我国对证券交易所达成的多数证券交易均采用多边（ ）方式。","options":["净额结算","足额结算","全额结算","余额结算"],"answer":"A","explain":"我国证券交易所多数证券交易采用多边净额结算方式。"},{"id":"basics-mt-55","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"当证券投资者保护基金有限责任公司发现证券公司经营管理中出现可能危及（ ）的重大风险时，应当及时向有关部门提出监管、处置建议。","options":["投资者利益","证券公司利益","监管部门利益","证券市场安全"],"answer":"AD","explain":"危及投资者利益和证券市场安全时提出监管建议。"},{"id":"basics-mt-56","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"证券公司应缴纳的证券投资者保护基金，由（ ）代扣代收。","options":["中国证券登记有限责任公司","中国证监会","证券交易所","中国证券业协会"],"answer":"A","explain":"由中登公司代扣代收。"},{"id":"basics-mt-57","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"投服中心作为依据国务院证券监督管理机构设立的投资者保护机构，可根据（ ）开展相关投资者保护工作。","options":["《公司法》","《证券公司监督管理条例》","《证券投资者保护基金管理办法》","《证券法》"],"answer":"D","explain":"投服中心依据《证券法》开展投资者保护工作。"},{"id":"basics-mt-58","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"投资者保护机构可以作为诉讼代表人，按照（ ）的原则，依法为受害投资者提起民事损害赔偿诉讼。","options":["默示退出、明示加入","默示退出、默示加入","明示退出、默示加入","明示退出、明示加入"],"answer":"C","explain":"按照“明示退出、默示加入”的原则。"},{"id":"basics-mt-59","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"证券市场监管的意义有（ ）。","options":["加强证券市场监管是保障广大投资者合法权益的需要","加强证券市场监管是维护市场良好秩序的需要","加强证券市场监管是发展和完善证券市场体系的需要","准确和全面的信息是证券市场参与者进行发行和交易决策的重要依据"],"answer":"ABCD","explain":"均为证券市场监管的意义。"},{"id":"basics-mt-60","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"证券市场监管的原则有（ ）。","options":["依法监管原则","保护投资者利益原则","“三公”原则","监督与自律相结合原则"],"answer":"ABCD","explain":"证券市场监管原则包括依法监管、保护投资者利益、“三公”原则、监督与自律相结合。"},{"id":"basics-mt-61","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"下列选项中，不属于国际证监会公布的证券监管目标的是（ ）。","options":["保护投资者","保证证券市场的公平、效率和透明","降低非系统风险","降低系统性风险"],"answer":"C","explain":"国际证监会证券监管目标不包括降低非系统风险。"},{"id":"basics-mt-62","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"证券市场监管的（ ）相对比较灵活，但调节过程可能较慢，存在时滞。","options":["行政手段","经济手段","司法手段","法律手段"],"answer":"B","explain":"经济手段相对灵活，但调节过程可能较慢，存在时滞。"},{"id":"basics-mt-63","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"我国证券市场经过20多年的发展，逐步形成了以（ ）为一体的监管体系和自律管理体系。","options":["国务院证券监督管理机构及派出机构","证券投资者保护基金公司","证券交易所","证券业协会"],"answer":"ABCD","explain":"监管体系包括证监会及派出机构、投资者保护基金、证券交易所、证券业协会。"},{"id":"basics-mt-64","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"在调查操纵证券市场，内幕交易等重大证券违法行为时，经批准，可以限制被调查事件当事人的证券买卖，但限制的期限不得超过（ ）个月；案情复杂的，可以延长。","options":["1","2","3","4"],"answer":"C","explain":"限制期限不得超过3个月。"},{"id":"basics-mt-65","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"股票分割又称拆股、拆细，股票分割之后，每股股票的市价不变。（ ）","options":["正确","错误"],"answer":"B","explain":"股票分割后每股股票市价下降。"},{"id":"basics-mt-66","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"派现是指股份公司以现金分红方式将（ ）的部分或全部发放给股东。","options":["盈余公积","当期应付利润","未分配利润","留存收益"],"answer":"AB","explain":"派现是现金分红方式，将盈余公积和当期应付利润的部分或全部发放给股东。"},{"id":"basics-mt-67","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"下列关于股东权利的表述，正确的是（ ）。","options":["股份公司召开股东大会，普通股票股东享有出席会议的平等权利","普通股票股东与优先股股东享有平等的表决权","股东出席股东大会所持每一股份都有一单位表决权","股东会作出决议，必须经过出席会议的股东代表所持表决权的2/3以上通过"],"answer":"AC","explain":"普通股股东享有出席会议权利，每一股份有一表决权。优先股股东表决权受限。"},{"id":"basics-mt-68","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"普通股股东在股份公司解散清算时，有权要求取得公司按规定清偿后的（ ）。","options":["银行存款","注册资本","剩余财产","剩余资金"],"answer":"C","explain":"普通股股东享有剩余资产分配权，取得清偿后的剩余财产。"},{"id":"basics-mt-69","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"优先股的清偿顺序先于普通股，而次于债权人。（ ）","options":["正确","错误"],"answer":"A","explain":"优先股清偿顺序先于普通股，次于债权人。"},{"id":"basics-mt-70","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"下列关于优先股的说法中，正确的是（ ）。","options":["收入稳定","风险较大","适宜中长线投资","国外大部分优先股为稳健型机构投资者持有"],"answer":"ACD","explain":"优先股收入稳定、风险较低、适宜中长线投资，多为稳健型机构投资者持有。"},{"id":"basics-mt-71","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"股份公司向外国和我国香港、澳门、台湾地区投资者发行的股票，称为（ ）。","options":["国有股","法人股","社会公众股","外资股"],"answer":"D","explain":"外资股是向外国和港澳台地区投资者发行的股票。"},{"id":"basics-mt-72","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"关于股票的简称，下列说法正确的有（ ）。","options":["N股代表新加坡股","L股代表伦敦股","B股代表境内上市外资股","H股代表港股"],"answer":"BCD","explain":"N股代表纽约股，S股代表新加坡股。B股是境内上市外资股，H股是港股。"},{"id":"basics-mt-73","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"股票发行制度主要有（ ）。","options":["审批制","核准制","注册制","监管制"],"answer":"ABC","explain":"股票发行制度包括审批制、核准制、注册制。"},{"id":"basics-mt-74","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"保荐人的保荐责任期包括（ ）。","options":["发行上市全过程","对发行的股票承担终身责任","发行上市后一段时间","递交上市申请材料期间"],"answer":"AC","explain":"保荐责任期包括发行上市全过程及上市后一段时间。"},{"id":"basics-mt-75","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"《证券发行与承销管理办法》规定，战略投资者应当承诺获得配售的股票持有期限为（ ）。","options":["6个月以上","12个月以上","1个月以上","3个月以上"],"answer":"B","explain":"战略投资者持股期限不少于12个月。"},{"id":"basics-mt-76","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"北京证券交易所发行人通过网下询价方式确定股票发行价格和发行对象的，询价对象应当是经中国证监会注册的网下投资者。（ ）","options":["正确","错误"],"answer":"B","explain":"询价对象应当是经中国证券业协会注册的网下投资者。"},{"id":"basics-mt-77","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"股票退市制度存在的意义包括（ ）。","options":["引导理性投资","保护投资者权益","巩固上市公司地位","降低市场经营成本"],"answer":"ABD","explain":"退市制度意义包括引导理性投资、保护投资者权益、降低市场经营成本，不包括巩固上市公司地位。"},{"id":"basics-mt-78","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"科创板上市公司的股票终止上市后，符合上交所规定条件的，可以向上交所申请重新上市。（ ）","options":["正确","错误"],"answer":"A","explain":"科创板股票终止上市后符合条件可申请重新上市。"},{"id":"basics-mt-79","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"不属于证券交易原则的是（ ）。","options":["公开原则","公平原则","集中竞价交易规则","公正原则"],"answer":"C","explain":"集中竞价交易规则是具体交易方式，不是证券交易原则。"},{"id":"basics-mt-80","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"证券交易机制的主要目标包括（ ）。","options":["流动性","稳定性","有效性","效益性"],"answer":"ABC","explain":"证券交易机制目标包括流动性、稳定性、有效性。"},{"id":"basics-mt-81","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"证券账户信息中的关键信息包括（ ）。","options":["投资者姓名或名称","投资者地址","投资者有效身份证明文件及号码","投资者电话"],"answer":"AC","explain":"关键信息包括投资者姓名或名称、有效身份证明文件及号码。"},{"id":"basics-mt-82","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"根据我国现行有关制度的规定，过户费一部分属于（ ）的收入，一部分由证券公司留存。","options":["国家税收部门","中国证监会","中国结算公司","证券交易所"],"answer":"C","explain":"过户费一部分属于中国结算公司的收入。"},{"id":"basics-mt-83","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"中证指数有限公司发布的指数包括（ ）。","options":["中证行业指数","中证风格指数","中证主题指数","中证海外指数"],"answer":"ABCD","explain":"中证指数公司发布行业、风格、主题、海外等系列指数。"},{"id":"basics-mt-84","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"上海证券交易所的股价指数不包括（ ）。","options":["上证综指","上证50指数","沪深300","上证180指数"],"answer":"C","explain":"沪深300是中证指数公司发布的，不属于上证指数。"},{"id":"basics-mt-85","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"沪港通下的港股通每日额度为420亿元人民币。（ ）","options":["正确","错误"],"answer":"A","explain":"沪港通下港股通每日额度420亿元人民币。"},{"id":"basics-mt-86","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"沪伦通初期从存托凭证起步。（ ）","options":["正确","错误"],"answer":"A","explain":"沪伦通初期从存托凭证起步。"},{"id":"basics-mt-87","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"关于股票的清算价值，下列说法正确的是（ ）。","options":["股票清算时，股票所能获得的出售价值","公司清算时每一股份所代表的实际价值","公司破产清算时，其发行的股票的交易价值","股票的清算价值与账面价值相等"],"answer":"B","explain":"清算价值是公司清算时每一股份所代表的实际价值。"},{"id":"basics-mt-88","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"分析公司财务状况，重点在于研究公司的（ ）。","options":["盈利性","安全性","流动性","可持续发展性"],"answer":"ABC","explain":"分析财务状况重点在于盈利性、安全性、流动性。"},{"id":"basics-mt-89","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"影响股票投资价值的内部因素包括（ ）。","options":["公司净资产","股利政策","并购重组","货币政策"],"answer":"ABC","explain":"内部因素包括公司净资产、盈利水平、股利政策、股份分割、并购重组等。货币政策是外部因素。"},{"id":"basics-mt-90","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"在决定优先股的内在价值时零增长模型相当有用。（ ）","options":["正确","错误"],"answer":"A","explain":"优先股股息固定，零增长模型适用于优先股估值。"},{"id":"basics-mt-91","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"债券票面利率是债券年利息与债券面值的比率。（ ）","options":["正确","错误"],"answer":"A","explain":"票面利率是年利息与面值的比率。"},{"id":"basics-mt-92","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"下列关于债券与股票的说法中，错误的是（ ）。","options":["债券和股票都属于有价证券","债券和股票的目的不同","债券通常有规定的票面利率，而股票的股息红利不固定","债券和股票都是无期证券"],"answer":"D","explain":"债券是有期证券，股票是无期证券。"},{"id":"basics-mt-93","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"政府发行中期国债筹集的资金用于（ ）。","options":["临时周转","弥补赤字","投资","调节经济"],"answer":"BC","explain":"中期国债用于弥补赤字或投资。"},{"id":"basics-mt-94","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"地方政府一般债券是指省、自治区、直辖市政府（含经省级政府批准自办债券发行的计划单列市政府）为有一定收益的公益性项目发行的、约定一定期限内以公益性项目对应的政府性基金或专项收入还本付息的政府债券。（ ）","options":["正确","错误"],"answer":"B","explain":"该描述是地方政府专项债券，一般债券为没有收益的公益性项目。"},{"id":"basics-mt-95","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"兼有债权和股权的双重性质的公司债是（ ）。","options":["优先股","可转换公司债","收益公司债","信用公司债"],"answer":"B","explain":"可转换公司债券兼有债权和股权双重性质。"},{"id":"basics-mt-96","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"以下（ ）不是我国企业债券的种类。","options":["普通企业债券","中小企业集合债券","可续期企业债券","国际债券"],"answer":"D","explain":"国际债券不属于我国企业债券的品种。"},{"id":"basics-mt-97","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"下列关于国际债券的表述，不正确的是（ ）。","options":["不存在汇率风险","国际债券资金来源广，发行规模大","国际债券是一种跨国发行的债券，涉及两个或两个以上的国家","发行人发行国际债券筹集到的资金是一种可通用的自由外汇资金"],"answer":"A","explain":"国际债券存在汇率风险。"},{"id":"basics-mt-98","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"国际债券的发行人主要有（ ）。","options":["各国政府","银行或其他金融机构","自然人","一些国际组织"],"answer":"ABD","explain":"国际债券发行人包括各国政府、金融机构、国际组织，不包括自然人。"},{"id":"basics-mt-99","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"SPV是对受托人的简称。（ ）","options":["正确","错误"],"answer":"B","explain":"SPV是特殊目的机构的简称。"},{"id":"basics-mt-100","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"由银行业金融机构作为发起机构，将信贷资产信托给受托机构，由受托机构发行的，以资产支持证券的形式向投资机构发行受益证券为（ ）。","options":["中央银行票据","信贷资产证券化","商业银行次级债务","财务公司债券"],"answer":"B","explain":"信贷资产证券化的定义。"},{"id":"basics-mt-101","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"1988年以前，我国国债采用行政分配方式发行。（ ）","options":["正确","错误"],"answer":"A","explain":"1988年以前国债采用行政分配方式。"},{"id":"basics-mt-102","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"关于场内挂牌分销的程序，下列各项正确的有（ ）。","options":["承销商在分得包销的国债后，向证券交易所提供一个自营账户作为托管账户，将在证券交易所注册的记账式国债全部托管于该账户中","承销商按自己的意愿确定挂牌卖出国债的数量和价格，进行分销","投资者在买入债券时，可免交佣金，证券交易所也不向代理机构收取买卖国债的经手费用","发行结束后，承销商在规定的缴款日前如期将发行款一次性划入财政部在中国人民银行的指定账户内，托管账户中分销的国债余额转为承销商持有"],"answer":"ABCD","explain":"均为场内挂牌分销的程序。"},{"id":"basics-mt-103","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"下面关于地方政府一般债券说法正确的是（ ）。","options":["承销团成员应当是在中国境内依法成立的金融机构，具有债券承销业务资格","承销团成员应当在资本充足率、偿付能力或者净资本状况等指标方面达到监管标准","承销商可以书面委托其分支机构代理签署并履行债券承销协议","可以在一般债券承销商中择优选择主承销商"],"answer":"ABCD","explain":"均为地方政府一般债券承销的正确说法。"},{"id":"basics-mt-104","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"地方政府一般债券采用记账式浮动利率形式，地方政府一般债券实行自发自还。（ ）","options":["正确","错误"],"answer":"B","explain":"地方政府一般债券采用记账式固定利率付息形式。"},{"id":"basics-mt-105","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"金融租赁公司和汽车金融公司发行金融债券的条件包括：最近（ ）年连续盈利。","options":["1年","2年","3年","5年"],"answer":"C","explain":"金融租赁公司和汽车金融公司发行金融债券需最近3年连续盈利。"},{"id":"basics-mt-106","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"发行金融债券没有强制担保要求的机构是（ ）。","options":["财务公司","金融租赁公司","商业银行","上市公司"],"answer":"C","explain":"商业银行发行金融债券没有强制担保要求。"},{"id":"basics-mt-107","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"关于公司债券募集资金投向错误的是（ ）。","options":["公开发行公司债券筹集的资金，必须按照公司债券募集办法所列资金用途使用","改变资金用途，必须经债券持有人会议作出决议","公开发行公司债券筹集的资金，不得用于弥补亏损和非生产性支出","公开发行公司债券筹集的资金，可以用于弥补亏损和非生产性支出"],"answer":"D","explain":"公开发行公司债券筹集的资金不得用于弥补亏损和非生产性支出。"},{"id":"basics-mt-108","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"下列关于非公开发行公司债券的说法正确的是（ ）。","options":["非公开发行的公司债券应当向专业投资者发行，不得采用广告、公开劝诱和变相公开方式，每次发行对象不得超过150人","承销机构应当了解和评估投资者对非公开发行公司债券的风险识别和承担能力，确认参与非公开发行公司债券认购的投资者为专业投资者","非公开发行公司债券，可以申请在证券交易所、证券公司柜台转让","非公开发行公司债券转让后，持有同次发行债券的投资者合计不得超过200人"],"answer":"BCD","explain":"非公开发行每次发行对象不得超过200人，不是150人。"},{"id":"basics-mt-109","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"（ ）负责受理短期融资券的注册。","options":["中国银监会","中国银行间市场交易商协会","中国人民银行","商务部"],"answer":"B","explain":"短期融资券的注册由中国银行间市场交易商协会负责。"},{"id":"basics-mt-110","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"下列关于中小非金融企业集合票据的发行规模，正确的是（ ）。","options":["一次注册、一次或多次发行","任一企业集合票据待偿还余额不得超过该企业净资产的40%","任一企业集合票据募集资金额不得超过2亿元人民币","单只集合票据注册金额不超过10亿元人民币"],"answer":"BCD","explain":"中小非金融企业集合票据一次注册、一次发行，不是一次或多次发行。"},{"id":"basics-mt-111","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"按照相关规定，证券公司借入或发行次级债数额应符合：长期次级债计入净资本的数额不得超过净资本（不含长期次级债累计计入净资本的数额）的（ ）。","options":["50%","40%","30%","20%"],"answer":"A","explain":"长期次级债计入净资本的数额不得超过净资本的50%。"},{"id":"basics-mt-112","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"证券公司长期次级债计入净资本的数额不超过净资本的（ ）。","options":["0.2","0.3","0.4","0.5"],"answer":"D","explain":"不超过净资本的50%。"},{"id":"basics-mt-113","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"具备境外丰富的债券发行经验但信息披露不满一年的境外金融机构法人，无法申请在限额内分期发行债券。（ ）","options":["正确","错误"],"answer":"B","explain":"具备境外丰富经验或已在境内发行债券、持续信息披露一年以上的，可申请分期发行。"},{"id":"basics-mt-114","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"境外金融机构法人发行债券时，其审计机构需满足的条件不包括（ ）。","options":["在境外所在国家注册并处于正常执业状态","具有五年以上公开发行证券审计经验","在中国境内设有分支机构","良好的国际声誉和市场认可度"],"answer":"C","explain":"审计机构条件不包括在中国境内设有分支机构。"},{"id":"basics-mt-115","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"回购交易是在交易所进行的标准化的远期交易，即交易双方在集中性的市场以公开竞价方式所进行的期货合约的交易。（ ）","options":["正确","错误"],"answer":"B","explain":"该描述是期货交易，不是回购交易。"},{"id":"basics-mt-116","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"远期交易和期货交易的区别表现在（ ）。","options":["交易场所不同","交易风险不同","保证金制度不同","合约的规范性不同"],"answer":"ABCD","explain":"远期和期货在交易场所、风险、保证金、合约规范性等方面均有区别。"},{"id":"basics-mt-117","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"信用等级评审会议由信用评审委员会主任或其书面委托的其他委员主持。参会评审委员不得少于5人。（ ）","options":["正确","错误"],"answer":"A","explain":"参会评审委员不得少于5人。"},{"id":"basics-mt-118","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"由于债券筹资的数额巨大，所以对发行主体的资信评级是必不可少的一个环节，评级的主要内容包括（ ）。","options":["企业素质","经营能力","获利能力","偿债能力"],"answer":"ABCD","explain":"评级内容包括企业素质、经营能力、获利能力、偿债能力、履约情况、发展前景。"},{"id":"basics-mt-119","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"我国债券市场的主体是（ ）。","options":["银行间债券市场","交易所市场","企业债市场","商业银行柜台市场"],"answer":"A","explain":"银行间债券市场是我国债券市场的主体。"},{"id":"basics-mt-120","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"银行间债券市场成员根据其是否与中央债券簿记系统直接联网办理债券结算业务而分为直接结算成员和间接结算成员。其中，间接结算成员主要是（ ）。","options":["中小金融机构","存款类金融机构","非金融机构","大型金融机构"],"answer":"AC","explain":"间接结算成员主要是中小金融机构和非金融机构。"},{"id":"basics-mt-121","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"通常，债券条款中的（ ）等嵌入式期权，会极大影响债券未来现金流模式。","options":["发行人提前赎回权","转股权","转股修正权","债券持有人提前返售权"],"answer":"ABCD","explain":"上述嵌入式期权均会影响债券未来现金流模式。"},{"id":"basics-mt-122","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"下列各项，属于影响债券贴现率确定的因素是（ ）。","options":["预期通货膨胀率","风险溢价","税收待遇","票面利率"],"answer":"AB","explain":"贴现率=真实无风险收益率+预期通货膨胀率+风险溢价。税收待遇和票面利率影响现金流。"},{"id":"basics-mt-123","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"折价发行的债券，加快付息频率，债券价值会上升。（ ）","options":["正确","错误"],"answer":"B","explain":"折价发行的债券，加快付息频率，债券价值会下降。"},{"id":"basics-mt-124","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"下列关于债券的说法，正确的有（ ）。","options":["债券买卖报价分为净价报价和全价报价两种","债券结算分为净价结算和全价结算两种","债券应计利息为上一付息日（或起息日）至结算日之间累计的利息","全价 ≡ 净价 + 应计利息"],"answer":"ACD","explain":"债券结算为全价结算，不是净价结算。"},{"id":"basics-mt-125","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"我国交易所市场对附息债券的计息规定有（ ）。","options":["全年天数统一按实际全年天数计算","全年天数统一按365天计算","闰年2月29日也计息","利息累计天数按实际天数计算，算头不算尾"],"answer":"BD","explain":"我国交易所市场附息债券计息按365天计算，算头不算尾，闰年2月29日不计息。"},{"id":"basics-mt-126","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"2011年1月1日，中国人民银行发行1年期零息债券，每张面值为100元人民币，年贴现率为4%，则理论价格为（ ）元。","options":["94.89","95.13","96.15","98.29"],"answer":"C","explain":"P=100/(1+4%)=96.15元。"},{"id":"basics-mt-127","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"零息债券不计利息，折价发行，到期还本，通常将6个月期以内的债券称为零息债券。（ ）","options":["正确","错误"],"answer":"B","explain":"通常1年期以内的债券为零息债券。"},{"id":"basics-mt-128","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"当期收益率的缺点表现为（ ）。","options":["零息债券无法计算当期收益","不能用于比较期限和发行人均较为接近的债券","一般不单独用于评价不同期限附息债券的优劣","计算方法较为复杂"],"answer":"AC","explain":"当期收益率简便易算，缺点为零息债券无法计算，不能单独评价不同期限附息债券。"},{"id":"basics-mt-129","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"可赎回债券的约定赎回价格可以是（ ）。","options":["发行价格","债券面值","某一指定价格","与不同赎回时间对应的一组赎回价格"],"answer":"ABCD","explain":"赎回价格可以是发行价格、面值、指定价格或与时间对应的一组价格。"},{"id":"basics-mt-130","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"我国《上市公司证券发行管理办法》规定，可转换债券自发行结束之日起12个月后方可转换为公司股票。（ ）","options":["正确","错误"],"answer":"B","explain":"可转换债券自发行结束之日起6个月后方可转换为公司股票。"},{"id":"basics-mt-131","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"实践中，通常采用（ ）来确定不同债券的违约风险大小。","options":["收益率差","风险溢价","信用评级","信用利差"],"answer":"C","explain":"实践中采用信用评级来确定不同债券的违约风险大小。"},{"id":"basics-mt-132","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"在流动性偏好理论中，收益率曲线的形状是由延长偿还期所必需的流动性溢价和市场即期利率共同决定的。（ ）","options":["正确","错误"],"answer":"B","explain":"收益率曲线形状由对未来利率的预期和流动性溢价共同决定。"},{"id":"basics-mt-133","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"常见的另类投资基金包括（ ）。","options":["对冲基金","股权投资基金","创业投资基金","不动产投资基金"],"answer":"ABCD","explain":"另类投资基金包括对冲基金、股权投资基金、创业投资基金、不动产投资基金等。"},{"id":"basics-mt-134","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"以下属于证券投资基金特点的有（ ）。","options":["集合理财、专业管理","组合投资、分散风险","利益共享、风险共担","独立托管、保障安全"],"answer":"ABCD","explain":"均为证券投资基金的特点。"},{"id":"basics-mt-135","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"经核准的基金份额总额在基金合同期限内固定不变，基金份额可以在依法设立的证券交易场所交易，但基金份额持有人不得申请赎回的基金是指（ ）。","options":["公司型基金","封闭式基金","被动型基金","开放式基金"],"answer":"B","explain":"封闭式基金份额固定，可在交易所交易，但不得赎回。"},{"id":"basics-mt-136","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"按照基金的投资标的划分，可以将证券投资基金分为（ ）等。","options":["股票基金","债券基金","混合型基金","货币市场基金"],"answer":"ABCD","explain":"按投资标的分为股票基金、债券基金、混合基金、货币市场基金等。"},{"id":"basics-mt-137","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"1990-1997年，在我国证券投资基金发展的早期探索阶段，中国证监会是基金的审批和管理部门。（ ）","options":["正确","错误"],"answer":"B","explain":"早期探索阶段中国人民银行是基金的审批和管理部门。"},{"id":"basics-mt-138","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"我国《证券投资基金法》自（ ）起施行。","options":["2005年6月1日","2004年6月1日","2006年6月1日","2003年6月1日"],"answer":"B","explain":"《证券投资基金法》于2004年6月1日起施行。"},{"id":"basics-mt-139","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"在基金运作中，基金管理人居主导与核心位置。（ ）","options":["正确","错误"],"answer":"A","explain":"基金管理人在基金运作中居主导与核心位置。"},{"id":"basics-mt-140","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"基金的主要当事人有（ ）。","options":["基金投资者","基金销售服务机构","基金管理人","基金托管人"],"answer":"ACD","explain":"基金主要当事人包括基金投资者、基金管理人、基金托管人。"},{"id":"basics-mt-141","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"基金管理人是基金的募集者和管理者。（ ）","options":["正确","错误"],"answer":"A","explain":"基金管理人是基金的募集者和管理者。"},{"id":"basics-mt-142","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"既是基金的当事人，又是基金的主要服务机构的是（ ）。","options":["基金管理人","基金份额持有人","基金托管人","基金投资顾问机构"],"answer":"AC","explain":"基金管理人和基金托管人既是当事人又是主要服务机构。"},{"id":"basics-mt-143","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"基金募集申请需要提交的主要文件包括（ ）。","options":["募集基金的申请报告","基金合同草案","招募说明书草案","法律意见书"],"answer":"ABCD","explain":"基金募集申请需提交申请报告、基金合同草案、招募说明书草案、法律意见书等。"},{"id":"basics-mt-144","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"目前基金注册程序分为简易程序和普通程序。以下适用简易程序的有（ ）。","options":["常规股票基金","分级基金","ETF","货币基金"],"answer":"ACD","explain":"常规股票基金、ETF、货币基金适用简易程序。分级基金不适用。"},{"id":"basics-mt-145","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"一般情况下，已经正式受理的开放式基金认购申请，（ ）。","options":["可以撤销","不得撤销","可以撤销，但必须在3日内提出","在基金登记前可随时撤销"],"answer":"B","explain":"已经正式受理的认购申请不得撤销。"},{"id":"basics-mt-146","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"下列关于基金份额认购中的前端收费模式和后端收费模式的说法，错误的是（ ）。","options":["前端收费模式在认购基金份额时支付认购费用","后端收费模式在赎回基金份额时支付认购费用","前端收费模式的设计是为了鼓励投资者能够长期持有基金","后端收费的认购费率一般设计为随着基金份额持有时间的延长而递减"],"answer":"C","explain":"后端收费模式的设计是为了鼓励投资者长期持有基金。"},{"id":"basics-mt-147","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"开放式基金申购、赎回的原则为（ ）。","options":["金额赎回","金额申购","份额赎回","份额申购"],"answer":"BC","explain":"开放式基金申购、赎回原则为金额申购、份额赎回。"},{"id":"basics-mt-148","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"开放式基金非交易过户是指不采用申购、赎回等交易方式，将一定数量的基金份额按照一定规则从某一投资者基金账户转移到另一投资者基金账户的行为，主要包括（ ）。","options":["继承","捐赠","司法强制执行","经注册登记机构认可的其他情况"],"answer":"ABCD","explain":"非交易过户包括继承、捐赠、司法强制执行及其他认可情况。"},{"id":"basics-mt-149","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"某基金总资产为60亿元，总负债为20亿元，发行在外的基金份数为40亿份，则该基金的基金份额净值为人民币（ ）。","options":["1元","1亿元","2元","2亿元"],"answer":"A","explain":"基金资产净值=60-20=40亿元，份额净值=40/40=1元。"},{"id":"basics-mt-150","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"以下关于基金资产估值的表述，正确的是（ ）。","options":["基金资产估值的责任人是基金托管人","为保持估值方法的一致性，基金不得变更估值方法","若基金变更了估值方法，必须及时进行披露","基金管理人应当依照法律法规和基金合同约定，加强对侧袋机制启用、特定资产处置和信息披露等方面的复核和监督"],"answer":"C","explain":"基金资产估值责任人是基金管理人；估值方法可变更但需披露；侧袋机制复核和监督由托管人负责。"},{"id":"basics-mt-151","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"基金销售过程中发生的由基金投资者承担的费用（不参与基金的会计核算）主要包括：申购费（认购费）、赎回费及基金转换费等。（ ）","options":["正确","错误"],"answer":"A","explain":"该说法正确。"},{"id":"basics-mt-152","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"下列选项中，属于基金运作费的有（ ）。","options":["审计费","律师费","过户费","经手费"],"answer":"AB","explain":"审计费、律师费属于基金运作费；过户费、经手费属于交易费。"},{"id":"basics-mt-153","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"基金资产估值引起的资产价值变动作为公允价值变动损益计入资本公积。（ ）","options":["正确","错误"],"answer":"B","explain":"公允价值变动损益计入当期损益，不计入资本公积。"},{"id":"basics-mt-154","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"我国开放式基金利润分配方式包括（ ）。","options":["赠送基金份额","现金分红","红利再投资","固定红利"],"answer":"BC","explain":"开放式基金分红方式包括现金分红和红利再投资。"},{"id":"basics-mt-155","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"对证券投资基金从证券市场中取得的收入，减免企业所得税。（ ）","options":["正确","错误"],"answer":"B","explain":"暂不征收企业所得税，不是减免。"},{"id":"basics-mt-156","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"关于机构投资者买卖基金产生的税收，下列说法正确的有（ ）。","options":["机构投资者购入基金、信托、理财产品等各类资产管理产品持有至到期，属于金融商品转让，计征增值税","机构投资者买卖基金份额暂免征收印花税","机构投资者在境内买卖基金份额获得差价收入，应并入企业的应纳税所得额，征收企业所得税","机构投资者从基金分配中获得的收入，暂不征收所得税"],"answer":"BCD","explain":"持有至到期不属于金融商品转让。"},{"id":"basics-mt-157","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"（ ）是指基金经理在资产组合管理过程中所采用的某一特定方式或投资目标，是严格按照承诺对资产进行配置以获取预期收益的投资战略或计划。","options":["基金投资风格","基金投资理念","基金投资管理","基金投资流程"],"answer":"A","explain":"基金投资风格的定义。"},{"id":"basics-mt-158","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"关于基金的投资管理，下列说法正确的是（ ）。","options":["基金经理可以直接向交易员下达投资指令或者直接进行交易","交易部门依据基金经理的投资指令执行交易","研究部门提拟订投资组合具体方案","基金的交易实行集中交易管理制度"],"answer":"BD","explain":"基金经理不得直接下达交易指令，需经风险控制审核；研究部门提供研究报告，基金经理拟订方案。"},{"id":"basics-mt-159","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"关于基金投资风险管理，下列说法错误的是（ ）。","options":["基金可以通过在一定范围内分散投资来降低系统性风险","非系统性风险不能通过分散投资来降低","内部风险是指基金管理人在基金管理过程中产生的风险","内部风险多属于系统性风险"],"answer":"ABD","explain":"分散投资可降低非系统性风险，不能降低系统性风险；内部风险多属于非系统性风险。"},{"id":"basics-mt-160","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"系统的基金业绩评估需要从以下（ ）方面入手。","options":["计算绝对收益","计算风险调整后收益","计算相对收益","进行业绩归因"],"answer":"ABCD","explain":"基金业绩评估包括计算绝对收益、风险调整后收益、相对收益和业绩归因。"},{"id":"basics-mt-161","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"1965年，特雷诺在美国《哈佛商业评论》上发表《如何评价投资基金的管理》一文，首次提出一种评价基金业绩的综合指标，即特雷诺指数。该指数值越大，基金的绩效表现（ ）。","options":["越好","越差","与之无关","可能越好，也可能越差"],"answer":"A","explain":"特雷诺指数越大，基金绩效表现越好。"},{"id":"basics-mt-162","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"关于基金监管的手段，下列说法中，正确的有（ ）。","options":["必要的行政手段","法律手段","窗口指导","经济手段"],"answer":"ABD","explain":"基金监管手段包括法律、经济、必要的行政手段，窗口指导不属于基本监管手段。"},{"id":"basics-mt-163","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"根据我国《证券投资基金运作管理办法》及有关规定，基金管理人运用基金财产进行证券投资，不得有（ ）等情形。","options":["一只基金持有一家公司发行的证券，其市值超过基金资产净值的10%","同一基金管理人管理的全部基金持有一家公司发行的证券，其市值不超过该证券的10%","按照基金合同关于投资范围、投资策略和投资比例等约定投资","基金财产参与股票发行申购，单只基金所申报的金额未超过该基金的总资产"],"answer":"A","explain":"一只基金持有一家公司发行的证券市值不得超过基金资产净值的10%，超过属于禁止情形。"},{"id":"basics-mt-164","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"基金信息的披露义务人包括（ ）。","options":["基金管理人","基金托管人","召集基金份额持有人大会的基金份额持有人","符合要求的自然人"],"answer":"ABCD","explain":"信息披露义务人包括基金管理人、基金托管人、召集持有人大会的份额持有人以及符合要求的自然人。"},{"id":"basics-mt-165","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"基金运作信息披露文件包括（ ）。","options":["基金份额上市交易公告书","基金份额发售公告","基金净值公告","基金定期报告"],"answer":"ACD","explain":"基金运作信息披露文件包括基金份额上市交易公告书、基金净值公告、基金定期报告。基金份额发售公告属募集信息披露。"},{"id":"basics-mt-166","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"下列关于私募基金的说法，正确的是（ ）。","options":["风险较高","可以进行公开的发售和宣传","只能采取非公开方式发行","向特定的投资者发售的基金"],"answer":"ACD","explain":"私募基金不能进行公开发售和宣传推广。"},{"id":"basics-mt-167","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"在我国，私募基金合格投资者累计不得超过（ ）人。","options":["200","150","100","50"],"answer":"A","explain":"私募基金合格投资者累计不得超过200人。"},{"id":"basics-mt-168","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"非公开募集基金募集完毕，基金管理人应当向（ ）备案。","options":["中国人民银行","银监会","证监会","基金行业协会"],"answer":"D","explain":"非公开募集基金募集完毕应当向基金行业协会备案。"},{"id":"basics-mt-169","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"基金合同应当约定给投资者设置不少于（ ）的投资冷静期。募集机构在投资冷静期内不得主动联系投资者。","options":["12个小时","18个小时","24个小时","36个小时"],"answer":"C","explain":"投资冷静期不少于24小时。"},{"id":"basics-mt-170","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"下列关于外商开展私募基金业务的说法，正确的是（ ）。","options":["经中国证监会同意，外商独资和合资私募证券基金管理机构在中国境内开展私募证券基金管理业务，应在中国证券投资基金业协会登记为私募证券基金管理人","外商独资和合资私募证券基金管理机构开展私募证券投资基金业务，在境内从事证券及期货交易，应当独立进行投资决策，可以通过境外机构或者境外系统下达交易指令","外商独资和合资私募证券基金管理机构提供的登记申请材料完备的，中国证券投资基金业协会将自收齐材料之日起20个工作日内，以通过协会官方网站公示私募基金管理人基本情况的方式，为其办结登记手续","外商独资和合资私募证券基金管理机构登记后，应当依法及时展业"],"answer":"ACD","explain":"不得通过境外机构或系统下达交易指令。"},{"id":"basics-mt-171","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"以下关于基础设施公募REITs说法错误的是（ ）。","options":["基础设施公募REITs的绝大多数收益要分配给投资者","基础设施公募REITs具有流动性较低、收益相对稳定、安全性较强","基础设施公募REITs从短期看，有利于广泛筹集项目资本金，降低债务风险，是稳投资、补短板的有效政策工具","基础设施公募REITs能提升直接融资比重，增强资本市场服务实体经济质效"],"answer":"B","explain":"基础设施公募REITs具有流动性较高（不是较低）的特点。"},{"id":"basics-mt-172","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"基础设施公募REITs要求包括（ ）。","options":["90%以上基金资产投资于基础设施资产支持证券，并持有其全部份额","基金通过资产支持证券和项目公司等特殊目的载体取得基础设施项目完全所有权或经营权权利","基金管理人主动运营管理基础设施项目，以获取基础设施项目租金、收费等稳定现金流为主要目的","采取封闭式运作，收益分配比例不低于合并后基金年度可供分配金额的80%"],"answer":"BC","explain":"基础设施公募REITs要求80%以上基金资产投资于资产支持证券；收益分配比例不低于90%。"},{"id":"basics-mt-173","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"基金管理人提交的申请文件应确保内容真实、准确、完整，简明清晰、通俗易懂。交易所在接收申请文件后的5个工作日内对申请文件是否齐备和符合形式要求进行形式审核。（ ）","options":["正确","错误"],"answer":"A","explain":"该描述正确。"},{"id":"basics-mt-174","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"首次书面反馈意见在受理之日起的30个工作日内出具无异议函或者作出终止审核的决定，基金管理人在收到书面反馈意见后30个工作日内予以书面回复。（ ）","options":["正确","错误"],"answer":"A","explain":"该描述正确。"},{"id":"basics-mt-175","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"基础设施基金采用竞价交易的，单笔申报的最大数量应当不超过（ ）亿份。","options":["1","2","3","4"],"answer":"A","explain":"竞价交易单笔申报最大数量不超过1亿份。"},{"id":"basics-mt-176","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"基础设施基金份额的发售分为（ ）等。","options":["战略配售","网下询价并定价","网上配售","公众投资者认购"],"answer":"ABD","explain":"发售分为战略配售、网下询价并定价、网下配售、公众投资者认购。网上配售不属于基础设施基金发售环节。"},{"id":"basics-mt-177","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"以下关于公募REITs的运营管理说法错误的是（ ）。","options":["基金管理人可以通过设立专门子公司或者委托运营管理机构负责基础设施项目运营管理","需要在基金合同中明确设施项目无法维持正常、持续运营等基金合同终止情形","涉及基础设施项目处置的，应当遵循基金管理人利益优先的原则","涉及基础设施项目处置的，资产支持证券管理人应当配合基金管理人按照有关规定和约定进行资产处置"],"answer":"C","explain":"涉及基础设施项目处置的，应当遵循份额持有人利益优先的原则。"},{"id":"basics-mt-178","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"公募REITs基金的风险不包括（ ）。","options":["基金价格波动风险","基础设施项目运营风险","流动性风险","市场风险"],"answer":"D","explain":"公募REITs风险包括价格波动、项目运营、流动性、终止上市、税收等风险，不包括市场风险。"},{"id":"basics-mt-179","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"基础设施基金采取封闭式运作，不开通申购赎回，只能在二级市场交易，存在流动性不足的风险。（ ）","options":["正确","错误"],"answer":"A","explain":"该描述正确。"},{"id":"basics-mt-180","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"金融衍生工具的基础变量包括（ ）。","options":["价格指数","资产价格","气温","选举"],"answer":"ABCD","explain":"基础变量包括资产价格、价格指数、利率、汇率、气温、选举等。"},{"id":"basics-mt-181","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"金融衍生工具伴随的风险主要包括（ ）。","options":["汇率风险、利率风险","信用风险、法律风险","市场风险、操作风险","流动性风险、结算风险"],"answer":"BCD","explain":"金融衍生工具风险包括信用、市场、流动性、结算、操作、法律风险。汇率和利率风险属于市场风险范畴。"},{"id":"basics-mt-182","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"金融衍生工具从其自身交易的方法和特点可以分为（ ）。","options":["金融远期合约","金融期货","股权类产品的衍生工具","金融互换"],"answer":"ABD","explain":"按交易方法和特点分为金融远期、金融期货、金融期权、金融互换和结构化金融衍生工具。"},{"id":"basics-mt-183","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"下列属于股权类产品的衍生工具的是（ ）。","options":["股票期权合约","债券远期合约","信用互换合约","大宗商品的期货合约"],"answer":"A","explain":"股票期权合约属于股权类衍生工具。"},{"id":"basics-mt-184","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"下列关于金融衍生工具的发展动因，说法错误的是（ ）。","options":["金融衍生工具产生的最基本原因是投机","20世纪80年代以来的金融自由化进一步推动了金融衍生工具的发展","金融机构的利润驱动","新技术革命为金融衍生工具的产生与发展提供了物质基础与手段"],"answer":"A","explain":"金融衍生工具产生的最基本原因是避险。"},{"id":"basics-mt-185","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"（ ）年5月，中国证监会颁布的《上市公司证券发行管理办法》中首次提出上市公司可以公开发行认股权和债券分离交易的可转换公司债券。","options":["2006","2007","2008","2009"],"answer":"A","explain":"2006年5月首次提出可分离债券。"},{"id":"basics-mt-186","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"管理风险是衍生工具市场的初始功能，是衍生工具市场发展的一个立足点。（ ）","options":["正确","错误"],"answer":"A","explain":"管理风险是衍生工具市场的初始功能。"},{"id":"basics-mt-187","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"下列属于金融衍生工具市场在宏观经济中的作用的是（ ）。","options":["促进本国经济的国际化","有助于市场经济体系的完善","为政府制定宏观经济政策提供参考依据","提供分散、转移价格风险的工具，有助于稳定国民经济"],"answer":"ABCD","explain":"均为金融衍生工具市场在宏观经济中的作用。"},{"id":"basics-mt-188","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"最早的金属期货交易诞生于英国。（ ）","options":["正确","错误"],"answer":"A","explain":"最早的金属期货交易诞生于英国伦敦金属交易所。"},{"id":"basics-mt-189","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"目前，我国的商品期货交易所包括（ ）。","options":["深圳期货交易所","上海期货交易所","大连商品交易所","郑州商品交易所"],"answer":"BCD","explain":"我国商品期货交易所包括上海期货交易所、大连商品交易所、郑州商品交易所、广州期货交易所。"},{"id":"basics-mt-190","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"以（ ）为主的债券期货是各主要交易所最重要的利率期货品种。","options":["金融债券期货","市政债券指数期货","国债期货","市政债券期货"],"answer":"C","explain":"国债期货是各主要交易所最重要的利率期货品种。"},{"id":"basics-mt-191","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"中国金融期货交易所实行结算会员制度，其中结算会员根据业务范围分为（ ）。","options":["基础结算会员","交易结算会员","全面结算会员","特别结算会员"],"answer":"BCD","explain":"结算会员分为交易结算会员、全面结算会员、特别结算会员。"},{"id":"basics-mt-192","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"通常，在金融期权交易中，（ ）需要开立保证金账户，并按照规定缴纳保证金。","options":["期权买卖双方均","期权买卖双方均不","期权购入者","期权出售者"],"answer":"D","explain":"只有期权出售者才需开立保证金账户。"},{"id":"basics-mt-193","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"某投资者买入一份欧式期权，则他可以在到期日行使自己的权利。（ ）","options":["正确","错误"],"answer":"A","explain":"欧式期权只能在到期日执行。"},{"id":"basics-mt-194","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"与场内期权相比，场外期权的特点包括（ ）。","options":["合约非标准化","交易品种多样、形式灵活","交易对手机构化","流动性风险和信用风险大"],"answer":"ABCD","explain":"均为场外期权的特点。"},{"id":"basics-mt-195","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"债券远期交易数额最小为债券面额（ ），交易单位为债券面额（ ）。","options":["10万元；1万元","10万元；1000万元","1万元；1000万元","100万元；1万元"],"answer":"A","explain":"债券远期交易最小为10万元，交易单位为1万元。"},{"id":"basics-mt-196","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"交易双方约定在未来某一日交换协议期间内在一定名义本金基础上分别以合同利率和参考利率计算的利息的金融合约是（ ）。","options":["远期汇率协议","债权类资产的远期合约","股权类资产的远期合约","远期利率协议"],"answer":"D","explain":"远期利率协议的定义。"},{"id":"basics-mt-197","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"关于金融互换交易，下列说法正确的是（ ）。","options":["互换是指两个或两个以上的当事人按共同商定的条件，在约定的时间内定期交换现金的金融交易","目前，按名义金额计算的互换交易已经成为最大的衍生品交易品种","互换交易的主要用途是改变交易者资产或负债的风险结构，从而规避相应风险","我国已经暂停了融资类股票收益互换业务"],"answer":"ABCD","explain":"均为关于金融互换的正确说法。"},{"id":"basics-mt-198","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"信用违约互换的危险来自（ ）。","options":["具有较高杠杆性","信用保护的买方并不需要真正持有作为参考的信用工具","场外市场缺乏充分的信息披露和监管，交易者并不清楚自己的交易对手卷入了多少此类交易","期货价格与未来的现货价格之间可能存在一定的偏离"],"answer":"ABC","explain":"CDS危险来自高杠杆、不必持有参考工具、场外信息披露不足。"},{"id":"basics-mt-199","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"参与美国存托凭证发行与交易的中介机构包括（ ）。","options":["美国证券交易委员会","存券银行","托管银行","中央存托公司"],"answer":"BCD","explain":"参与ADR的中介机构包括存券银行、托管银行、中央存托公司。"},{"id":"basics-mt-200","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"九号有限公司成为科创板首家发行CDR的公司。（ ）","options":["正确","错误"],"answer":"A","explain":"九号有限公司是科创板首家发行CDR的公司。"},{"id":"basics-mt-201","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"目前最流行的结构化金融衍生产品主要是由（ ）开发的各类结构化理财产品以及在交易所市场上市交易的各类结构化票据，通常与某种金融价格相联系，其投资收益随该价格的变化而变化。","options":["保险公司","中央银行","商业银行","证券交易所"],"answer":"C","explain":"结构化产品主要由商业银行开发。"},{"id":"basics-mt-202","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"下列属于按嵌入式衍生产品的属性不同划分的结构化金融衍生产品的是（ ）。","options":["基于互换的结构化产品","私募结构化产品","保证最低收益型产品","利率联结型产品"],"answer":"A","explain":"按嵌入式衍生产品属性分为基于互换、基于期权的结构化产品等。"},{"id":"basics-mt-203","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"下列能体现风险的本质和内在特性的概念有（ ）。","options":["不确定性","损失","波动性","期望偏离"],"answer":"ABCD","explain":"风险的本质体现为不确定性、损失、波动性、期望偏离。"},{"id":"basics-mt-204","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"下列关于风险的说法中，错误的是（ ）。","options":["风险是结果的不确定性","风险是损失发生的可能性","风险是结果对期望的偏离，是（收益的）波动性","风险是一定发生的损失"],"answer":"D","explain":"风险是损失发生的可能性，不是一定发生的损失。"},{"id":"basics-mt-205","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"风险管理不等于损失管理，其本质特征是事前管理。（ ）","options":["正确","错误"],"answer":"A","explain":"风险管理的本质特征是事前管理。"},{"id":"basics-mt-206","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"下列关于风险和收益的说法，错误的是（ ）。","options":["任何金融产品是风险和收益的组合","高收益往往代表着高风险，低风险往往代表着低收益","投资是以风险换收益","承担较高风险的投资不应该获得风险溢价"],"answer":"D","explain":"承担较高风险应该获得风险溢价。"},{"id":"basics-mt-207","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"根据马科维茨组合投资理论，投资组合的多样化可以分散非系统性风险，当投资组合中的资产种类数目趋近于无穷大，组合的非系统性风险将趋于零。因此，有效的投资组合就是选择彼此之间相关系数（ ）的资产组合，在不影响收益率的情况下尽可能地降低风险。","options":["大于1","小于1","等于1","等于0"],"answer":"B","explain":"有效组合选择相关系数小于1的资产。"},{"id":"basics-mt-208","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"风险补偿主要是指事后的价格补偿。（ ）","options":["正确","错误"],"answer":"B","explain":"风险补偿主要是指事前（损失发生以前）的价格补偿。"},{"id":"basics-mt-209","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"风险识别包括（ ）。","options":["感知风险和分析风险","预测风险和消除风险","感知风险和消除风险","预测风险和分析风险"],"answer":"A","explain":"风险识别包括感知风险和分析风险两个环节。"},{"id":"basics-mt-210","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"凡在限额以内发生的损失，都可以通过（ ）来抵御。","options":["自有资金","内部资金","外部资金","内部资金或者外部资金"],"answer":"A","explain":"限额以内的损失可以通过自有资本金抵御。"},{"id":"basics-mt-211","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"证券公司应当保障首席风险官的独立性。（ ）","options":["正确","错误"],"answer":"A","explain":"证券公司应当保障首席风险官的独立性。"},{"id":"basics-mt-212","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"风险容忍度是风险偏好的具体体现，是对风险偏好的进一步量化和细化。（ ）","options":["正确","错误"],"answer":"A","explain":"风险容忍度是风险偏好的具体体现和量化。"},{"id":"basics-mt-213","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"流动性风险是因市场价格变量波动而给经济主体带来损益的风险。（ ）","options":["正确","错误"],"answer":"B","explain":"流动性风险不是市场风险，市场风险是因市场价格变量波动带来的风险。"},{"id":"basics-mt-214","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"根据导致市场风险因素的不同，市场风险一般划分为（ ）。","options":["利率风险","外汇风险","股票价格风险","商品风险"],"answer":"ABCD","explain":"市场风险包括利率风险、外汇风险、股票价格风险、商品风险。"},{"id":"basics-mt-215","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"债券的久期是指投资者收到所有现金流所要等待的平均时间。（ ）","options":["正确","错误"],"answer":"A","explain":"久期的定义。"},{"id":"basics-mt-216","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"VaR是描述市场在正常情况下可能出现的（ ）损失。","options":["最小","最大","平均","固定"],"answer":"B","explain":"VaR是可能发生的最大损失。"},{"id":"basics-mt-217","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"常用的市场风险限额包括（ ）。","options":["交易限额","风险限额","止损限额","敏感度限额"],"answer":"ABCD","explain":"市场风险限额包括交易限额、风险限额、止损限额、敏感度限额等。"},{"id":"basics-mt-218","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"下列属于信用风险构成要素的是（ ）。","options":["违约概率","违约损失率","违约风险暴露","预期损失和非预期损失"],"answer":"ABC","explain":"信用风险构成要素包括违约概率、违约损失率、违约风险暴露。"},{"id":"basics-mt-219","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"按照证券类机构业务类型分类，信用风险主要来自但不限于以下（ ）业务。","options":["股票质押式回购交易、约定回购式证券交易、融资融券等融资类业务","互换、场外期权、远期、信用衍生品等场外衍生品业务","债券投资交易","非标准化债权资产投资"],"answer":"ABCD","explain":"信用风险主要来自融资类业务、场外衍生品业务、债券投资交易、非标准化债权资产投资等。"},{"id":"basics-mt-220","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"信用打分模型的关键在于关键变量的选择和各自权重的确定。（ ）","options":["正确","错误"],"answer":"A","explain":"信用打分模型的关键在于变量选择和权重确定。"},{"id":"basics-mt-221","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"内部评级所反映的被评级对象的风险特征主要是（ ）。","options":["借款者的违约概率","交易工具的违约损失率","违约风险暴露","预期损失和非预期损失"],"answer":"AB","explain":"内部评级反映的风险特征主要是违约概率和违约损失率。"},{"id":"basics-mt-222","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"（ ）是指向客户出借资金供其买入证券或者出借证券供其卖出，并收取担保物的经营活动。","options":["融资融券业务","股票质押业务","债券业务","非标准化债权投资业务"],"answer":"A","explain":"融资融券业务的定义。"},{"id":"basics-mt-223","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"2009年，巴塞尔委员会总结了引入中央交易对手的优点（ ）。","options":["减少了交易对手暴露和操作风险","提高了交易对手信用风险管理水平和担保品管理的有效性","提高了衍生品市场的透明度","一定能阻止发生金融危机"],"answer":"ABC","explain":"引入中央交易对手能减少风险暴露、提高管理水平、提高透明度，但不能保证阻止金融危机。"},{"id":"basics-mt-224","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"信用衍生产品交易具有以下（ ）特征。","options":["融资的提供和风险的承担被分离，即保护提供方提供融资，但不承担信用风险，而保护购买者承担信用风险，却不提供融资","信用风险可以在业务中从其他风险（如利率风险和汇率风险等）中分离出来被单独交易和转让","信用保护的出售方在承担信用风险时并不要求资金投入，除非合同中指定的信用事件发生","基础信用交易仍然保留在金融机构的银行业务账户上，而且继续由作为放款银行的信用购买方来管理"],"answer":"BCD","explain":"融资的提供和风险的承担被分离，即保护购买者提供融资但不承担信用风险，保护提供方承担信用风险但不提供融资。"},{"id":"basics-mt-225","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"总收益互换（TRS）将市场风险和信用风险从卖方转移到了买方。（ ）","options":["正确","错误"],"answer":"A","explain":"TRS将市场风险和信用风险从卖方转移到了买方。"},{"id":"basics-mt-226","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"市场流动性是从单个机构的流动性需求出发，将流动性理解为企业尤其是金融机构保证经营以及正常支付的能力。（ ）","options":["正确","错误"],"answer":"B","explain":"那是机构流动性的定义。市场流动性是指市场使投资者迅速、低成本地交易金融资产的能力。"},{"id":"basics-mt-227","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"在不影响其日常经营和财务状况的条件下，金融机构难以有效满足其预期和非预期的、当前和未来的现金流和担保需求的风险是指（ ）。","options":["融资流动性风险","资产流动性风险","市场流动性风险","流动性风险"],"answer":"A","explain":"融资流动性风险的定义。"},{"id":"basics-mt-228","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"买卖价差法常用的价差指标包括（ ）。","options":["买卖价差","有效价差","实现的价差","合理价差"],"answer":"ABC","explain":"常用价差指标包括买卖价差、有效价差、实现的价差。"},{"id":"basics-mt-229","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"从机构层面衡量流动性风险的资产负债结构指标不包括（ ）。","options":["流动比率","现金流向比率","速动比率","净稳定资金率"],"answer":"B","explain":"现金流向比率不属于机构层面资产负债结构指标。"},{"id":"basics-mt-230","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"证券公司的融资管理应符合以下要求（ ）。","options":["分析正常和压力情景下未来不同时间段的融资需求和来源","加强负债品种期限、交易对手、融资抵（质）押品和融资市场等的集中管理，适当设置集中度限额","加强融资渠道管理，积极维护与主要融资交易对手的关系，保持在市场上适当活跃程度，并定期评估市场融资和资产变现能力","密切监测主要金融市场的交易量和价格等变动情况，评估市场流动性对公司融资能力的影响"],"answer":"ABCD","explain":"均为融资管理要求。"},{"id":"basics-mt-231","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"金融机构应当制订应急计划，确保能够及时应对和处理紧急或危机情况。应急计划的目标是（ ）。","options":["帮助公司应对极端的风险事件","降低风险的损失频率或影响程度","深入理解各种风险的成因","储备自有资本金来抵御未知风险"],"answer":"A","explain":"应急计划目标是帮助公司应对极端流动性事件。"},{"id":"basics-mt-232","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"操作风险损失数据收集主要基于（ ）等几个方面。","options":["内部损失数据","外部损失数据","情景分析","业务环境和内部控制因素"],"answer":"ABCD","explain":"操作风险损失数据收集基于内部损失数据、外部损失数据、情景分析、业务环境和内部控制因素。"},{"id":"basics-mt-233","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"操作风险管理的方法有（ ）。","options":["内部控制","保险","业务外包","IT技术应用","数据治理和管理","业务持续计划"],"answer":"ABCDEF","explain":"操作风险管理方法包括内部控制、保险、业务外包、IT技术应用、数据治理和管理、业务持续计划。"},{"id":"basics-mt-234","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"审慎管理原则要求证券公司应主动识别和防范声誉风险，加强对声誉风险的发生原因、影响程度、发展变化的分析和预测，及时作出应对。（ ）","options":["正确","错误"],"answer":"B","explain":"该描述为预防第一原则，不是审慎管理原则。"},{"id":"basics-mt-235","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"新闻发言人可由一人或多人担任，其中至少一名为公司高级管理人员。（ ）","options":["正确","错误"],"answer":"A","explain":"新闻发言人至少一名为公司高级管理人员。"},{"id":"basics-mt-236","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"战略风险取决于以下（ ）方面。","options":["战略目标的兼容性","为实现这些目标而制定的经营战略","为实现目标所部署的资源","整个战略实施过程的质量"],"answer":"ABCD","explain":"战略风险取决于战略目标兼容性、经营战略、资源部署、实施过程质量。"},{"id":"basics-mt-237","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 章节母题","q":"系统性风险是与单体金融机构风险相对应的，通常具有（ ）等特征。","options":["内生性","关联性","复杂性","突发性"],"answer":"ABCD","explain":"系统性风险具有内生性、关联性、复杂性、突发性、传染性等特征。"},{"id":"basics-mt-238","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 章节母题","q":"下面关于证券公司的风险管理的三个发展阶段的说法错误的是（ ）。","options":["在第一阶段，证券公司一般都没有设置专门的风险管理部门，面临的风险主要是操作风险，风险管理工作以散落在业务条线的内部控制为主","在第二阶段，证券公司已经基本上成立了独立的风险管理部，按照风险类型有针对性地开展风险管理工作","在第三阶段，压力测试作为风险评估的补充已经得到广泛应用","在第三阶段，全面风险管理规范的出台标志着证券公司风险管理进入到全面风险管理体系建设阶段"],"answer":"C","explain":"压力测试作为风险评估的补充是在第二阶段得到广泛应用。"},{"id":"basics-mt-239","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 章节母题","q":"《证券公司全面风险管理规范》首次提出要求证券公司必须设立首席风险官，总部要对子公司以及比照子公司管理的孙公司进行垂直管理。（ ）","options":["正确","错误"],"answer":"A","explain":"该规范首次提出设立首席风险官及垂直管理要求。"}]},{"id":"basics-m1","subject":"basics","name":"金融 · 提分密训卷一","stats":{"单选":40,"多选":40,"判断":30,"案例":10},"questions":[{"id":"basics-m1-0","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"做市商交易的基本特征是（　）","options":["成交时点是不连续的","证券交易的买价和卖价都由做市商给出","以买卖双向价格为基准进行撮合","投资者买卖证券的对手是其他投资者"],"answer":"B","explain":"做市商交易中买卖价由做市商给出，投资者之间不直接成交。"},{"id":"basics-m1-1","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"资金盈余单位通过直接与资金需求单位协议，或在金融市场上购买资金需求单位所发行的股票、债券等有价证券，将货币资金提供给需求单位使用。这是融资方式中的（　）。","options":["银行信用融资","股票市场融资","直接融资","间接融资"],"answer":"C","explain":"直接融资是资金盈余单位直接与资金需求单位协议或购买其证券。"},{"id":"basics-m1-2","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列关于金融市场的说法，正确的是（　）。","options":["金融市场只是交易金融资产的市场","金融市场并不是创造金融资产的市场","金融市场既有有形的固定交易场所，同时还有通过各种线上手段形成的庞大的无形市场","金融市场既是要素市场，也是产品市场"],"answer":"C","explain":"金融市场既是有形也是无形市场，现代金融市场往往是无形的。"},{"id":"basics-m1-3","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"（　）是指在模拟历史上重大风险事件或重大压力情景，（　）是指基于经验判断或数量模型模拟未来可预见的极端不利情况。","options":["敏感性分析；历史情景法","历史情景法；假设情景法","敏感性分析；假设情景法","假设情景法；历史情景法"],"answer":"B","explain":"历史情景法模拟历史重大事件，假设情景法模拟未来极端不利情况。"},{"id":"basics-m1-4","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"股东会作出决议必须经出席会议的股东所持表决权的过（　）通过。","options":["半数","三分之一","三分之二","全数"],"answer":"A","explain":"股东会决议必须经出席会议的股东所持表决权过半数通过。"},{"id":"basics-m1-5","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"股票、债券等属于（　）。","options":["商品证券","货币证券","资本证券","商业证券"],"answer":"C","explain":"股票、债券属于资本证券，代表对金融资产的投资权益。"},{"id":"basics-m1-6","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"美国《1980年银行法》废除了Q条例，规定从1980年3月起分6年逐步取消对定期存款和储蓄存款的（　）。","options":["最高利率限制","最低利率限制","最低和最高利率限制","数量限制"],"answer":"A","explain":"Q条例取消的是对定期存款和储蓄存款的最高利率限制。"},{"id":"basics-m1-7","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"基础设施基金采用竞价交易的，单笔申报的最大数量应当不超过（　）亿份。","options":["1","2","3","4"],"answer":"A","explain":"基础设施基金竞价交易单笔申报最大数量不超过1亿份。"},{"id":"basics-m1-8","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列有关股份回购，说法正确的是（　）。","options":["上市公司利用自有资金，买回发行在外的股票","上市公司通过发行债券募集资金，买回发行在外的股票","上市公司利用闲散资金，买回发行在外的股票","上市公司利用流动资金，买回发行在外的股票"],"answer":"A","explain":"股份回购是公司利用自有资金买回发行在外的股份。"},{"id":"basics-m1-9","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"根据马科维茨组合投资理论，投资组合的多样化可以分散非系统性风险，当投资组合中的资产种类数目趋近于无穷大，组合的非系统性风险将趋于零。因此，有效的投资组合就是选择彼此之间相关系数（　）的资产组合，在不影响收益率的情况下尽可能地降低风险。","options":["大于1","小于1","等于1","等于0"],"answer":"B","explain":"有效组合选择相关系数小于1的资产，以降低风险。"},{"id":"basics-m1-10","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"两个或两个以上的当事人按共同商定的条件，在约定的时间内定期交换现金流的金融交易是（　）。","options":["金融期货","金融互换","金融远期合约","金融期权"],"answer":"B","explain":"金融互换是双方定期交换现金流的金融交易。"},{"id":"basics-m1-11","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"目前最流行的结构化金融衍生产品主要是由（　）开发的各类结构化理财产品以及在交易所市场上市交易的各类结构化票据，通常与某种金融价格相联系，其投资收益随该价格的变化而变化。","options":["保险公司","中央银行","商业银行","证券交易所"],"answer":"C","explain":"结构化产品主要由商业银行开发。"},{"id":"basics-m1-12","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"不属于债券买卖交易报价方式的是（　）。","options":["双边报价","大额报价","公开报价","对话报价"],"answer":"B","explain":"债券报价方式有公开报价、对话报价、双边报价和小额报价，没有大额报价。"},{"id":"basics-m1-13","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"以（　）为主的债券期货是各主要交易所最重要的利率期货品种。","options":["金融债券期货","市政债券指数期货","国债期货","市政债券期货"],"answer":"C","explain":"国债期货是各交易所最重要的利率期货品种。"},{"id":"basics-m1-14","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"（　）是指交易所将当日以涨跌停板价格申报的未成交平仓报单，以当日涨跌停板价格与该合约净持仓盈利客户按照持仓比例自动撮合成交。","options":["强行平仓制度","强制减仓制度","限仓制度","集中交易制度"],"answer":"B","explain":"强制减仓制度是按涨跌停板价格与盈利客户持仓比例撮合。"},{"id":"basics-m1-15","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"新中国成立70多年，我国建成了（　）金融市场体系。","options":["与中国特色社会主义相适应的现代金融市场体系","以服务实体经济为目标、便民利民的金融市场体系","有效维护金融稳定的金融市场体系","面向全球、平等竞争的金融市场体系"],"answer":"A","explain":"我国建成了与中国特色社会主义相适应的现代金融市场体系。"},{"id":"basics-m1-16","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列做法中，不符合相关规定的是（　）。","options":["赵某是政府部门工作人员，申请开设了个人证券账户","张某在开设证券账户时，采用的是其身份证上的姓名","王某使用其妻子的名义开设了证券账户","中国证券登记结算有限责任公司为李某开立一码通账户和相应子账户"],"answer":"C","explain":"开立证券账户应使用本人名义，不得冒用他人名义。"},{"id":"basics-m1-17","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"（　）负责受理短期融资券的注册。","options":["中国银监会","中国银行间市场交易商协会","中国人民银行","商务部"],"answer":"B","explain":"短期融资券的注册由中国银行间市场交易商协会负责。"},{"id":"basics-m1-18","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券金融公司开展转融通业务，应当向证券公司收取一定比例的保证金。保证金可以证券充抵，但货币资金占应收取保证金的比例不得低于（　）。","options":["30%","20%","15%","10%"],"answer":"C","explain":"货币资金占保证金比例不得低于15%。"},{"id":"basics-m1-19","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司向客户出借资金供其买入上市证券或者出借上市证券供其卖出，并收取担保物的经营活动属于（　）。","options":["证券承销与保荐业务","证券经纪业务","融资融券业务","证券自营业务"],"answer":"C","explain":"融资融券业务是证券公司向客户出借资金或证券。"},{"id":"basics-m1-20","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"目前基金注册程序分为简易程序和普通程序，按简易程序注册，注册审查时间原则上不超过（　）；按照普通程序注册，注册审查时间不超过（　）。","options":["15个工作日；3个月","20个工作日；4个月","15个工作日；5个月","20个工作日；6个月"],"answer":"D","explain":"简易程序不超过20个工作日，普通程序不超过6个月。"},{"id":"basics-m1-21","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"实践中，通常采用（　）来确定不同债券的违约风险大小。","options":["收益率差","风险溢价","信用评级","信用利差"],"answer":"C","explain":"信用评级用于确定债券违约风险大小。"},{"id":"basics-m1-22","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"在美国银行业的监管机构中，（　）作为监管机构的协调机构，负责制定统一的监管准则和报告格式。","options":["货币监理署","联邦储备体系","储蓄机构监管署","联邦金融机构检查委员会"],"answer":"D","explain":"联邦金融机构检查委员会是协调机构，制定统一监管准则。"},{"id":"basics-m1-23","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"经核准的基金份额总额在基金合同期限内固定不变，基金份额可以在依法设立的证券交易场所交易，但基金份额持有人不得申请赎回的基金是指（　）。","options":["公司型基金","封闭式基金","被动型基金","开放式基金"],"answer":"B","explain":"封闭式基金份额固定，可在交易所交易，但不得赎回。"},{"id":"basics-m1-24","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"金融衍生工具产生的最基本原因是（　）。","options":["新技术革命","金融自由化","利润驱动","避险"],"answer":"D","explain":"避险是金融衍生工具产生的最基本原因。"},{"id":"basics-m1-25","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"根据我国现行有关制度的规定，过户费一部分属于（　）的收入，一部分由证券公司留存。","options":["国家税收部门","中国证监会","中国结算公司","证券交易所"],"answer":"C","explain":"过户费一部分属于中国结算公司的收入。"},{"id":"basics-m1-26","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"沪、深证券交易所对股票交易实行价格涨跌幅限制，涨跌幅比例为（　）。","options":["5%","8%","10%","15%"],"answer":"C","explain":"沪深股票涨跌幅限制为10%。"},{"id":"basics-m1-27","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"小何想要建立一家企业充分发挥自身才能，但是由于资金不足，想要通过发行股票的方式筹集资金，那么小何可以选择建立的企业的组织形式为（　）。","options":["个人独资企业","合伙企业","有限责任公司","股份有限公司"],"answer":"D","explain":"只有股份有限公司才能发行股票。"},{"id":"basics-m1-28","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"如果中央银行调高贴现率，则会（　）。","options":["使商业银行的借入资金成本降低","使商业银行降低贷款利率","扩大企业的借贷需求","减少贷款量和货币供应量"],"answer":"D","explain":"调高贴现率会提高商业银行融资成本，减少贷款和货币供应量。"},{"id":"basics-m1-29","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"整个证券市场的核心是（　）。","options":["证券发行人","证券交易所","中国证监会","国务院"],"answer":"B","explain":"证券交易所是整个证券市场的核心。"},{"id":"basics-m1-30","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"风险投资企业以让渡企业的部分股权换取企业经营资金的资金融通方式是（　）。","options":["股票市场融资","债券市场融资","风险投资融资","商业信用融资"],"answer":"C","explain":"风险投资融资是以股权换取经营资金。"},{"id":"basics-m1-31","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"全国中小企业股份转让系统中挂牌股票采取做市转让方式的，须有（　）家以上从事做市业务的主办券商为其提供做市报价服务。","options":["3","2","1","5"],"answer":"B","explain":"做市转让方式需2家以上做市商。"},{"id":"basics-m1-32","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"A公司当年的净资产收益率为 75%，已知当年的销售利润率为 25%，资产周转率为2，那么杠杆比率为（　）。","options":["3","0.375","1.5","0.67"],"answer":"C","explain":"杠杆比率=ROE/(销售利润率×资产周转率)=75%/(25%×2)=1.5"},{"id":"basics-m1-33","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"普通股股东在股份公司解散清算时，有权要求取得公司按规定清偿后的（　）。","options":["银行存款","注册资本","剩余财产","剩余资金"],"answer":"C","explain":"股东享有剩余资产分配权，即清偿后的剩余财产。"},{"id":"basics-m1-34","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"国家开发银行、中国进出口银行、中国农业发展银行具备发行（　）的条件，经中国人民银行核准后便可发行。","options":["公司债券","金融债券","企业债券","混合资本债券"],"answer":"B","explain":"三家政策性银行具备发行金融债券的条件。"},{"id":"basics-m1-35","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"1965年，特雷诺在美国《哈佛商业评论》上发表《如何评价投资基金的答理》一文，首次提出一种评价基金业绩的综合指标，即特雷诺指数。该指数值越大，基金的绩效表现（　）。","options":["越好","越差","与之无关","可能越好，也可能越差"],"answer":"A","explain":"特雷诺指数越大，基金绩效表现越好。"},{"id":"basics-m1-36","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"企业成长周期中不包括（　）。","options":["创立期","成熟期","衰退期","稳定期"],"answer":"D","explain":"企业成长周期包括创立期、成长期、成熟期和衰退期，没有稳定期。"},{"id":"basics-m1-37","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"金融资产的持有者为了资金安全而进行资金调拨所形成的国际资金流动被称为（　）。","options":["投机性资金流动","保值性资金流动","国际间接投资","套利性资金流动"],"answer":"B","explain":"为了资金安全的资金调拨是保值性资金流动。"},{"id":"basics-m1-38","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"中期票据是（　）发行的债务融资工具。","options":["非金融企业","签发人","中国人民银行","出票人"],"answer":"A","explain":"中期票据由具有法人资格的非金融企业发行。"},{"id":"basics-m1-39","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下面关于证券公司的风险管理的三个发展阶段的说法错误的是（　）。","options":["在第一阶段，证券公司一般都没有设置专门的风险管理部门，面临的风险主要是操作风险，风险管理工作以散落在业务条线的内部控制为主","在第二阶段，证券公司已经基本上成立了独立的风险管理部，按照风险类型有针对性地开展风险管理工作","在第三阶段，压力测试作为风险评估的补充已经得到广泛应用","在第三阶段，全面风险管理规范的出台标志着证券公司风险管理进入到全面风险管理体系建设阶段"],"answer":"C","explain":"压力测试作为风险评估的补充是在第三阶段得到广泛应用，但题干问的是“说法错误”，C表述本身正确，但根据原卷答案，错误选项为C（因为第三阶段压力测试已广泛应用，但原题“说法错误”指向C，实际C描述正确，但依据原卷答案选C，此处保持一致）"},{"id":"basics-m1-40","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券发行人是指为筹措资金而发行债券、股票等证券的发行主体。证券发行人主要包括（　）。","options":["中央政府及其直属机构","金融机构","地方政府","企业（公司）"],"answer":"ABCD","explain":"证券发行人包括政府及其机构、金融机构、企业（公司）"},{"id":"basics-m1-41","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券市场是（　）等有价证券发行和交易的场所，是市场经济发展到一定阶段的产物，是为解决资本供求矛盾和流动性而产生的市场。","options":["股票","债券","证券投资基金","信托"],"answer":"ABC","explain":"证券市场交易对象包括股票、债券、证券投资基金，信托属于非证券金融市场"},{"id":"basics-m1-42","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"基金自身投资活动产生的税收有（　）。","options":["增值税","印花税","营业税","所得税"],"answer":"ABD","explain":"基金投资活动产生增值税、印花税、所得税，营业税已取消"},{"id":"basics-m1-43","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"保荐人的保荐责任期包括（　）。","options":["发行上市全过程","对发行的股票承担终身责任","发行上市后一段时间","递交上市申请材料期间"],"answer":"AC","explain":"保荐责任期包括发行上市全过程及上市后一段时间"},{"id":"basics-m1-44","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列关于证券公司缴纳证券投资者保护基金的说法，正确的有（　）。","options":["各证券公司的具体缴纳比例由证券投资者保护基金公司根据证券公司风险状况确定后，报中国证监会批准，并按年进行调整","从事证券经纪业务的证券公司，按照佣金收入的一定比例按季提取和预缴，不得由中国证券登记结算有限责任公司代扣代收","不从事证券经纪业务的证券公司，应在每季结束后10个工作日内按该季度营业收入和事先核定的比例预先提取但不预缴","经营管理或运作水平较差、风险较高的证券公司，应当按较高比例缴纳。证券公司缴纳的证券投资者保护基金在其营业成本中列支"],"answer":"AD","explain":"B错在可以代扣代收；C错在应预缴"},{"id":"basics-m1-45","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"银行间债券市场成员根据其是否与中央债券簿记系统直接联网办理债券结算业务而分为直接结算成员和间接结算成员。其中，间接结算成员主要是（　）。","options":["中小金融机构","存款类金融机构","非金融机构","大型金融机构"],"answer":"AC","explain":"间接结算成员主要是中小金融机构和非金融机构"},{"id":"basics-m1-46","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"以下关于可转换债券要素的叙述，正确的是（　）。","options":["可转换债券要素基本决定了可转换债券的转换条件、转换价值、市场价格等总体特征","可转换公司债的票面利率一般高于相同条件的不可转换公司债券","转换比例是指一定面额可转换债券可转换成优先股的股数","赎回条款和回售条款是可转换债券发行时规定的赎回行为和回售行为发生的具体市场条件"],"answer":"AD","explain":"B错在票面利率一般低于；C错在转换成普通股"},{"id":"basics-m1-47","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"货币政策的最终目标包括（　）。","options":["促进国际化","稳定物价","促进经济增长","促进证券市场发展"],"answer":"BC","explain":"货币政策最终目标包括稳定物价、经济增长、充分就业、国际收支平衡、金融稳定"},{"id":"basics-m1-48","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"按收益保障性分类，结构化金融衍生产品可分为（　）。","options":["保证最高收益型产品","非收益保证型产品","保证适中收益型产品","保本型产品"],"answer":"BD","explain":"分为收益保证型（含保本型）和非收益保证型"},{"id":"basics-m1-49","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"我国证券市场经过20多年的发展，逐步形成了以（　）为一体的监管体系和自律管理体系。","options":["国务院证券监督管理机构及派出机构","证券投资者保护基金公司","证券交易所","证券业协会"],"answer":"ABCD","explain":"监管体系包括证监会及派出机构、投资者保护基金、证券交易所、证券业协会"},{"id":"basics-m1-50","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"普通股股东的义务有（　）。","options":["应当遵守法律、行政法规和公司章程","依法行使股东权利","不得滥用股东权利损害公司或其他股东利益","不得滥用公司法人独立地位和股东有限责任损害公司债权人的利益"],"answer":"ABCD","explain":"均为普通股股东的义务"},{"id":"basics-m1-51","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"报价系统的核心功能包括（　）。","options":["私募产品发行","所有产品的报价","信息服务","登记结算"],"answer":"ACD","explain":"核心功能不包括所有产品报价，而是私募产品报价"},{"id":"basics-m1-52","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"托管银行的主要职责包括（　）。","options":["保管ADR所代表的基础证券","向ADR持有者提供基础证券发行人及ADR的市场信息，解答投资者的询问","根据存券银行的指令领取红利或利息","向存券银行提供当地市场信息"],"answer":"ACD","explain":"B是存券银行的职责"},{"id":"basics-m1-53","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"金融业区域内短期资金成本的基准指标包括（　）。","options":["SHIBOR","HIBOR","EURIBOR","TIBOR"],"answer":"ABCD","explain":"均为区域短期资金成本基准指标"},{"id":"basics-m1-54","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"股票投资的主要分析方法包括（　）。","options":["基本分析法","定性分析法","技术分析法","量化分析法"],"answer":"ACD","explain":"股票分析方法有基本分析法、技术分析法、量化分析法"},{"id":"basics-m1-55","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"封闭式基金账户可用于（　）的认购和交易。","options":["基金","国债","企业债券","公司股票"],"answer":"ABC","explain":"基金账户可用于基金、国债及其他债券的认购和交易"},{"id":"basics-m1-56","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"影响国债销售价格的因素有（　）。","options":["市场利率","承销商承销国债的中标成本","流通市场中可比国债的收益率水平","国债承销的手续费收入"],"answer":"ABCD","explain":"均为影响国债销售价格的因素"},{"id":"basics-m1-57","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"政府发行中期国债筹集的资金用于（　）。","options":["临时周转","弥补赤字","投资","调节经济"],"answer":"BC","explain":"中期国债用于弥补赤字或投资"},{"id":"basics-m1-58","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"关于股票的票面价值，下列说法中错误的是（　）。","options":["股票的票面价值又称面值，即股票交易时的价格","发行价格高于票面价值称为溢价发行，募集的资金中等于面值总和的部分计入资本账户，以超过股票票面金额的发行价格发行股份所得的溢价款列为公司资本公积金","如果以票面价值作为发行价，称为平价发行","股票的票面价值在初次发行时没有参考意义"],"answer":"AD","explain":"A错在票面价值不是交易价格；D错在初次发行时有参考意义"},{"id":"basics-m1-59","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"在我国，基金性质的机构投资者包括（　）。","options":["证券投资基金","社保基金","社会公益基金","企业年金"],"answer":"ABCD","explain":"均为基金性质的机构投资者"},{"id":"basics-m1-60","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"根据证券化的基础资产不同，可以将资产证券化分为（　）。","options":["不动产证券化","应收账款证券化","信贷资产证券化","未来收益证券化"],"answer":"ABCD","explain":"包括不动产、应收账款、信贷资产、未来收益证券化"},{"id":"basics-m1-61","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"金融衍生工具伴随的风险主要包括（　）。","options":["汇率风险、利率风险","信用风险、法律风险","市场风险、操作风险","流动性风险、结算风险"],"answer":"BCD","explain":"金融衍生工具风险包括信用、市场、流动性、结算、操作、法律风险"},{"id":"basics-m1-62","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列属于操作风险管理关注的重点领域和环节的是（　）。","options":["定期或不定期开展风险与控制自我评估","根据关键风险指标监测结果，评估操作风险状况与操作风险管理措施的执行效果","建立公司主要业务与管理活动的流程目录并持续更新和完善，并在流程目录的基础上识别操作风险点","通过分析内外部风险事件开展操作风险识别与评估"],"answer":"ABCD","explain":"均为操作风险管理关注的重点领域和环节"},{"id":"basics-m1-63","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"分析公司财务状况，重点在于研究公司的（　）。","options":["盈利性","安全性","流动性","可持续发展性"],"answer":"ABC","explain":"分析财务状况重点在于盈利性、安全性、流动性"},{"id":"basics-m1-64","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"国际证券市场上著名的股价指数有（　）。","options":["纳斯达克（NASDAQ）指数","日经平均股价指数","金融时报证券交易所指数","道·琼斯工业股价平均数"],"answer":"ABCD","explain":"均为国际著名股价指数"},{"id":"basics-m1-65","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司经理层对全面风险管理承担主要责任，应当履行的职责包括（　）。","options":["制定风险管理制度，并适时调整","建立健全公司全面风险管理的经营管理架构","建立涵盖风险管理有效性的全员绩效考核体系","建立完备的信息技术系统和数据质量控制机制"],"answer":"ABCD","explain":"均为经理层风险管理职责"},{"id":"basics-m1-66","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列属于用来转移或防范信用风险的金融衍生工具的有（　）。","options":["利率互换","信用联结票据","信用互换","保证金互换"],"answer":"BC","explain":"信用联结票据和信用互换用于转移或防范信用风险"},{"id":"basics-m1-67","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列关于外商开展私募基金业务的说法，正确的是（　）。","options":["经中国证监会同意，外商独资和合资私募证券基金管理机构在中国境内开展私募证券基金管理业务，应当在中国证券投资基金业协会登记为私募证券基金管理人","外商独资和合资私募证券基金管理机构开展私募证券投资基金业务，在境内从事证券及期货交易，应当独立进行投资决策，可以通过境外机构或者境外系统下达交易指令","外商独资和合资私募证券基金管理机构提供的登记申请材料完备的，中国证券投资基金业协会将自收齐材料之日起20个工作日内，以通过协会官方网站公示私募基金管理人基本情况的方式，为其办结登记手续","外商独资和合资私募证券基金管理机构登记后，应当依法及时展业"],"answer":"ACD","explain":"B错在不得通过境外机构或系统下达交易指令"},{"id":"basics-m1-68","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"关于有面额股票和无面额股票的说法中，正确的是（　）。","options":["同次发行的有面额股票的每股票面金额是相等的","我国股票发行价格可以按票面金额，也可以超过票面金额或低于票面金额","无面额股票也被称为比例股票","无面额股票只注明它在公司总股本中所占的比例"],"answer":"ACD","explain":"B错在我国发行价格不得低于票面金额"},{"id":"basics-m1-69","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"信用违约互换的危险来自（　）。","options":["具有较高杠杆性","信用保护的买方并不需要真正持有作为参考的信用工具","场外市场缺乏充分的信息披露和监管，交易者并不清楚自己的交易对手卷入了多少此类交易","期货价格与未来的现货价格之间可能存在一定的偏离"],"answer":"ABC","explain":"危险来自高杠杆、不必持有参考工具、场外信息披露不足"},{"id":"basics-m1-70","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列关于10年期国债期货合约的说法中，正确的是（　）。","options":["上市的10年期国债期货合约交易代码为T","实行实物交割","标的为面值1000万元人民币、票面利率6%的名义长期国债","挂牌合约为最近的三个季月，每日最大波动幅度为前一交易日结算价的上下2%"],"answer":"ABD","explain":"C错在标的为面值100万元、票面利率3%"},{"id":"basics-m1-71","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"当证券投资者保护基金有限责任公司发现证券公司经营管理中出现可能危及（　）的重大风险时，应当及时向有关部门提出监管、处置建议。","options":["投资者利益","证券公司利益","监管部门利益","证券市场安全"],"answer":"AD","explain":"危及投资者利益和证券市场安全"},{"id":"basics-m1-72","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"境内居民个人可以用（　）从事B股交易。","options":["外币现钞","从境外汇入的外汇资金","外币现钞存款","现汇存款"],"answer":"BCD","explain":"不允许使用外币现钞"},{"id":"basics-m1-73","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"保证公司债券的担保人可以是（　）。","options":["政府","信誉好的银行","发行人自身","举债公司的母公司"],"answer":"ABD","explain":"担保人必须是发行人以外的第三方"},{"id":"basics-m1-74","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"债券投资风险相对低于股票投资，是因为（　）。","options":["债券利息是公司固定支出，属于费用范围；股票的股息红利是公司利润一部分，公司有盈利才能支付","倘若公司破产，清理资产有余额偿还时，债券偿付在前，股票偿付在后","在二级市场上，债券因其利率固定、期限固定，市场价格也较稳定；而股票无固定期限和利率，市场价格波动频繁","债券的投资收益高于股票"],"answer":"ABC","explain":"D错在股票收益通常高于债券"},{"id":"basics-m1-75","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列选项中，属于基金运作费的有（　）。","options":["审计费","律师费","过户费","经手费"],"answer":"AB","explain":"审计费、律师费属于基金运作费；过户费、经手费属于交易费"},{"id":"basics-m1-76","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"可以作为金融衍生工具的变量有（　）。","options":["利率","股票价格指数","汇率","气温"],"answer":"ABCD","explain":"利率、股价指数、汇率、气温均可作为衍生工具变量"},{"id":"basics-m1-77","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"下列对我国金融市场的发展现状的描述中，正确的是（　）。","options":["“大一统”的单一银行体系","交易场所多层次","交易品种多样化","交易机制多元化"],"answer":"BCD","explain":"A是改革前的特征"},{"id":"basics-m1-78","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券市场监管的意义有（　）。","options":["加强证券市场监管是保障广大投资者权益的需要","加强证券市场监管是维护市场良好秩序的需要","加强证券市场监管是发展和完善证券市场体系的需要","准确全面的信息是证券市场参与者进行发行和交易决策的重要依据"],"answer":"ABCD","explain":"均为证券市场监管的意义"},{"id":"basics-m1-79","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券公司的融资管理应符合以下要求（　）。","options":["分析正常和压力情景下未来不同时间段的融资需求和来源","加强负债品种期限、交易对手、融资抵（质）押品和融资市场等的集中管理，适当设置集中度限额","加强融资渠道管理，积极维护与主要融资交易对手的关系，保持在市场上适当活跃程度，并定期评估市场融资和资产变现能力","密切监测主要金融市场的交易量和价格等变动情况，评估市场流动性对公司融资能力的影响"],"answer":"ABCD","explain":"均为融资管理要求"},{"id":"basics-m1-80","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"中国存托凭证是指由存托人签发、以境外证券为基础在中国境内发行、代表境外基础证券权益的证券。其参与主体主要包括发行人、存托人、托管人。（　）","options":["正确","错误"],"answer":"B","explain":"参与主体还包括持有人"},{"id":"basics-m1-81","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"现代金融市场以有形市场为主。（　）","options":["正确","错误"],"answer":"B","explain":"现代金融市场往往是无形的"},{"id":"basics-m1-82","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"SPV不是资产支持证券的真正发行人。（　）","options":["正确","错误"],"answer":"B","explain":"SPV是资产支持证券的真正发行人"},{"id":"basics-m1-83","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"1988年以前，我国国债采用行政分配方式发行。（　）","options":["正确","错误"],"answer":"A","explain":"1988年以前国债采用行政分配方式"},{"id":"basics-m1-84","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券中介机构包括证券公司和其他证券服务机构两类。（　）","options":["正确","错误"],"answer":"A","explain":"证券中介机构包括证券公司和证券服务机构"},{"id":"basics-m1-85","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"按业务特征及货币创造、交换媒介和支付手段的能力划分，金融中介机构可以划分为商业性金融机构和政策性金融机构。（　）","options":["正确","错误"],"answer":"B","explain":"应划分为银行金融中介机构和非银行金融中介机构"},{"id":"basics-m1-86","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"目前，中国香港的主要金融监管机构包括：香港金融管理局、证券及期货事务监察委员会、保险业监理处、银监会。（　）","options":["正确","错误"],"answer":"B","explain":"香港没有银监会"},{"id":"basics-m1-87","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"流动性风险是因市场价格变量波动而给经济主体带来损益的风险。（　）","options":["正确","错误"],"answer":"B","explain":"那是市场风险的定义"},{"id":"basics-m1-88","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"我国的证券登记结算制度包括证券实名制、货银对付的交收制度、无负债结算制度。（　）","options":["正确","错误"],"answer":"B","explain":"没有无负债结算制度，应为分级结算、净额结算等"},{"id":"basics-m1-89","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"基金管理人是基金的募集者和管理者。（　）","options":["正确","错误"],"answer":"A","explain":"基金管理人是募集者和管理者"},{"id":"basics-m1-90","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券投资基金在中国的台湾地区称为集合投资基金。（　）","options":["正确","错误"],"answer":"B","explain":"台湾地区称为证券投资信托基金"},{"id":"basics-m1-91","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"信用打分模型的关键在于关键变量的选择和各自权重的确定。（　）","options":["正确","错误"],"answer":"A","explain":"信用打分模型的关键在于变量选择和权重确定"},{"id":"basics-m1-92","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"理事会会议至少每半年召开一次。（　）","options":["正确","错误"],"answer":"B","explain":"理事会会议至少每季度召开一次"},{"id":"basics-m1-93","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"市场流动性是从单个机构的流动性需求出发，将流动性理解为企业尤其是金融机构保证经营以及正常支付的能力。（　）","options":["正确","错误"],"answer":"B","explain":"那是机构流动性的定义"},{"id":"basics-m1-94","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"我国创业板市场于2007年在深圳证券交易所正式启动。（　）","options":["正确","错误"],"answer":"B","explain":"创业板于2009年启动"},{"id":"basics-m1-95","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"目前，除了国债（包括附息国债和地方债）和企业债可以跨市场转托管，其他债券品种（包括公司债、证券公司次级债、中小企业私募债）都不能跨市场转托管。（　）","options":["正确","错误"],"answer":"A","explain":"只有国债和企业债可以跨市场转托管"},{"id":"basics-m1-96","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"中国证券登记结算有限责任公司是金融债券的登记、托管机构。（　）","options":["正确","错误"],"answer":"B","explain":"中央国债登记结算有限责任公司是金融债券的登记、托管机构"},{"id":"basics-m1-97","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"根据《北京证券交易所交易规则（试行）》，在北京证券交易所交易的股票实行价格涨跌幅限制，涨跌幅限制比例为20%。（　）","options":["正确","错误"],"answer":"B","explain":"涨跌幅限制比例为30%"},{"id":"basics-m1-98","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"按照交易工具，可以将金融市场划分为债权市场和权益市场。（　）","options":["正确","错误"],"answer":"A","explain":"按交易工具分为债权市场和权益市场"},{"id":"basics-m1-99","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"九号有限公司成为科创板首家发行CDR的公司。（　）","options":["正确","错误"],"answer":"A","explain":"九号有限公司是科创板首家发行CDR的公司"},{"id":"basics-m1-100","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"长期国债的偿还期限一般为15年以上。（　）","options":["正确","错误"],"answer":"B","explain":"长期国债偿还期限为10年以上"},{"id":"basics-m1-101","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"保值性资金的流动是期限在1年以上的资金的跨国流动。（　）","options":["正确","错误"],"answer":"B","explain":"保值性资金流动是短期资金流动，期限1年或以下"},{"id":"basics-m1-102","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"证券分析中，基本面分析包括宏观经济和证券市场运行情况、行业前景以及公司经营状况。（　）","options":["正确","错误"],"answer":"A","explain":"基本面分析涵盖宏观经济、行业、公司经营"},{"id":"basics-m1-103","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"股票分割又称拆股、拆细，股票分割之后，每股股票的市价不变。（　）","options":["正确","错误"],"answer":"B","explain":"拆细后每股股价下降"},{"id":"basics-m1-104","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"投资人可通过办理转托管业务，实现其变更办理基金业务销售渠道的需要。（　）","options":["正确","错误"],"answer":"A","explain":"转托管可用于变更销售渠道"},{"id":"basics-m1-105","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"某投资者买入一份欧式期权，则他可以在到期日行使自己的权利。（　）","options":["正确","错误"],"answer":"A","explain":"欧式期权只能在到期日行使"},{"id":"basics-m1-106","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"可转换债券通常是指证券持有者可以在一定时期内按一定比例或价格将它转换成一定数量的普通股票。（　）","options":["正确","错误"],"answer":"A","explain":"可转换债券可转换成普通股票"},{"id":"basics-m1-107","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"创业板投资者交易权限需要开通前20个交易日资产日均不低于人民币30万元，并具有2年的证券交易经验。（　）","options":["正确","错误"],"answer":"B","explain":"资产日均不低于10万元"},{"id":"basics-m1-108","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"股票的未来潜在价值决定股票市场价格。（　）","options":["正确","错误"],"answer":"B","explain":"内在价值决定市场价格"},{"id":"basics-m1-109","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 提分密训卷一","q":"审慎管理原则要求证券公司应主动识别和防范声誉风险，加强对声誉风险的发生原因、影响程度、发展变化的分析和预测，及时作出应对。（　）","options":["正确","错误"],"answer":"B","explain":"那是预防第一原则，审慎管理原则要求审慎评估判断"},{"id":"basics-m1-110","subject":"basics","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】假定某公司在未来每期支付的每股股息为8元，必要收益率为10%，此时市场该股票价格为65元。根据以上信息，回答以下问题：\n\n【问题】（1）该股票此时价值被（　），投资者对于该股票的投资决策应该为（　）","options":["高估，卖出","低估，买入","低估，卖出","高估，买入"],"answer":"B","explain":"净现值=8/10%-65=15>0，被低估，应买入"},{"id":"basics-m1-111","subject":"basics","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】假定某公司在未来每期支付的每股股息为8元，必要收益率为10%，此时市场该股票价格为65元。根据以上信息，回答以下问题：\n\n【问题】（2）该股票的内部收益率为（　）","options":["8%","10%","12.3%","不确定"],"answer":"C","explain":"内部收益率=8/65×100%=12.3%"},{"id":"basics-m1-112","subject":"basics","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】假定某公司在未来每期支付的每股股息为8元，必要收益率为10%，此时市场该股票价格为65元。根据以上信息，回答以下问题：\n\n【问题】（3）关于零增长模型与内部收益率的说法，正确的是（　）。","options":["内部收益率就是指使得投资净现值等于零的折现","如果股票的内部收益率 > 必要收益率，则可以考虑购买这种股票","如果股票的内部收益率 > 必要收益率，则不要购买这种股票","在确定优先股的内在价值时零增长模型更有用"],"answer":"ABD","explain":"C错在内部收益率>必要收益率时应购买"},{"id":"basics-m1-113","subject":"basics","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】甲股份公司拟向社会公众公开发行股票并上市，该公司发行前注册资本为2.4亿元，公司没有内部职工股。根据以上信息，回答以下问题：\n\n【问题】（1）根据《上市公司证券发行注册管理办法》，上市公司不得向不特定对象发行股票的情形包括（　）。","options":["擅自改变前次募集资金用途未作纠正","上市公司员最近三年受到中国证监会行政处罚","实际控制人最近三年存在严重损害上市公司利益的重大违法行为","上市公司最近一年存在未履行向投资者作出的公开承诺的情形"],"answer":"ABCD","explain":"均为不得向不特定对象发行的情形"},{"id":"basics-m1-114","subject":"basics","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】甲股份公司拟向社会公众公开发行股票并上市，该公司发行前注册资本为2.4亿元，公司没有内部职工股。根据以上信息，回答以下问题：\n\n【问题】（2）若每股股价1元，则其首次发行的普通股数量不得少于（　）。","options":["1800万股","3000万股","6000万股","3200万股"],"answer":"C","explain":"公开发行比例不低于25%，2.4亿×25%=6000万股"},{"id":"basics-m1-115","subject":"basics","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】A公司发行一种开放式基金，该基金的认购费率为1.20%，基金的认购费用将统一按净认购金额为基础收取。根据以上信息，回答以下问题：\n\n【问题】（1）关于开放式基金的特点，以下说法正确的是（　）。","options":["开放式基金的基金规模是固定的","开放式基金的买卖价格受市场供求关系的影响","开放式基金更便于基金经理进行长期投资和全额投资安排","开放式基金没有固定期限，投资者可向基金管理人申购、赎回基金份额"],"answer":"D","explain":"开放式基金规模不固定，以净值交易，便于申购赎回"},{"id":"basics-m1-116","subject":"basics","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】A公司发行一种开放式基金，该基金的认购费率为1.20%，基金的认购费用将统一按净认购金额为基础收取。根据以上信息，回答以下问题：\n\n【问题】（2）张某投资100000元认购本基金，其认购费用为（　）元。","options":["1600","1185.77","962.7","1000"],"answer":"B","explain":"净认购金额=100000/(1+1.2%)=98814.23，认购费=100000-98814.23=1185.77"},{"id":"basics-m1-117","subject":"basics","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】A公司为上市公司，其股票可以在证券交易所上市交易，A公司的每股销售收入是5元，A公司的可比公司B公司的市销率为0.8。但由于该公司的出现一些问题面临强制退市的风险。根据以上信息，回答以下问题：\n\n【问题】（1）A公司申请公开发行股票并采取承销方式，应当聘请（　）担任保荐人。","options":["证券公司","财务集团","商业银行","证券投资咨询机构"],"answer":"A","explain":"保荐人应当由证券公司担任"},{"id":"basics-m1-118","subject":"basics","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】A公司为上市公司，其股票可以在证券交易所上市交易，A公司的每股销售收入是5元，A公司的可比公司B公司的市销率为0.8。但由于该公司的出现一些问题面临强制退市的风险。根据以上信息，回答以下问题：\n\n【问题】（2）王某购买了A公司股票，由于做生意急需资金，王某将股票转卖给了丁某而非向A公司要求退股，这是由于股票的（　）特性。","options":["参与性","风险性","永久性","流动性"],"answer":"C","explain":"股票具有永久性，股东不能要求退股，只能转让"},{"id":"basics-m1-119","subject":"basics","type":"案例","source":"2026.09 乐橙密训 · 提分密训卷一","q":"【资料】A公司为上市公司，其股票可以在证券交易所上市交易，A公司的每股销售收入是5元，A公司的可比公司B公司的市销率为0.8。但由于该公司的出现一些问题面临强制退市的风险。根据以上信息，回答以下问题：\n\n【问题】（3）关于强制退市，下列说法正确的是（　）。","options":["根据《上海证券交易所股票上市规则（2025年4月修订）》《深圳证券交易所股票上市规则（2025年4月修订）》，强制退市分为交易类强制退市、财务类强制退市、规范类强制退市和重大违法类强制退市四类情形","科创板上市公司的股票终止上市后，符合上交所规定条件的，可以向上交所申请重新上市","“上市公司存在欺诈发行、重大信息披露违法或者其他严重损害证券市场秩序的重大违法行为，且严重影响上市地位，其股票应当被终止上市的情形”属于重大违法类强制退市的情形","“因公司股本总额或股权分布发生变化，导致连续20个交易日不再具备上市条件，在规定期限内仍未解决”属于重大违法类强制退市的情形"],"answer":"ABC","explain":"D属于规范类强制退市，不是重大违法类"}]},{"id":"basics-mk","subject":"basics","name":"金融 · 模拟密卷","stats":{"单选":20,"多选":10,"判断":10,"案例":6},"questions":[{"id":"basics-mk-0","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"既是基金的当事人，又是基金的主要服务机构的是（）。","options":["基金评价机构","基金份额持有人","基金托管人","基金投资顾问机构"],"answer":"C","explain":"基金管理人和基金托管人，既是基金当事人，也是基金主要服务机构。基金评价机构、基金投资顾问机构仅属于基金服务机构，不属于当事人；基金份额持有人是当事人，但不属于服务机构。"},{"id":"basics-mk-1","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"金融市场被称作经济运行的“晴雨表”，体现金融市场的（）功能。","options":["促进储蓄‑投资转化","优化资源配置","反映经济状态","宏观调控"],"answer":"C","explain":"反映经济状态：金融市场是实体经济的晴雨表，金融市场繁荣对应实体经济兴旺，市场萧条对应实体经济不景气。促进储蓄‑投资转化是把闲置资金转为投资；优化资源配置是资金流向高效率主体；宏观调控是政府借助市场调节经济。"},{"id":"basics-mk-2","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"某证券投资基金总资产44.06亿元，负债0.97亿元，总份额46.8亿份，则基金份额净值为（）元。","options":["0.94","0.93","0.92","0.96"],"answer":"C","explain":"基金资产净值=基金总资产‑基金负债=44.06‑0.97=43.09亿元；基金份额净值=基金资产净值÷基金总份额=43.09÷46.8=0.92元。"},{"id":"basics-mk-3","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"伦敦证券交易所中，为流动性较差证券提供交易服务的系统是（）。","options":["SETS系统","SETSqx系统","IOB系统","SEAQ系统"],"answer":"B","explain":"SETSqx服务流动性相对弱的证券，二板股票、非富时指数成分股；SETS是旗舰电子指令簿；IOB用于存托凭证；SEAQ是做市商报价系统。"},{"id":"basics-mk-4","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"关于债券当期收益率，说法正确的是（）。","options":["既反映年利息收益，也反映资本损益","零息债券可方便计算当期收益率","不同期限附息债券，不能只依靠当期收益率评判优劣","当期收益率=债券总利息收益÷债券面值"],"answer":"C","explain":"当期收益率=年利息收入÷债券购买市价；只反映利息收益，不反映资本损益；零息债券没有利息，无法计算当期收益率；不同期限债券不能单纯对比当期收益率。"},{"id":"basics-mk-5","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"中央政府发行的国债一般被视作（）。","options":["高风险债券","低风险债券","无风险债券","一般风险债券"],"answer":"C","explain":"中央政府债券以国家信用为保障，几乎不存在违约风险，被称为无风险债券，其收益率作为金融市场无风险利率基准。"},{"id":"basics-mk-6","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"我国H股、N股、S股属于（）。","options":["红筹股","境外上市外资股","社会公众股","境内上市外资股"],"answer":"B","explain":"境外上市外资股：境内企业向境外投资者募集，在境外上市；H（香港）、N（纽约）、S（新加坡）。B股是境内上市外资股；红筹股是境外注册、香港上市、业务在内地的企业。"},{"id":"basics-mk-7","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"战略投资者获得配售股票，锁定期要求（）。","options":["6个月以上","12个月以上","1个月以上","3个月以上"],"answer":"B","explain":"战略投资者应当承诺配售股票持有期限不少于12个月，锁定期自证券上市之日起计算。"},{"id":"basics-mk-8","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"我国债券市场的主体是（）。","options":["银行间债券市场","交易所市场","企业债市场","商业银行柜台市场"],"answer":"A","explain":"银行间债券市场是国内债券市场主体，参与主体以银行、保险等机构投资者为主。"},{"id":"basics-mk-9","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"世界上最早的证券交易所是（）。","options":["纽约证券交易所","费城证券交易所","阿姆斯特丹证券交易所","伦敦证券交易所"],"answer":"C","explain":"1602年荷兰设立阿姆斯特丹证券交易所，是全球第一家证券交易所。"},{"id":"basics-mk-10","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"上市企业大多为大型成熟企业，资本规模大、盈利稳定，该市场是（）。","options":["主板市场","创业板市场","科创板市场","场外市场"],"answer":"A","explain":"主板对股本、盈利、经营期限门槛高，上市主体多为大型成熟企业；创业板、科创板服务成长型创新创业企业。"},{"id":"basics-mk-11","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"股票清算价值指（）。","options":["股票日常二级市场的交易价格","公司清算时每一股份代表的实际价值","公司破产时股票的发行价格","股票的账面价值"],"answer":"B","explain":"股票清算价值：公司破产清算时，每一股份代表的实际价值。现实中资产处置通常折价，清算价值大多低于账面价值。"},{"id":"basics-mk-12","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"非公开募集基金募集完毕，基金管理人应当向（）办理备案。","options":["中国人民银行","证监会派出机构","中国证监会","中国证券投资基金业协会"],"answer":"D","explain":"私募基金募集完毕，管理人向基金业协会履行备案登记。"},{"id":"basics-mk-13","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"下列选项，不属于货币市场的是（）。","options":["股票市场","同业拆借市场","商业票据市场","大额可转让定期存单市场"],"answer":"A","explain":"货币市场是期限1年以内短期资金市场；股票属于资本市场（长期）。"},{"id":"basics-mk-14","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"股票高于票面面值发行，称为（）。","options":["溢价发行","折价发行","平价发行","配额发行"],"answer":"A","explain":"溢价发行：发行价格＞面值；平价=面值；折价＜面值，我国股票不允许折价发行。"},{"id":"basics-mk-15","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"交易双方约定未来某一日，交换名义本金基础上合同利率、参考利率计算利息的合约是（）。","options":["远期汇率协议","债权远期合约","股权远期合约","远期利率协议"],"answer":"D","explain":"远期利率协议，只交换利息差额，不交换本金，用来管理利率波动风险。"},{"id":"basics-mk-16","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"按债券券面形态分类，不包括（）。","options":["记账式债券","实物债券","凭证式债券","息票累积债券"],"answer":"D","explain":"按券面形态：实物、凭证式、记账式。息票累积债券属于按付息方式分类。"},{"id":"basics-mk-17","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"武士债券的计价货币是（）。","options":["美元","日元","港币","欧元"],"answer":"B","explain":"武士债券：外国发行人在日本发行、以日元计价的外国债券；扬基债券在美国发行，美元计价。"},{"id":"basics-mk-18","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"基金托管费是支付给（）的费用。","options":["基金托管人","基金管理人","证监会","基金份额持有人"],"answer":"A","explain":"托管费付给托管人，托管人保管基金资产；管理费支付给基金管理人。"},{"id":"basics-mk-19","subject":"basics","type":"单选","source":"2026.09 乐橙密训 · 模拟密卷","q":"证券交易所会员大会的职权包含（）。","options":["召集主持理事会会议","选举和罢免理事","制定业务交易规则","监督检查风险防控"],"answer":"B","explain":"会员大会是证券交易所最高权力机构，有权选举、罢免会员理事；理事长召集理事会；理事会制定业务规则。"},{"id":"basics-mk-20","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 模拟密卷","q":"按照基础工具种类，金融衍生工具分为（）。","options":["货币衍生工具","利率衍生工具","股权类衍生工具","信用衍生工具"],"answer":"ABCD","explain":"按基础工具分类：股权类、货币类、利率类、信用衍生工具，还有其他类衍生工具。"},{"id":"basics-mk-21","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 模拟密卷","q":"属于交易所市场的有（）。","options":["同业拆借市场","期货交易所","外汇场外市场","证券交易所"],"answer":"BD","explain":"交易所市场是集中场内交易：证券交易所、期货、期权交易所；拆借、传统外汇多属于场外OTC市场。"},{"id":"basics-mk-22","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 模拟密卷","q":"二级市场具备的功能包括（）。","options":["直接为企业筹资","为已发行证券提供流动性","资产价格发现","消除全部投资风险"],"answer":"BC","explain":"二级市场是流通市场：提供流动性、价格发现；一级市场承担筹资功能；二级市场不能消除全部风险。"},{"id":"basics-mk-23","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 模拟密卷","q":"优先股股东享有的优先权是（）。","options":["优先分配公司利润","日常经营重大事项完整表决权","优先分配清算剩余资产","参与公司日常经营管理"],"answer":"AC","explain":"优先股两大优先：利润分红优先、破产清算剩余财产优先；一般没有日常经营表决权，不参与经营。"},{"id":"basics-mk-24","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 模拟密卷","q":"商业银行借款负债渠道主要包含（）。","options":["向中央银行借款","同业借款","发行普通股股票","回购协议"],"answer":"ABD","explain":"借款负债：向央行借款、同业借款、回购协议、境外借款；发行股票属于权益资本，不属于借款负债。"},{"id":"basics-mk-25","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 模拟密卷","q":"股票市场融资的特点（）。","options":["无需归还本金","可以转让流通","持有人可以随意要求公司退股","保证固定投资收益"],"answer":"AB","explain":"股权融资：不用偿还本金，股份可以转让；股东不能要求公司退股；收益随企业经营浮动，不保证收益。"},{"id":"basics-mk-26","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 模拟密卷","q":"常见另类投资基金包含（）。","options":["对冲基金","股权投资基金","创业投资基金","不动产投资基金"],"answer":"ABCD","explain":"另类投资基金投资于传统股债以外资产：对冲基金、股权投资、创投基金、不动产基金、大宗商品基金等。"},{"id":"basics-mk-27","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 模拟密卷","q":"可交换债券与可转换债券的区别有（）。","options":["发债主体不同","转股股份来源不同","均一定会扩大上市公司总股本","交割方式完全一样"],"answer":"AB","explain":"可交换债发行人为上市公司股东，股份来自股东持有的存量股票，转股不扩大上市公司总股本；可转换债发行人是上市公司本身，转股发行新股，扩大总股本。"},{"id":"basics-mk-28","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 模拟密卷","q":"基金运作信息披露文件包括（）。","options":["基金份额上市交易公告书","基金份额发售公告","基金净值公告","基金定期报告（年报、半年报、季报）"],"answer":"ACD","explain":"运作信息披露：上市公告书、净值公告、定期报告；基金份额发售公告属于募集信息披露。"},{"id":"basics-mk-29","subject":"basics","type":"多选","source":"2026.09 乐橙密训 · 模拟密卷","q":"系统性风险一般具备哪些特征（）。","options":["内生性","关联性","复杂性","突发性"],"answer":"ABCD","explain":"系统性风险特征：内生性、关联性、复杂性、突发性、传染性，风险会扩散整个金融体系，无法通过分散投资消除。"},{"id":"basics-mk-30","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 模拟密卷","q":"ETF采用实物申购赎回机制，申购用一篮子股票换份额，赎回换回一篮子股票，不是现金。（）","options":["正确","错误"],"answer":"A","explain":"ETF实物申赎，大额申赎使用一篮子证券组合；二级市场可以现金买卖ETF份额。"},{"id":"basics-mk-31","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 模拟密卷","q":"封闭式基金每个交易日估值，并且每个交易日披露基金份额净值。（）","options":["正确","错误"],"answer":"B","explain":"封闭式基金每个交易日估值，每周披露一次份额净值，不是每日披露。"},{"id":"basics-mk-32","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 模拟密卷","q":"可转换债券自发行结束之日起，满6个月后才可以转换为公司股票。（）","options":["正确","错误"],"answer":"A","explain":"我国规则，可转债发行结束6个月后方可行使转股权。"},{"id":"basics-mk-33","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 模拟密卷","q":"特雷诺指数可以评价基金经理分散降低非系统性风险的能力。（）","options":["正确","错误"],"answer":"B","explain":"特雷诺指数以β衡量系统性风险，无法衡量非系统性风险分散效果；夏普指数衡量总风险。"},{"id":"basics-mk-34","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 模拟密卷","q":"除息除权日，一般为股权登记日后一个交易日。（）","options":["正确","错误"],"answer":"A","explain":"股权登记日收盘持有股票享有分红；除息除权日买入股票不再享有本次分红。"},{"id":"basics-mk-35","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 模拟密卷","q":"债券票面利率=债券年利息÷债券市场交易价格。（）","options":["正确","错误"],"answer":"B","explain":"票面利率=债券年利息÷债券面值；当期收益率=年利息÷市场购买价格。"},{"id":"basics-mk-36","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 模拟密卷","q":"风险补偿主要是事前的价格补偿。（）","options":["正确","错误"],"answer":"A","explain":"风险补偿，在交易定价事前加入风险溢价，承担风险获取额外收益，不是事后补偿。"},{"id":"basics-mk-37","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 模拟密卷","q":"政府债券信用等级最高，被称为金边债券。（）","options":["正确","错误"],"answer":"A","explain":"中央政府债券以国家信用担保，安全性最高，俗称金边债券。"},{"id":"basics-mk-38","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 模拟密卷","q":"区域性股权市场合格自然人投资者，金融资产不低于30万元。（）","options":["正确","错误"],"answer":"B","explain":"区域性股权市场自然人合格投资者，金融资产不低于50万元人民币。"},{"id":"basics-mk-39","subject":"basics","type":"判断","source":"2026.09 乐橙密训 · 模拟密卷","q":"金融互换是两个及以上当事人，约定时间定期交换现金流的金融交易。（）","options":["正确","错误"],"answer":"A","explain":"互换合约，约定定期交换现金流，常见利率互换、货币互换、收益互换。"},{"id":"basics-mk-40","subject":"basics","type":"案例","source":"2026.09 乐橙密训 · 模拟密卷","q":"【资料】案例背景一：存款货币乘数 法定存款准备金率r=20%； 情景1：货币政策调整前，超额准备金率e=5%；不考虑现金漏出（现金比率c=0，全部非现金结算）。客户李某存入原始现金存款10000元。 情景2：央行政策调整，取消超额准备金（e=0）；现金比率c=5%；客户王某存入原始现金存款30000元。 货币乘数通用公式：$m=\\dfrac{1+c}{c+r+e}$\n\n【问题】（单选，3分）政策调整前，李某存款对应的货币乘数是（）。","options":["20","4","6.67","5"],"answer":"B","explain":"c=0，r=20%，e=5%；m=1÷(0.2+0.05)=4。"},{"id":"basics-mk-41","subject":"basics","type":"案例","source":"2026.09 乐橙密训 · 模拟密卷","q":"【资料】案例背景一：存款货币乘数 法定存款准备金率r=20%； 情景1：货币政策调整前，超额准备金率e=5%；不考虑现金漏出（现金比率c=0，全部非现金结算）。客户李某存入原始现金存款10000元。 情景2：央行政策调整，取消超额准备金（e=0）；现金比率c=5%；客户王某存入原始现金存款30000元。 货币乘数通用公式：$m=\\dfrac{1+c}{c+r+e}$\n\n【问题】（单选，4分）政策调整后，王某原始存款能够创造的货币供给总量为（）万元。","options":["12.6","12","20","15"],"answer":"A","explain":"c=5%，r=20%，e=0；m=(1+0.05)÷(0.05+0.20+0)=1.05÷0.25=4.2；货币供给=原始存款×货币乘数=3万 ×4.2 =12.6万元。"},{"id":"basics-mk-42","subject":"basics","type":"案例","source":"2026.09 乐橙密训 · 模拟密卷","q":"【资料】案例背景一：存款货币乘数 法定存款准备金率r=20%； 情景1：货币政策调整前，超额准备金率e=5%；不考虑现金漏出（现金比率c=0，全部非现金结算）。客户李某存入原始现金存款10000元。 情景2：央行政策调整，取消超额准备金（e=0）；现金比率c=5%；客户王某存入原始现金存款30000元。 货币乘数通用公式：$m=\\dfrac{1+c}{c+r+e}$\n\n【问题】（多选，5分）关于货币乘数影响因素，说法正确的是（）。","options":["提高法定存款准备金率，货币乘数下降","降低超额准备金率，货币乘数上升","提高现金漏损率（现金比率），货币乘数下降","现金比率、法定准备金率与货币乘数呈反向变动"],"answer":"ABCD","explain":"法定存款准备金率r、超额准备金率e、现金比率c，三个数值越高，货币乘数越小；三者和货币乘数反向变动。"},{"id":"basics-mk-43","subject":"basics","type":"案例","source":"2026.09 乐橙密训 · 模拟密卷","q":"【资料】案例背景二：可转换债券 甲公司20×2年1月1日发行可转换债券，面值1000元，票面利率5%，转换价格45元；发行结束6个月后可以转股。20×1年末甲公司发生大额亏损。投资者乙拥有可转债，按照约定，有权把债券按本金加应付利息卖给发行人甲公司；投资者丙选择继续持有可转债。\n\n【问题】（单选，3分）投资者乙可以把债券回售给发行人，对应的条款是（）。","options":["赎回条款","回售条款","转换条款","修正条款"],"answer":"B","explain":"回售：投资者把债券卖给发行人（投资者主动）；赎回：发行人主动买回投资者手中债券。"},{"id":"basics-mk-44","subject":"basics","type":"案例","source":"2026.09 乐橙密训 · 模拟密卷","q":"【资料】案例背景二：可转换债券 甲公司20×2年1月1日发行可转换债券，面值1000元，票面利率5%，转换价格45元；发行结束6个月后可以转股。20×1年末甲公司发生大额亏损。投资者乙拥有可转债，按照约定，有权把债券按本金加应付利息卖给发行人甲公司；投资者丙选择继续持有可转债。\n\n【问题】（单选，2分）该可转债转换比例是（）。","options":["23.33","22.22","20.22","19.22"],"answer":"B","explain":"转换比例=可转债面值÷转换价格=1000÷45=22.22。"},{"id":"basics-mk-45","subject":"basics","type":"案例","source":"2026.09 乐橙密训 · 模拟密卷","q":"【资料】案例背景二：可转换债券 甲公司20×2年1月1日发行可转换债券，面值1000元，票面利率5%，转换价格45元；发行结束6个月后可以转股。20×1年末甲公司发生大额亏损。投资者乙拥有可转债，按照约定，有权把债券按本金加应付利息卖给发行人甲公司；投资者丙选择继续持有可转债。\n\n【问题】（单选，3分）该可转债最早可以转股时间为（）。","options":["20×2‑03‑01","20×2‑06‑01","20×2‑07‑01","20×2‑04‑01"],"answer":"C","explain":"20×2‑01‑01发行结束，满6个月即20×2‑07‑01起可行权转股。"}]}];
